-- FILE: /d/Products/athyper/server/db/sql/00_extensions/000_roles.sql
-- 00_extensions/000_roles.sql
-- Creates application roles required by RLS policies.
-- Must run before any RLS policy file (09_rls_policies/*).

DO $$ BEGIN
    CREATE ROLE athyperadmin NOLOGIN;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

COMMENT ON ROLE athyperadmin IS
    'Platform administrator role. Used by RLS policies across all schemas '
    'to grant unrestricted read/write access. NOLOGIN — granted to login roles.';

-- FILE: /d/Products/athyper/server/db/sql/00_extensions/001_extensions.sql
-- Case-insensitive text type for email, username, and other case-insensitive comparisons
CREATE EXTENSION IF NOT EXISTS citext;

-- Cryptographic functions for UUID generation (gen_random_uuid) and hashing
CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- GiST index support for exclusion constraints on range and scalar types
CREATE EXTENSION IF NOT EXISTS btree_gist;

-- FILE: /d/Products/athyper/server/db/sql/01_schemas/001_schemas.sql
-- Shared lookup data: currencies, countries, UoM, and standard codes
CREATE SCHEMA IF NOT EXISTS shared;

-- Access control, permissions, metadata/lookup registry, policy rules, lifecycle & workflow engines
CREATE SCHEMA IF NOT EXISTS control;

-- Master data: organizations, tenants, users, and core business entities
CREATE SCHEMA IF NOT EXISTS master;

-- Transactional documents: invoices, credit notes, payments, and journal entries
CREATE SCHEMA IF NOT EXISTS document;

-- General ledger, chart of accounts, fiscal periods, and financial postings
CREATE SCHEMA IF NOT EXISTS ledger;

-- Audit trails, change logs, and activity history
CREATE SCHEMA IF NOT EXISTS log;

-- Domain events, event store, and outbox for event-driven processing
CREATE SCHEMA IF NOT EXISTS event;

-- Approval workflows, period close orchestration, and compliance governance
CREATE SCHEMA IF NOT EXISTS governance;

-- Point-in-time snapshots for reporting, close cycles, and versioned state
CREATE SCHEMA IF NOT EXISTS snapshot;

-- Pre-computed aggregates, balances, KPIs, and materialized summaries
CREATE SCHEMA IF NOT EXISTS aggregate;

