    -- Table-specific (operational)
    is_intercompany_enabled  boolean      NOT NULL DEFAULT false,

    -- Metadata
    metadata                 jsonb        NOT NULL DEFAULT '{}'::jsonb,

    -- Lifecycle
    status           text         NOT NULL DEFAULT 'draft',
