    CONSTRAINT company_code_fy_start_chk    CHECK (fiscal_year_start_month BETWEEN 1 AND 12),
    CONSTRAINT company_code_code_nonempty   CHECK (btrim(code) <> ''),
    CONSTRAINT company_code_name_nonempty   CHECK (btrim(name) <> '')
