-- ════════════════════════════════════════════════════════════════════════════
-- §N  master.principal_notification_preference  — per-user notification opt-in
-- ════════════════════════════════════════════════════════════════════════════
-- One row per (tenant, principal, event_code, channel).
-- NULL is_enabled = inherit routing rule default.
-- NULL frequency_code = no digest batching (deliver immediately).
-- Precedence: routing rule → principal preference → digest frequency override.
-- high/urgent priorities (as defined in notification.priority seed) are never
-- downshifted to digest regardless of frequency_code.
--
-- Lookup domains (seeded in 900_seed_data/010_system/000_lookups/):
--   notification.channel   → channel
--   notification.digest_frequency → frequency_code

CREATE TABLE IF NOT EXISTS master.principal_notification_preference (
    -- Identity
    id              uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid        NOT NULL,

    -- Owner
    principal_id    uuid        NOT NULL,

    -- Scope — what event + channel this preference applies to
    event_code      text        NOT NULL,   -- matches notification_routing_rule.event_type
    channel         text        NOT NULL,   -- lookup: notification.channel

    -- Opt-in/out  (NULL = inherit routing rule default)
    is_enabled      boolean,

    -- Digest batching (NULL = deliver immediately; only applies to digest-eligible priorities)
    frequency_code  text,                   -- lookup: notification.digest_frequency

    -- Metadata
    metadata        jsonb       NOT NULL DEFAULT '{}'::jsonb,

    -- Lifecycle
    status          text        NOT NULL DEFAULT 'active',
    is_active       boolean     GENERATED ALWAYS AS (status = 'active') STORED,
    status_changed_at timestamptz,
    status_changed_by uuid,

    -- Audit
    created_at      timestamptz NOT NULL DEFAULT now(),
    created_by      uuid        NOT NULL,
    updated_at      timestamptz,
    updated_by      uuid,

    CONSTRAINT pnp_pkey                PRIMARY KEY (id),
    CONSTRAINT pnp_tenant_id_uq        UNIQUE (tenant_id, id),
    CONSTRAINT pnp_natural_key_uq      UNIQUE (tenant_id, principal_id, event_code, channel),
    CONSTRAINT pnp_status_chk          CHECK (status IN ('active', 'deprecated')),
    CONSTRAINT pnp_event_code_nonempty CHECK (btrim(event_code) <> ''),
    CONSTRAINT pnp_channel_nonempty    CHECK (btrim(channel) <> '')
    -- channel validated by trigger (notification.channel)
    -- frequency_code validated by trigger (notification.digest_frequency)
);

COMMENT ON TABLE master.principal_notification_preference IS
    'Per-user notification opt-in/out by event_code + channel. '
    'NULL is_enabled = inherit routing rule default. '
    'NULL frequency_code = immediate delivery (no digest batching). '
    'high/urgent priorities are never downshifted to digest. '
    'Precedence: routing rule → principal preference → digest frequency.';

COMMENT ON COLUMN master.principal_notification_preference.event_code IS
    'Matches control.notification_routing_rule.event_type. Identifies the notification trigger.';
COMMENT ON COLUMN master.principal_notification_preference.channel IS
    'Lookup: notification.channel (in_app, email, sms, push, webhook).';
COMMENT ON COLUMN master.principal_notification_preference.is_enabled IS
    'NULL = inherit routing rule. false = suppress all deliveries for this event+channel.';
COMMENT ON COLUMN master.principal_notification_preference.frequency_code IS
    'Lookup: notification.digest_frequency. NULL = immediate. Only honoured for digest-eligible priorities.';

-- Foreign keys
DO $$ BEGIN ALTER TABLE master.principal_notification_preference ADD CONSTRAINT pnp_tenant_fk
    FOREIGN KEY (tenant_id) REFERENCES master.tenant (id) ON DELETE CASCADE;
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN ALTER TABLE master.principal_notification_preference ADD CONSTRAINT pnp_principal_fk
    FOREIGN KEY (tenant_id, principal_id)
    REFERENCES master.principal (tenant_id, id) ON DELETE CASCADE;
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN ALTER TABLE master.principal_notification_preference ADD CONSTRAINT pnp_created_by_fk
    FOREIGN KEY (created_by) REFERENCES master.principal (id) ON DELETE RESTRICT;
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN ALTER TABLE master.principal_notification_preference ADD CONSTRAINT pnp_updated_by_fk
    FOREIGN KEY (updated_by) REFERENCES master.principal (id) ON DELETE SET NULL;
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- Index: lookups by principal
CREATE INDEX IF NOT EXISTS pnp_principal_idx
    ON master.principal_notification_preference (tenant_id, principal_id)
    WHERE is_active = true;

-- FILE: /d/Products/athyper/server/db/sql/04_tables/003f_master_cms.sql
-- 04_tables/003f_master_cms.sql
-- Depends on: 01_schemas, 02_types_domains, 003a_master_identity.sql
-- Master schema tables (Part F): Content management.
-- 3 tables: content_item, content_item_link, content_item_access_grant.
--
-- current_version_id circular FK → 06_constraints (DEFERRABLE INITIALLY DEFERRED).
--
-- Lookup-validated columns (trigger-based, 09_triggers/011_cms.sql):
--   content_item.kind           — master.content_item_kind
--   content_item_link.relation_type — master.content_item_link_relation_type
--
-- Sealed inline CHECK (protocol / platform vocabulary):
--   content_item.status         (DRAFT / REVIEW / PUBLISHED / ARCHIVED)
--   content_item_access_grant.subject_type  (principal / role / group / public)
--   content_item_access_grant.access_level  (read / write / publish / admin)
--
-- FKs → 06_constraints/011_cms.sql
-- Indexes → 07_indexes/011_cms.sql
-- Triggers → 09_triggers/011_cms.sql


-- ============================================================================
-- §1  master.content_item — versioned content header
-- ============================================================================
-- Registry / standing record for CMS content.
-- Body lives in snapshot.content_item_version.
-- current_version_id → DEFERRABLE circular FK (06_constraints).
-- Lifecycle mirrors master.template: UPPERCASE status, no is_active generated column.

CREATE TABLE IF NOT EXISTS master.content_item (
    -- Identity
    id                  uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id           uuid        NOT NULL,

    -- Natural key
    code                text        NOT NULL,
    title               text        NOT NULL,

    -- Table-specific (classification)
    kind                text        NOT NULL DEFAULT 'page',

    -- Table-specific (tree + locale + routing)
    parent_id           uuid,
    locale_code         text        NOT NULL DEFAULT 'en',
    slug                text        NOT NULL,
    summary             text,

    -- Current version pointer (circular FK — see 06_constraints)
    current_version_id  uuid,

    -- Metadata
    metadata            jsonb       NOT NULL DEFAULT '{}'::jsonb,

    -- Lifecycle
    status              text        NOT NULL DEFAULT 'DRAFT',
    status_changed_at   timestamptz,
    status_changed_by   uuid,

    -- Audit
    created_at          timestamptz NOT NULL DEFAULT now(),
    created_by          uuid        NOT NULL,
    updated_at          timestamptz,
    updated_by          uuid,

    CONSTRAINT content_item_pkey                PRIMARY KEY (id),
    CONSTRAINT content_item_tenant_id_uq        UNIQUE (tenant_id, id),
    CONSTRAINT content_item_tenant_code_uq      UNIQUE (tenant_id, code),
    CONSTRAINT content_item_slug_uq             UNIQUE (tenant_id, parent_id, locale_code, slug),
    CONSTRAINT content_item_no_self_ref         CHECK (parent_id IS DISTINCT FROM id),
    CONSTRAINT content_item_code_chk            CHECK (btrim(code) <> ''),
    CONSTRAINT content_item_title_chk           CHECK (btrim(title) <> ''),
    CONSTRAINT content_item_slug_chk            CHECK (slug ~ '^[a-z][a-z0-9_-]*$'),
    CONSTRAINT content_item_locale_code_chk     CHECK (btrim(locale_code) <> ''),
    CONSTRAINT content_item_status_chk          CHECK (status IN (
        'DRAFT', 'REVIEW', 'PUBLISHED', 'ARCHIVED'
    ))
    -- kind: 09_triggers — control.trg_validate_lookup_columns('master.content_item_kind')
    -- parent_id FK: 06_constraints (same-schema self-referential)
    -- current_version_id FK: 06_constraints — DEFERRABLE INITIALLY DEFERRED
);

COMMENT ON TABLE  master.content_item IS
    'Versioned content header. Body snapshots in snapshot.content_item_version. '
    'current_version_id → snapshot.content_item_version via DEFERRABLE FK (06_constraints). '
    'Lifecycle mirrors master.template: UPPERCASE status, no is_active. '
    'Multilingual: slug uniqueness includes locale_code. Multiple locales for one '
    'logical content item are modelled as sibling rows sharing the same code.';
COMMENT ON COLUMN master.content_item.code IS
    'Stable internal key. Never changes when title or slug is updated.';
COMMENT ON COLUMN master.content_item.slug IS
    'URL-visible path segment. Format: lowercase alphanumeric + hyphens/underscores. '
    'Unique per (tenant_id, parent_id, locale_code).';
COMMENT ON COLUMN master.content_item.kind IS
    'Content functional category. Lookup: master.content_item_kind. '
    'e.g. page, article, snippet, announcement.';
COMMENT ON COLUMN master.content_item.current_version_id IS
    'Points to the active snapshot. NULL until first version is saved. '
    'FK is DEFERRABLE INITIALLY DEFERRED — item + first version can be inserted '
    'atomically in a single transaction.';
COMMENT ON COLUMN master.content_item.locale_code IS
    'BCP 47 locale tag (e.g. en, fr, ar). Part of slug uniqueness key.';
COMMENT ON COLUMN master.content_item.summary IS
    'Short plain-text excerpt for listings and search results. Not versioned.';


-- ============================================================================
-- §2  master.content_item_link — cross-reference graph
-- ============================================================================
-- Explicit directional links between content items.
-- relation_type is extensible — governed by master.content_item_link_relation_type.
-- No updated_at: links are immutable once created (delete and re-create to change).

CREATE TABLE IF NOT EXISTS master.content_item_link (
    -- Identity
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,

    -- Graph edge
    source_content_item_id  uuid        NOT NULL,
    target_content_item_id  uuid        NOT NULL,

    -- Table-specific
    relation_type           text        NOT NULL DEFAULT 'related',
    display_order           integer     NOT NULL DEFAULT 0,

    -- Metadata
    metadata                jsonb       NOT NULL DEFAULT '{}'::jsonb,

    -- Audit
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,

    CONSTRAINT cil_pkey                 PRIMARY KEY (id),
    CONSTRAINT cil_tenant_id_uq         UNIQUE (tenant_id, id),
    CONSTRAINT cil_edge_uq              UNIQUE (tenant_id, source_content_item_id,
                                                target_content_item_id, relation_type),
    CONSTRAINT cil_no_self_ref          CHECK (source_content_item_id IS DISTINCT FROM
                                               target_content_item_id),
    CONSTRAINT cil_display_order_chk    CHECK (display_order >= 0),
    CONSTRAINT cil_relation_type_chk    CHECK (btrim(relation_type) <> '')
    -- relation_type: 09_triggers — control.trg_validate_lookup_columns(
    --     'master.content_item_link_relation_type', 'relation_type')
);

COMMENT ON TABLE  master.content_item_link IS
    'Directional cross-reference graph between content items. '
    'relation_type is extensible via master.content_item_link_relation_type lookup.';
COMMENT ON COLUMN master.content_item_link.relation_type IS
    'Link classification. Lookup: master.content_item_link_relation_type. '
    'e.g. related, embed, see_also.';
COMMENT ON COLUMN master.content_item_link.display_order IS
    'Sort order for rendering outbound links from source item.';


-- ============================================================================
-- §3  master.content_item_access_grant — per-record access overrides
-- ============================================================================
-- Record-level access grants layered on top of platform RBAC.
-- subject_type / access_level: sealed platform vocabulary — inline CHECK only.
-- subject_type = 'public' + subject_id IS NULL = world-readable content.

CREATE TABLE IF NOT EXISTS master.content_item_access_grant (
    -- Identity
    id                  uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id           uuid        NOT NULL,

    -- Target
    content_item_id     uuid        NOT NULL,

    -- Subject (one of: principal, role, group, or public)
    subject_type        text        NOT NULL,
    subject_id          uuid,

    -- Grant
    access_level        text        NOT NULL,
    expires_at          timestamptz,

    -- Audit
    created_at          timestamptz NOT NULL DEFAULT now(),
    created_by          uuid        NOT NULL,

    CONSTRAINT ciag_pkey                PRIMARY KEY (id),
    CONSTRAINT ciag_tenant_id_uq        UNIQUE (tenant_id, id),
    CONSTRAINT ciag_grant_uq            UNIQUE (tenant_id, content_item_id,
                                                subject_type, subject_id, access_level),
    CONSTRAINT ciag_subject_type_chk    CHECK (subject_type IN (
        'principal', 'role', 'group', 'public'
    )),
    CONSTRAINT ciag_access_level_chk    CHECK (access_level IN (
        'read', 'write', 'publish', 'admin'
    )),
    CONSTRAINT ciag_public_no_subject   CHECK (
        subject_type <> 'public' OR subject_id IS NULL
    ),
    CONSTRAINT ciag_named_has_subject   CHECK (
        subject_type = 'public' OR subject_id IS NOT NULL
    ),
    CONSTRAINT ciag_expiry_chk          CHECK (
        expires_at IS NULL OR expires_at > created_at
    )
);

COMMENT ON TABLE  master.content_item_access_grant IS
    'Per-record access grants. Additive overrides on top of platform RBAC. '
    'subject_type and access_level are sealed platform vocabulary (inline CHECK). '
    'subject_type=''public'' + subject_id IS NULL = open/world-readable.';
COMMENT ON COLUMN master.content_item_access_grant.subject_type IS
    'Sealed: principal | role | group | public.';
COMMENT ON COLUMN master.content_item_access_grant.access_level IS
    'Sealed: read | write | publish | admin.';
COMMENT ON COLUMN master.content_item_access_grant.expires_at IS
    'Optional expiry. NULL = perpetual grant. Must be after created_at.';


-- ============================================================================
-- §4  master.comment_feed_cursor — per-principal comment read watermark
-- ============================================================================
-- Lightweight per-principal read cursor for unread comment tracking.
--
-- One row per (tenant_id, principal_id, entity_type, entity_id).
-- Upserted when a principal opens a comment thread (sets last_read_at = now()).
--
-- Why a cursor table instead of log.activity_log?
--   log.activity_log is append-only and partitioned by month. Querying it
--   at render time (once per CommentList mount) would require a partition scan.
--   This table holds the latest watermark only — O(1) reads on a tiny B-tree.

CREATE TABLE IF NOT EXISTS master.comment_feed_cursor (
    id              uuid        NOT NULL DEFAULT gen_random_uuid(),
    tenant_id       uuid        NOT NULL,
    principal_id    uuid        NOT NULL,
    entity_type     text        NOT NULL,
    entity_id       text        NOT NULL,
    last_read_at    timestamptz NOT NULL DEFAULT now(),
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz,

    CONSTRAINT cfc_pk     PRIMARY KEY (id),
    CONSTRAINT cfc_unique UNIQUE (tenant_id, principal_id, entity_type, entity_id),
    CONSTRAINT cfc_entity_type_len CHECK (char_length(entity_type) BETWEEN 1 AND 120),
    CONSTRAINT cfc_entity_id_len   CHECK (char_length(entity_id)   BETWEEN 1 AND 120)
);

COMMENT ON TABLE master.comment_feed_cursor IS
    'Per-principal watermark for comment thread read tracking. '
    'One row per (tenant, principal, entity). Upserted on thread open. '
    'Enables O(1) unread-count queries without scanning activity_log.';

COMMENT ON COLUMN master.comment_feed_cursor.last_read_at IS
    'Timestamp of the last time this principal opened the comment thread. '
    'Comments created after this timestamp are counted as unread.';

-- Primary unread-count lookup: (tenant, entity_type, entity_id, principal)
CREATE INDEX IF NOT EXISTS cfc_entity_principal_idx
    ON master.comment_feed_cursor (tenant_id, entity_type, entity_id, principal_id);

ALTER TABLE master.comment_feed_cursor ENABLE ROW LEVEL SECURITY;
ALTER TABLE master.comment_feed_cursor FORCE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS tenant_rw  ON master.comment_feed_cursor;
DROP POLICY IF EXISTS admin_all  ON master.comment_feed_cursor;

CREATE POLICY tenant_rw ON master.comment_feed_cursor
    USING     (tenant_id = shared.current_tenant_id_soft())
    WITH CHECK (tenant_id = shared.current_tenant_id());

CREATE POLICY admin_all ON master.comment_feed_cursor
    TO athyperadmin USING (true) WITH CHECK (true);


-- ============================================================================
-- §PREVIEW  Preview columns — populated asynchronously by the cms-preview worker
-- ============================================================================
-- Added via Sprint 36 (Task 11.2 — CMS Preview Generation Worker).
-- The cms-preview BullMQ worker processes jobs queued when a new content
-- version is saved. It extracts plain text and HTML snippets from body_json
-- and writes them here so listing/search pages can render previews without
-- loading the full snapshot.content_item_version body.
--
-- preview_text — plain-text excerpt, max ~500 chars, suitable for search
-- preview_html — HTML snippet (first 3 paragraphs), suitable for embedding
-- preview_generated_at — when the worker last populated these columns;
--   NULL means no preview has been generated yet (pending first version save)
-- ============================================================================

ALTER TABLE master.content_item ADD COLUMN IF NOT EXISTS preview_text          text;
ALTER TABLE master.content_item ADD COLUMN IF NOT EXISTS preview_html          text;
ALTER TABLE master.content_item ADD COLUMN IF NOT EXISTS preview_generated_at  timestamptz;

COMMENT ON COLUMN master.content_item.preview_text IS
    'Plain-text excerpt generated by the cms-preview worker from the current version body_json. '
    'Max ~500 chars. NULL until first version is processed. Used for search snippets.';
COMMENT ON COLUMN master.content_item.preview_html IS
    'HTML snippet (first 3 rendered paragraphs) generated by the cms-preview worker. '
    'NULL until first version is processed. Used for embed/preview cards.';
COMMENT ON COLUMN master.content_item.preview_generated_at IS
    'Timestamp when the cms-preview worker last wrote preview_text/preview_html. '
    'NULL = preview pending. Use to detect stale previews after version updates.';

-- FILE: /d/Products/athyper/server/db/sql/04_tables/004_document.sql
-- 04_tables/004_document.sql
-- Scope: Platform / Workflow / Render document tables
-- Domain: workflow_request, workflow_stage, user_profile_update_request,
--         render_output, render_job
-- Depends on: 01_schemas, 04_tables/002_control.sql, 04_tables/003_master.sql
-- Load order: 004 (base document tables — no cross-document FK deps)

-- =============================================================================
-- §6  document.workflow_request — live workflow envelope
-- =============================================================================
-- One row per running workflow process. The envelope for an approval,
-- review, or watcher workflow on a specific entity.
-- workflow_type and template are captured at creation and version-pinned:
--   template_snapshot jsonb = compiled_json from workflow_template at creation time.
--   Subsequent template changes do not affect in-flight requests.
-- A08: entity_id is TEXT (polymorphic — matches lifecycle engine convention).
-- Renamed from document.approval_instance (backup).

CREATE TABLE IF NOT EXISTS document.workflow_request (
    -- Identity
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,

    -- Workflow type (lookup: work_request.workflow_type)
    workflow_type           text        NOT NULL DEFAULT 'approval',

    -- Definition reference (which policy triggered this)
    workflow_definition_id  uuid,

    -- Template reference + version-pinned snapshot
    workflow_template_id    uuid,
    template_snapshot       jsonb,

    -- Subject (A08: entity_id = TEXT — polymorphic)
    entity_type             text        NOT NULL,
    entity_id               text        NOT NULL,
    entity_version_id       uuid,
    -- Version-pinned entity state at submission time
    entity_snapshot         jsonb,

    -- Request context
    requested_by            uuid        NOT NULL,
    requested_at            timestamptz NOT NULL DEFAULT now(),

    -- Final outcome
    status                  text        NOT NULL DEFAULT 'pending',
    decision                text,
    decided_by              uuid,
    decided_at              timestamptz,
    reason                  text,

    -- Metadata
    metadata                jsonb       NOT NULL DEFAULT '{}',

    -- Correlation
    correlation_id          uuid,

    -- Audit
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT wreq_pkey                PRIMARY KEY (id),
    CONSTRAINT wreq_tenant_id_uq        UNIQUE (tenant_id, id),
    CONSTRAINT wreq_entity_chk          CHECK (
        btrim(entity_type) <> '' AND btrim(entity_id) <> ''
    ),
    CONSTRAINT wreq_status_chk          CHECK (status IN (
        'pending', 'approved', 'rejected', 'escalated', 'canceled'
    )),
    CONSTRAINT wreq_decision_chk        CHECK (decision IS NULL OR decision IN (
        'approve', 'reject', 'escalate'
    )),
    CONSTRAINT wreq_decided_consistency CHECK (
        decision IS NULL
        OR (
            status NOT IN ('pending', 'escalated')
            AND decided_at IS NOT NULL
            AND decided_by IS NOT NULL
        )
    ),
    CONSTRAINT wreq_snapshot_chk        CHECK (
        entity_snapshot IS NULL OR jsonb_typeof(entity_snapshot) = 'object'
    ),
    CONSTRAINT wreq_template_snap_chk   CHECK (
        template_snapshot IS NULL OR jsonb_typeof(template_snapshot) = 'object'
    )
    -- workflow_type: 09_triggers — control.trg_validate_lookup_columns('work_request.workflow_type')
);

COMMENT ON TABLE  document.workflow_request IS
    'Live workflow process envelope. One row per running approval/review/watcher. '
    'entity_id=TEXT (polymorphic — A08). '
    'entity_snapshot: version-pinned entity state at submission time. '
    'template_snapshot: version-pinned compiled_json from workflow_template. '
    'In-flight requests survive template changes. '
    'workflow_type validated via work_request.workflow_type lookup. '
    'Renamed from document.approval_instance (backup).';
COMMENT ON COLUMN document.workflow_request.entity_snapshot IS
    'Copy of entity payload at request submission time. '
    'Assignees see what was submitted, not the current (possibly edited) state. '
    'Controlled by workflow_template.behaviors.capture_entity_snapshot.';
COMMENT ON COLUMN document.workflow_request.template_snapshot IS
    'compiled_json from workflow_template at request creation time. '
    'Version-pins the workflow — template changes do not affect in-flight requests.';


-- =============================================================================
-- §7  document.workflow_stage — live stage instance
-- =============================================================================
-- One row per template_stage per workflow_request. Created upfront when the
-- workflow_request is created. Work items are created only when stage → ACTIVE.
-- A06: quorum captured at creation (version-pinned from template_stage).
-- A12: template_stage_id FK links back to control.workflow_template_stage.
-- Moved from control.* (backup) to document.* — it is an operational record.
-- Renamed from document.approval_stage (backup).

CREATE TABLE IF NOT EXISTS document.workflow_stage (
    -- Identity
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,

    -- Parent request
    workflow_request_id     uuid        NOT NULL,

    -- Template lineage (A12: trace back to template stage)
    template_stage_id       uuid,

    -- Stage definition (captured at creation — version-pinned)
    stage_no                smallint    NOT NULL,
    name                    text,

    -- Execution mode (captured from template at creation)
    mode                    text        NOT NULL DEFAULT 'serial',

    -- Quorum (A06: captured at creation — version-pinned)
    quorum                  jsonb,

    -- SLA
    sla_policy_id           uuid,

    -- Stage lifecycle
    status                  text        NOT NULL DEFAULT 'pending',
    started_at              timestamptz,
    completed_at            timestamptz,

    -- Outcome (set when stage completes)
    outcome                 text,

    -- Audit
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT wstg_pkey            PRIMARY KEY (id),
    CONSTRAINT wstg_tenant_id_uq    UNIQUE (tenant_id, id),
    -- One stage per stage_no per request
    CONSTRAINT wstg_stage_no_uq     UNIQUE (workflow_request_id, stage_no),
    CONSTRAINT wstg_stage_no_chk    CHECK (stage_no > 0),
    CONSTRAINT wstg_mode_chk        CHECK (mode IN ('serial', 'parallel')),
    CONSTRAINT wstg_status_chk      CHECK (status IN (
        'pending', 'active', 'completed', 'skipped', 'canceled'
    )),
    CONSTRAINT wstg_started_chk     CHECK (
        status = 'pending'
        OR (status IN ('active', 'completed', 'skipped') AND started_at IS NOT NULL)
    ),
    CONSTRAINT wstg_completed_chk   CHECK (
        status NOT IN ('completed', 'skipped', 'canceled') OR completed_at IS NOT NULL
    ),
    CONSTRAINT wstg_quorum_chk      CHECK (
        quorum IS NULL OR jsonb_typeof(quorum) = 'object'
    )
);

COMMENT ON TABLE  document.workflow_stage IS
    'Runtime stage instance. One row per template_stage per workflow_request. '
    'Created upfront — work_items created only when stage status → active. '
    'mode + quorum captured at creation (version-pinned — A06). '
    'template_stage_id links back to control.workflow_template_stage (A12). '
    'Moved from control.* to document.*. Renamed from approval_stage (backup).';
COMMENT ON COLUMN document.workflow_stage.quorum IS
    'Captured from workflow_template_stage.quorum at request creation. '
    'Version-pinned — template quorum changes do not affect in-flight stages.';
COMMENT ON COLUMN document.workflow_stage.outcome IS
    'Stage-level outcome when completed: approved | rejected | escalated | skipped.';


-- =============================================================================
-- §8  document.user_profile_update_request — self-service profile change
-- =============================================================================
-- Self-service profile update request. entity_class=DOCUMENT.
-- allow_on_behalf_of=false — self-service only (principal_id = created_by).
-- Requestor submits changes to own profile fields, locale/contact,
-- IAM group membership, or OU assignment. Routed to supervisor for approval.
-- ATH-DP-UPUPR-001 v3.0.

CREATE TABLE IF NOT EXISTS document.user_profile_update_request (

    -- ── Identity ──────────────────────────────────────────────────────────
    id                    uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id             uuid        NOT NULL,
    code                  text        NOT NULL,
    name                  text        NOT NULL,

    -- ── Requestor (platform contract — trigger-populated) ─────────────────
    created_by            uuid        NOT NULL,
    requested_by          uuid        NOT NULL,

    -- ── Subject (UPUPR-specific) ──────────────────────────────────────────
    principal_id          uuid        NOT NULL,
    principal_snapshot    jsonb,

    -- ── Request data ──────────────────────────────────────────────────────
    request_scope         text[]      NOT NULL DEFAULT '{}',
    priority              text        NOT NULL DEFAULT 'normal',
    change_reason         text,
    requested_changes     jsonb       NOT NULL DEFAULT '{}'::jsonb,

    -- ── Routing ───────────────────────────────────────────────────────────
    workflow_request_id   uuid,

    -- ── Lifecycle ─────────────────────────────────────────────────────────
    status                text        NOT NULL DEFAULT 'draft',
    is_active             boolean     GENERATED ALWAYS AS (
        status IN ('draft','submitted','awaiting_approval','revision_requested')
    ) STORED,
    status_changed_at     timestamptz,
    status_changed_by     uuid,

    -- ── Metadata ──────────────────────────────────────────────────────────
    metadata              jsonb       NOT NULL DEFAULT '{}'::jsonb,

    -- ── Audit ─────────────────────────────────────────────────────────────
    created_at            timestamptz NOT NULL DEFAULT now(),
    updated_at            timestamptz,
    updated_by            uuid,

    -- ── 8 Constraints ─────────────────────────────────────────────────────
    CONSTRAINT upupr_pkey            PRIMARY KEY (id),
    CONSTRAINT upupr_tenant_code_uq  UNIQUE (tenant_id, code),
    CONSTRAINT upupr_tenant_id_uq    UNIQUE (tenant_id, id),
    CONSTRAINT upupr_code_nonempty   CHECK (btrim(code) <> ''),
    CONSTRAINT upupr_code_fmt        CHECK (code !~ '\s'),
    CONSTRAINT upupr_name_nonempty   CHECK (btrim(name) <> ''),
    CONSTRAINT upupr_no_behalf_chk   CHECK (requested_by = created_by),
    CONSTRAINT upupr_subject_chk     CHECK (principal_id = created_by)
);

COMMENT ON TABLE document.user_profile_update_request IS
    'Self-service profile update request. entity_class=DOCUMENT. '
    'allow_on_behalf_of=false — self-service only (principal_id = created_by). '
    'Requestor submits changes to own profile fields, locale/contact, '
    'IAM group membership, or OU assignment. Routed to supervisor for approval. '
    'ATH-DP-UPUPR-001 v3.0.';


-- =============================================================================
-- §9  DOCUMENT · PRINT · BRANDING  —  document tables
-- =============================================================================
-- Depends on: master.tenant, snapshot.template_version

-- ── §9.1  document.render_output ───────────────────────────────────────────
-- Render request record — mutable status lifecycle (QUEUED → RENDERED → DELIVERED).
-- Idempotency unique index prevents duplicate concurrent renders.

CREATE TABLE IF NOT EXISTS document.render_output (
    -- Identity
    id              uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid        NOT NULL,

    -- Render inputs (cross-schema FKs in 06_constraints)
    template_version_id uuid,
    letterhead_id       uuid,
    brand_profile_id    uuid,

    -- Polymorphic entity context
    entity_name         text        NOT NULL,
    entity_id           text        NOT NULL,   -- text: polymorphic entity PK

    -- Render parameters
    operation           text        NOT NULL,
    variant             text        NOT NULL DEFAULT 'default',
    locale              text        NOT NULL DEFAULT 'en',
    timezone            text        NOT NULL DEFAULT 'UTC',

    -- Output storage
    status              text        NOT NULL DEFAULT 'QUEUED',
    storage_bucket      text,
    storage_key         text,
    storage_version_id  text,
    mime_type           text                 DEFAULT 'application/pdf',
    size_bytes          bigint,
    checksum            text,

    -- Request tracking
    manifest_json       jsonb       NOT NULL DEFAULT '{}'::jsonb,
    manifest_version    integer     NOT NULL DEFAULT 1,
    input_payload_hash  text,
    replaces_output_id  uuid,

    -- Error tracking
    error_code          text,
    error_message       text,

    -- Lifecycle timestamps
    rendered_at         timestamptz,
    delivered_at        timestamptz,
    archived_at         timestamptz,
    revoked_at          timestamptz,
    revoked_by          uuid,
    revoke_reason       text,

    -- Audit
    created_at          timestamptz NOT NULL DEFAULT now(),
    created_by          uuid        NOT NULL,
    updated_at          timestamptz,
    updated_by          uuid,

    CONSTRAINT render_output_pkey               PRIMARY KEY (id),
    CONSTRAINT render_output_tenant_id_uq       UNIQUE (tenant_id, id),
    CONSTRAINT render_output_status_chk         CHECK (status IN (
        'QUEUED', 'RENDERING', 'RENDERED', 'DELIVERED',
        'FAILED', 'ARCHIVED', 'REVOKED'
    )),
    CONSTRAINT render_output_size_chk           CHECK (
        size_bytes IS NULL OR size_bytes >= 0
    ),
    CONSTRAINT render_output_entity_name_chk    CHECK (btrim(entity_name) <> ''),
    CONSTRAINT render_output_entity_id_chk      CHECK (btrim(entity_id) <> ''),
    CONSTRAINT render_output_operation_chk      CHECK (btrim(operation) <> ''),
    CONSTRAINT render_output_manifest_ver_chk   CHECK (manifest_version >= 1)
    -- template_version_id, letterhead_id, brand_profile_id FKs in 06_constraints
);

COMMENT ON TABLE  document.render_output IS
    'Render request + result. Status lifecycle: QUEUED→RENDERING→RENDERED→DELIVERED. '
    'Idempotency index prevents same render being queued twice concurrently. '
    'manifest_json validated by document.trg_validate_manifest_json() trigger.';
COMMENT ON COLUMN document.render_output.entity_id IS
    'Entity PK as text — supports uuid and non-uuid entity keys (polymorphic).';
COMMENT ON COLUMN document.render_output.manifest_json IS
    'Render request manifest. Must be JSON object with entity_name key. '
    'Validated by document.trg_validate_manifest_json() trigger.';


-- ── §9.2  document.render_job ──────────────────────────────────────────────
-- Individual render execution record.
-- Mutable status (PENDING → RETRYING → COMPLETED) — NOT append-only.

CREATE TABLE IF NOT EXISTS document.render_job (
    -- Identity
    id              uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid        NOT NULL,

    -- Parent render request
    output_id       uuid        NOT NULL,

    -- Queue context
    job_queue_id    text,
    trace_id        text,

    -- Execution lifecycle
    status          text        NOT NULL DEFAULT 'PENDING',
    attempts        integer     NOT NULL DEFAULT 0,
    max_attempts    integer     NOT NULL DEFAULT 3,

    -- Error detail
    error_code      text,
    error_detail    text,

    -- Timing
    started_at      timestamptz,
    completed_at    timestamptz,
    duration_ms     bigint,

    -- Audit
    created_at      timestamptz NOT NULL DEFAULT now(),
    created_by      uuid        NOT NULL DEFAULT '00000000-0000-0000-0000-000000000000',
    updated_at      timestamptz,

    CONSTRAINT render_job_pkey              PRIMARY KEY (id),
    CONSTRAINT render_job_status_chk        CHECK (status IN (
        'PENDING', 'PROCESSING', 'COMPLETED', 'FAILED', 'RETRYING'
    )),
    CONSTRAINT render_job_attempts_pos      CHECK (attempts >= 0),
    CONSTRAINT render_job_max_pos           CHECK (max_attempts > 0),
    CONSTRAINT render_job_attempts_cap      CHECK (attempts <= max_attempts),
    CONSTRAINT render_job_duration_pos      CHECK (
        duration_ms IS NULL OR duration_ms >= 0
    )
);

COMMENT ON TABLE document.render_job IS
    'Render execution record. Mutable status (PENDING→RETRYING→COMPLETED) — '
    'not append-only, belongs in document schema not log. '
    'One render_output may have multiple render_job rows (retries). '
    'created_by: session principal who enqueued the job.';

-- FILE: /d/Products/athyper/server/db/sql/04_tables/004a_document_journal.sql
-- 04_tables/004a_document_journal.sql
-- Scope: Journal / GL / FX document tables + accounting distribution
-- Domain: journal_entry, journal_line, journal_line_reference,
--         fx_revaluation_run, accounting_distribution
-- Depends on: 01_schemas, 04_tables/002_control.sql, 04_tables/003_master.sql,
--             04_tables/004_document.sql (workflow_request)
-- Load order: 004a (after 004_document.sql)

-- ============================================================================
-- JOURNAL ENTRY / LINE / LINE REFERENCE
-- ============================================================================

-- ============================================================================
-- §JE  document.journal_entry — the posting event
-- ============================================================================
-- Status lifecycle: draft → created → posted → reversed
-- All amounts cached from lines (trigger-synced on draft→created)
-- Immutable after posted (except status→reversed and reversed_by_id)

CREATE TABLE IF NOT EXISTS document.journal_entry (
    -- Identity
    id               uuid         NOT NULL DEFAULT shared.uuidv7(),
    tenant_id        uuid         NOT NULL,
    code             text         NOT NULL DEFAULT '',
    name             text         NOT NULL DEFAULT '',

    -- Company scope (Tier 1 UUID)
    company_code_id  uuid         NOT NULL,

    -- Book + Period (UUID FKs)
    book_id          uuid         NOT NULL,
    fiscal_period_id uuid         NOT NULL,
    fiscal_year      smallint     NOT NULL,
    period_number    smallint     NOT NULL,

    -- Numbering
    je_number        text         NOT NULL,

    -- Dates
    document_date    date         NOT NULL,
    posting_date     date         NOT NULL,

    -- Source document
    source_doc_type  text         NOT NULL,
    source_doc_id    uuid,

    -- Amounts (CACHED from lines — not authoritative)
    transaction_currency character(3) NOT NULL,
    base_currency    character(3)     NOT NULL,
    total_debit      numeric(18,4) NOT NULL DEFAULT 0,
    total_credit     numeric(18,4) NOT NULL DEFAULT 0,
    line_count       smallint     NOT NULL DEFAULT 0,

    -- Description
    description      text,

    -- Reversal chain
    is_reversal      boolean      NOT NULL DEFAULT false,
    reversal_of_id   uuid,
    reversed_by_id   uuid,

    -- Auto-reversal
    is_auto_reverse  boolean      NOT NULL DEFAULT false,
    auto_reverse_date date,

    -- Cross-book derivation
    derived_from_je_id   uuid,
    posting_rule_id      uuid,
    book_idempotency_key text,

    -- Closed-period support
    prior_period_flag      boolean  NOT NULL DEFAULT false,
    original_period_year   smallint,
    original_period_number smallint,
    close_override_id      uuid,

    -- Posting metadata
    posted_at        timestamptz,
    posted_by        uuid,

    -- Tags & Metadata
    tags             jsonb        NOT NULL DEFAULT '[]'::jsonb,
    metadata         jsonb        NOT NULL DEFAULT '{}'::jsonb,

    -- Lifecycle
    status           text         NOT NULL DEFAULT 'draft',
    is_active        boolean      GENERATED ALWAYS AS (status IN ('draft', 'created', 'posted')) STORED,
    status_changed_at timestamptz,
    status_changed_by uuid,

    -- Audit
    created_at       timestamptz  NOT NULL DEFAULT now(),
    created_by       uuid         NOT NULL,
    updated_at       timestamptz,
    updated_by       uuid,

    CONSTRAINT journal_entry_pkey PRIMARY KEY (id),
    CONSTRAINT journal_entry_tenant_id_uq UNIQUE (tenant_id, id),
    CONSTRAINT journal_entry_tenant_number_uq
        UNIQUE (tenant_id, company_code_id, je_number),
    CONSTRAINT je_balanced_chk CHECK (total_debit = total_credit),
    CONSTRAINT je_doc_date_chk CHECK (document_date <= posting_date),
    CONSTRAINT je_auto_reverse_chk CHECK (NOT is_auto_reverse OR auto_reverse_date IS NOT NULL),
    CONSTRAINT je_no_self_ref CHECK (reversal_of_id IS DISTINCT FROM id),
    CONSTRAINT je_prior_period_chk CHECK (
        NOT prior_period_flag
        OR (original_period_year IS NOT NULL AND original_period_number IS NOT NULL)
    ),
    CONSTRAINT je_number_nonempty CHECK (btrim(je_number) <> '')
);

-- Idempotency for cross-book derived JEs
CREATE UNIQUE INDEX IF NOT EXISTS je_idempotency_uq
    ON document.journal_entry (tenant_id, book_idempotency_key)
    WHERE book_idempotency_key IS NOT NULL;

COMMENT ON TABLE document.journal_entry IS
    'Journal entry header. Status lifecycle: draft → created → posted → reversed. '
    'Amounts cached from lines (trigger-synced). Immutable after posted. '
    'document_date = business event date, posting_date = GL period assignment.';


-- ============================================================================
-- §JL  document.journal_line — debit/credit lines
-- ============================================================================
-- Dual-currency: transaction amounts (document currency) + base amounts
-- Strict polarity: exactly one side > 0.
-- Denormalized company_code_id, book_id, fiscal_period_id from header.

CREATE TABLE IF NOT EXISTS document.journal_line (
    -- Identity
    id               uuid         NOT NULL DEFAULT shared.uuidv7(),
    tenant_id        uuid         NOT NULL,

    -- Parent journal entry
    journal_entry_id uuid         NOT NULL,

    -- Denormalized from header (trigger-synced on INSERT)
    company_code_id  uuid         NOT NULL,
    book_id          uuid         NOT NULL,
    fiscal_period_id uuid         NOT NULL,
    fiscal_year      smallint     NOT NULL,
    period_number    smallint     NOT NULL,
    posting_date     date         NOT NULL,

    -- Line sequencing
    line_no          smallint     NOT NULL,

    -- Account
    gl_account_id    uuid         NOT NULL,

    -- Transaction amounts (document currency)
    transaction_currency character(3) NOT NULL,
    transaction_debit    numeric(18,4) NOT NULL DEFAULT 0,
    transaction_credit   numeric(18,4) NOT NULL DEFAULT 0,

    -- Base amounts (company functional currency)
    base_currency    character(3)     NOT NULL,
    base_debit       numeric(18,4) NOT NULL DEFAULT 0,
    base_credit      numeric(18,4) NOT NULL DEFAULT 0,
    exchange_rate    numeric(18,10),

    -- First-class dimensions
    cost_center_id   uuid,
    profit_center_id uuid,
    project_id       uuid,
    site_id          uuid,

    -- Composite dimensions
    dimension_set_id uuid,

    -- Party (counterparty)
    party_type       text,
    party_id         uuid,

    -- Subledger
    subledger_type   text,

    -- Narrative
    description      text,

    -- Source traceability
    source_doc_line_id uuid,

    -- Posting
    posted_at        timestamptz,
    posted_by        uuid,

    -- Tags & Metadata
    tags             jsonb        NOT NULL DEFAULT '[]'::jsonb,
    metadata         jsonb        NOT NULL DEFAULT '{}'::jsonb,

    -- Audit
    created_at       timestamptz  NOT NULL DEFAULT now(),
    created_by       uuid         NOT NULL,
    updated_at       timestamptz,
    updated_by       uuid,

    CONSTRAINT journal_line_pkey PRIMARY KEY (id),
    CONSTRAINT journal_line_je_line_uq UNIQUE (tenant_id, journal_entry_id, line_no),
    CONSTRAINT jl_txn_nonneg_chk CHECK (transaction_debit >= 0 AND transaction_credit >= 0),
    CONSTRAINT jl_txn_polarity_chk CHECK (
        (transaction_debit > 0 AND transaction_credit = 0)
        OR (transaction_debit = 0 AND transaction_credit > 0)
    ),
    CONSTRAINT jl_base_nonneg_chk CHECK (base_debit >= 0 AND base_credit >= 0),
    CONSTRAINT jl_base_polarity_chk CHECK (
        (base_debit > 0 AND base_credit = 0)
        OR (base_debit = 0 AND base_credit > 0)
    ),
    CONSTRAINT jl_side_match_chk CHECK (
        (transaction_debit > 0 AND base_debit > 0)
        OR (transaction_credit > 0 AND base_credit > 0)
    ),
    CONSTRAINT jl_fx_rate_chk CHECK (
        transaction_currency = base_currency OR exchange_rate IS NOT NULL
    ),
    CONSTRAINT jl_party_chk CHECK (
        (party_type IS NULL AND party_id IS NULL)
        OR (party_type IS NOT NULL AND party_id IS NOT NULL)
    )
);

COMMENT ON TABLE document.journal_line IS
    'Journal entry debit/credit lines. Dual-currency: transaction + base amounts. '
    'Strict polarity: exactly one side > 0. Denormalized header fields for query perf.';


-- ============================================================================
-- §JLR  document.journal_line_reference — allocation / application tracking
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.journal_line_reference (
    -- Identity
    id               uuid         NOT NULL DEFAULT shared.uuidv7(),
    tenant_id        uuid         NOT NULL,

    -- Parent line
    journal_line_id  uuid         NOT NULL,

    -- Reference target (polymorphic)
    ref_type         text         NOT NULL,
    ref_doc_type     text         NOT NULL,
    ref_doc_id       uuid         NOT NULL,
    ref_doc_line_id  uuid,
    ref_doc_number   text,

    -- Allocation amount
    allocated_amount numeric(18,4) NOT NULL,
    currency_code    character(3) NOT NULL,
    base_amount      numeric(18,4),

    -- Settlement tracking
    is_full_settlement boolean    NOT NULL DEFAULT false,
    settlement_date  date,

    -- Narrative
    description      text,

    -- Metadata
    metadata         jsonb        NOT NULL DEFAULT '{}'::jsonb,

    -- Audit (append-only — no updated_at)
    created_at       timestamptz  NOT NULL DEFAULT now(),
    created_by       uuid         NOT NULL,

    CONSTRAINT journal_line_reference_pkey PRIMARY KEY (id),
    CONSTRAINT jlr_amount_pos_chk CHECK (allocated_amount > 0)
);

-- G3: Widened uniqueness — include ref_doc_line_id for line-level allocation.
-- Old: UNIQUE (tenant_id, journal_line_id, ref_doc_type, ref_doc_id)
--   Problem: one JE line can't allocate to two lines of the same invoice.
-- New: adds COALESCE(ref_doc_line_id, sentinel) so (JE-line, INV-001, line-1)
--   and (JE-line, INV-001, line-2) are distinct rows.
CREATE UNIQUE INDEX IF NOT EXISTS jlr_line_ref_uq
    ON document.journal_line_reference (
        tenant_id,
        journal_line_id,
        ref_doc_type,
        ref_doc_id,
        COALESCE(ref_doc_line_id, '00000000-0000-0000-0000-000000000000')
    );

COMMENT ON TABLE document.journal_line_reference IS
    'Allocation/application tracking. 1:N child of journal_line. Handles payment '
    'allocation, credit note application, netting, advance clearing, PO matching, '
    'and asset capitalization.';


-- ============================================================================
-- TAX + FX ENGINE — document.fx_revaluation_run
-- ============================================================================
-- Period-end FX revaluation run header. Lines in ledger.fx_revaluation_line.

CREATE TABLE IF NOT EXISTS document.fx_revaluation_run (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,

    -- Company + book scope
    company_code_id         uuid            NOT NULL,
    book_id                 uuid            NOT NULL,

    -- Period
    fiscal_year             smallint        NOT NULL,
    period_number           smallint        NOT NULL,

    -- Dates
    revaluation_date        date            NOT NULL,
    posting_date            date,

    -- Rate
    rate_type_used          text            NOT NULL DEFAULT 'PERIOD_END',
    rate_source             text            NOT NULL DEFAULT 'MANUAL',
    functional_currency     character(3)    NOT NULL,

    -- Amounts
    total_unrealized_gain   numeric(18,4)   NOT NULL DEFAULT 0,
    total_unrealized_loss   numeric(18,4)   NOT NULL DEFAULT 0,
    net_amount              numeric(18,4)   GENERATED ALWAYS AS (
                                total_unrealized_gain - total_unrealized_loss
                            ) STORED,
    line_count              integer         NOT NULL DEFAULT 0,

    -- GL linkage
    revaluation_je_id       uuid,
    reversal_je_id          uuid,
    is_auto_reversed        boolean         NOT NULL DEFAULT true,
    auto_reverse_date       date,
    idempotency_key         text,

    -- Metadata
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Lifecycle
    status                  text            NOT NULL DEFAULT 'draft',
    is_active               boolean         GENERATED ALWAYS AS (
                                status IN ('draft','calculated','posted')
                            ) STORED,
    status_changed_at       timestamptz,
    status_changed_by       uuid,

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT fxrr_pkey            PRIMARY KEY (id),
    CONSTRAINT fxrr_tenant_id_uq    UNIQUE (tenant_id, id),
    CONSTRAINT fxrr_status_chk      CHECK (status IN (
        'draft','calculated','posted','reversed','cancelled')),
    CONSTRAINT fxrr_gain_nonneg     CHECK (total_unrealized_gain >= 0),
    CONSTRAINT fxrr_loss_nonneg     CHECK (total_unrealized_loss >= 0),
    CONSTRAINT fxrr_period_chk      CHECK (period_number BETWEEN 1 AND 16),
    CONSTRAINT fxrr_reverse_chk     CHECK (NOT is_auto_reversed OR auto_reverse_date IS NOT NULL)
);

COMMENT ON TABLE document.fx_revaluation_run IS
    'Period-end FX revaluation run header. net_amount GENERATED. '
    'Lines stored in ledger.fx_revaluation_line (immutable). '
    'Auto-reversal creates a reversal JE on auto_reverse_date (first day of next period).';


-- ============================================================================
-- §12  document.accounting_distribution — split-charge distribution
-- ============================================================================
-- Moved from 004b_document_p2p.sql. Used by requisition, commitment,
-- invoice, GR, and SES lines. Not used by payment entries.

CREATE TABLE IF NOT EXISTS document.accounting_distribution (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,

    -- Source document (polymorphic)
    source_doc_type         text            NOT NULL,
    source_doc_id           uuid            NOT NULL,
    source_line_id          uuid            NOT NULL,

    -- Distribution sequencing
    distribution_no         smallint        NOT NULL,

    -- Split basis
    distribution_basis      text            NOT NULL DEFAULT 'PERCENT',
    split_pct               numeric(7,4),
    split_amount            numeric(18,4),
    split_quantity          numeric(18,4),

    -- Distributed amount
    distributed_amount      numeric(18,4)   NOT NULL,
    currency_code           character(3)    NOT NULL,

    -- Engine-aligned resolution inputs (drives control.resolve_entry_account())
    account_source          text            NOT NULL DEFAULT 'FROM_CATEGORY',
    posting_role_code       text,
    account_code            text,
    account_lookup_key      text,
    account_fallback        text,
    gl_account_id           uuid,
    business_intent_id      uuid,
    spend_category_id       uuid,

    -- Dimensions
    cost_center_id          uuid,
    profit_center_id        uuid,
    project_id              uuid,
    site_id                 uuid,
    dimension_set_id        uuid,

    -- CapEx flag
    is_capex                boolean         NOT NULL DEFAULT false,
    asset_class_id          uuid,

    -- Tax override
    tax_treatment_override  text,

    -- Budget linkage
    budget_allocation_id    uuid,
    budget_check_result     text,

    -- Encumbrance
    encumbrance_je_id       uuid,

    -- Narrative
    description             text,

    -- Metadata
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT ad_pkey              PRIMARY KEY (id),
    CONSTRAINT ad_tenant_id_uq      UNIQUE (tenant_id, id),
    CONSTRAINT ad_line_dist_uq      UNIQUE (
        source_doc_type, source_doc_id, source_line_id, distribution_no),
    CONSTRAINT ad_dist_no_chk       CHECK (distribution_no > 0),
    CONSTRAINT ad_basis_chk         CHECK (distribution_basis IN (
        'PERCENT','AMOUNT','QUANTITY')),
    CONSTRAINT ad_pct_chk           CHECK (
        distribution_basis <> 'PERCENT'
        OR (split_pct IS NOT NULL AND split_pct > 0)),
    CONSTRAINT ad_amount_chk        CHECK (
        distribution_basis <> 'AMOUNT' OR split_amount IS NOT NULL),
    CONSTRAINT ad_qty_chk           CHECK (
        distribution_basis <> 'QUANTITY' OR split_quantity IS NOT NULL),
    CONSTRAINT ad_distributed_nonneg CHECK (distributed_amount >= 0),
    CONSTRAINT ad_source_type_chk   CHECK (source_doc_type IN (
        'PURCHASE_REQUISITION_LINE',
        'COMMITMENT_LINE',
        'PURCHASE_INVOICE_LINE',
        'GOODS_RECEIPT_LINE',
        'SERVICE_ENTRY_SHEET_LINE')),
    CONSTRAINT ad_source_chk        CHECK (account_source IN (
        'POSTING_ROLE','FIXED','FROM_INTENT','FROM_CATEGORY')),
    CONSTRAINT ad_posting_role_req  CHECK (
        account_source <> 'POSTING_ROLE' OR posting_role_code IS NOT NULL),
    CONSTRAINT ad_fixed_req         CHECK (
        account_source <> 'FIXED'
        OR gl_account_id IS NOT NULL OR account_code IS NOT NULL),
    CONSTRAINT ad_intent_req        CHECK (
        account_source <> 'FROM_INTENT' OR business_intent_id IS NOT NULL),
    CONSTRAINT ad_category_req      CHECK (
        account_source <> 'FROM_CATEGORY' OR spend_category_id IS NOT NULL),
    CONSTRAINT ad_budget_chk        CHECK (budget_check_result IS NULL OR budget_check_result IN (
        'PASSED','WARNED','OVERRIDE','BLOCKED','EXEMPT')),
    CONSTRAINT ad_tax_override_chk  CHECK (tax_treatment_override IS NULL OR
        tax_treatment_override IN (
            'STANDARD','ZERO_RATED','EXEMPT','REVERSE_CHARGE','OUT_OF_SCOPE'))
);

COMMENT ON TABLE document.accounting_distribution IS
    'Split-charge distribution. account_source drives control.resolve_entry_account() at posting time. '
    'Default: FROM_CATEGORY (spend_category → intent → GL). '
    'POSTING_ROLE for system rows (GRIR_CLEARING, PRICE_VARIANCE, ADVANCE_PREPAID, AP_TRADE, AP_RETENTION). '
    'PAYMENT_ENTRY excluded – payments allocate AP liabilities, not P&L charges.';

-- FILE: /d/Products/athyper/server/db/sql/04_tables/004b_document_commitment.sql
-- 04_tables/004b_document_commitment.sql
-- Scope: Commitment Engine document tables
-- Domain: commitment (header), commitment_procurement (1:1 P2P ext),
--         commitment_line, commitment_release_allocation,
--         commitment_party_snapshot, commitment_address_snapshot,
--         obligation_horizon, forecast_scenario
-- Depends on: 01_schemas, 04_tables/003_master.sql,
--             04_tables/004_document.sql (workflow_request)
-- Load order: 004b (after 004_document.sql, 004a_document_journal.sql)

-- ============================================================================
-- §CMT1  document.commitment — commitment header
-- ============================================================================
-- Legal/financial obligation: PO, contract, lease, subscription, standing order.
-- Draws budget from master.budget_allocation. Children: commitment_schedule,
-- commitment_fulfillment. Tracks encumbrance JE linkage.

CREATE TABLE IF NOT EXISTS document.commitment (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,
    code                    text            NOT NULL DEFAULT '',
    name                    text            NOT NULL DEFAULT '',

    -- Company scope
    company_code_id         uuid            NOT NULL,

    -- Numbering
    commitment_number       text            NOT NULL,

    -- Classification
    commitment_type         text            NOT NULL DEFAULT 'PURCHASE_ORDER',
    commitment_subtype      text,
    description             text,

    -- Counterparty (polymorphic)
    party_type              text,
    party_id                uuid,
    party_name              text,

    -- Dates
    document_date           date            NOT NULL,
    effective_date          date            NOT NULL,
    expiry_date             date,

    -- Amounts
    currency_code           character(3)    NOT NULL,
    base_currency_code      character(3)    NOT NULL,
    total_amount            numeric(18,4)   NOT NULL DEFAULT 0,
    scheduled_amount        numeric(18,4)   NOT NULL DEFAULT 0,
    fulfilled_amount        numeric(18,4)   NOT NULL DEFAULT 0,
    released_amount         numeric(18,4)   NOT NULL DEFAULT 0,
    outstanding_amount      numeric(18,4)   GENERATED ALWAYS AS (
                                total_amount - fulfilled_amount - released_amount
                            ) STORED,
    exchange_rate           numeric(18,10),

    -- Budget linkage
    budget_allocation_id    uuid,
    intent_id               uuid,
    budget_check_result     text,

    -- Encumbrance
    encumbrance_type        text            NOT NULL DEFAULT 'STANDARD',
    is_encumbered           boolean         NOT NULL DEFAULT false,
    encumbrance_je_id       uuid,

    -- Fiscal scope
    fiscal_year             smallint        NOT NULL,
    period_number           smallint,

    -- Dimensions
    cost_center_id          uuid,
    profit_center_id        uuid,
    project_id              uuid,
    site_id                 uuid,
    dimension_set_id        uuid,

    -- Organisational
    requested_by            uuid,

    -- Advance / Retention
    advance_pct             numeric(5,2),
    advance_amount          numeric(18,4),
    retention_pct           numeric(5,2),
    retention_amount        numeric(18,4),

    -- Payment Terms (linked term + frozen snapshot at time of selection)
    payment_term_id             uuid,
    payment_term_version        smallint,
    payment_term_snapshot       jsonb,
    payment_term_selected_at    timestamptz,
    payment_term_selected_by    uuid,

    -- Renewal
    is_auto_renew           boolean         NOT NULL DEFAULT false,
    renewal_terms           jsonb,
    renewal_count           smallint        NOT NULL DEFAULT 0,
    renewed_from_id         uuid,

    -- Amendment tracking
    amendment_count         smallint        NOT NULL DEFAULT 0,
    original_amount         numeric(18,4),
    variance_to_original    numeric(18,4)   GENERATED ALWAYS AS (
                                total_amount - COALESCE(original_amount, total_amount)
                            ) STORED,

    -- Line count (trigger-synced)
    schedule_count          smallint        NOT NULL DEFAULT 0,

    -- Approval
    approved_at             timestamptz,
    approved_by             uuid,
    workflow_request_id     uuid,

    -- Close / Cancellation
    closed_at               timestamptz,
    closed_by               uuid,
    close_reason            text,

    -- Tags & Metadata
    tags                    jsonb           NOT NULL DEFAULT '[]'::jsonb,
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Lifecycle
    status                  text            NOT NULL DEFAULT 'draft',
    is_active               boolean         GENERATED ALWAYS AS (
                                status IN ('draft','pending_approval','approved','active','partially_fulfilled')
                            ) STORED,
    status_changed_at       timestamptz,
    status_changed_by       uuid,

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT cmt_pkey                 PRIMARY KEY (id),
    CONSTRAINT cmt_tenant_id_uq         UNIQUE (tenant_id, id),
    CONSTRAINT cmt_tenant_number_uq     UNIQUE (tenant_id, company_code_id, commitment_number),
    CONSTRAINT cmt_number_nonempty      CHECK (btrim(commitment_number) <> ''),
    CONSTRAINT cmt_status_chk           CHECK (status IN (
        'draft','pending_approval','approved','active','partially_fulfilled',
        'fully_fulfilled','closed','cancelled','expired','suspended')),
    CONSTRAINT cmt_type_chk             CHECK (commitment_type IN (
        'PURCHASE_ORDER','CONTRACT','LEASE','SUBSCRIPTION','STANDING_ORDER',
        'BLANKET_PO','FRAMEWORK_AGREEMENT','GRANT_AWARD','INTERNAL_ORDER')),
    CONSTRAINT cmt_encumbrance_chk      CHECK (encumbrance_type IN (
        'NONE','STANDARD','PRE_ENCUMBRANCE','STATISTICAL_ONLY')),
    CONSTRAINT cmt_check_chk            CHECK (budget_check_result IS NULL OR budget_check_result IN (
        'PASSED','WARNED','OVERRIDE','BLOCKED','EXEMPT')),
    CONSTRAINT cmt_amount_nonneg        CHECK (total_amount >= 0),
    CONSTRAINT cmt_fulfilled_nonneg     CHECK (fulfilled_amount >= 0),
    CONSTRAINT cmt_released_nonneg      CHECK (released_amount >= 0),
    CONSTRAINT cmt_fulfilled_lte_total  CHECK (fulfilled_amount <= total_amount),
    CONSTRAINT cmt_date_chk             CHECK (expiry_date IS NULL OR expiry_date >= effective_date),
    CONSTRAINT cmt_advance_chk          CHECK (advance_pct IS NULL OR advance_pct BETWEEN 0 AND 100),
    CONSTRAINT cmt_retention_chk        CHECK (retention_pct IS NULL OR retention_pct BETWEEN 0 AND 100),
    CONSTRAINT cmt_period_chk           CHECK (period_number IS NULL OR period_number BETWEEN 1 AND 16),
    CONSTRAINT cmt_amendment_chk        CHECK (amendment_count >= 0),
    CONSTRAINT cmt_renewal_chk          CHECK (renewal_count >= 0),
    CONSTRAINT cmt_party_chk            CHECK (
        (party_type IS NULL AND party_id IS NULL)
        OR (party_type IS NOT NULL AND party_id IS NOT NULL)),
    CONSTRAINT cmt_no_self_renew        CHECK (renewed_from_id IS DISTINCT FROM id),
    CONSTRAINT cmt_pt_snapshot_chk      CHECK (
        payment_term_snapshot IS NULL OR jsonb_typeof(payment_term_snapshot) = 'object'),
    CONSTRAINT cmt_pt_all_req_chk       CHECK (
        payment_term_id IS NULL OR (
            payment_term_version     IS NOT NULL AND
            payment_term_snapshot    IS NOT NULL AND
            payment_term_selected_at IS NOT NULL AND
            payment_term_selected_by IS NOT NULL))
);

COMMENT ON TABLE document.commitment IS
    'Commitment header: PO, contract, lease, subscription, standing order. '
    'outstanding_amount = GENERATED (total - fulfilled - released). '
    'Draws budget from master.budget_allocation (budget_allocation_id). '
    'budget_check_result: PASSED | WARNED | OVERRIDE | BLOCKED | EXEMPT. '
    'Status lifecycle: draft → pending_approval → approved → active → '
    'partially_fulfilled → fully_fulfilled → closed | cancelled | expired. '
    'Children: ledger.commitment_schedule, ledger.commitment_fulfillment.';


-- ============================================================================
-- §4.1  document.commitment_procurement — 1:1 procurement extension
-- ============================================================================
-- Procurement-commercial child of document.commitment. One row per PO-type
-- commitment. Holds supplier, terms, running total caches.

CREATE TABLE IF NOT EXISTS document.commitment_procurement (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,

    -- Parent link (1:1)
    commitment_id           uuid            NOT NULL,

    -- Source requisition
    requisition_id          uuid,

    -- Release order linkage
    parent_contract_id      uuid,
    is_release_order        boolean         NOT NULL DEFAULT false,
    release_sequence_no     smallint,

    -- Supplier
    supplier_id             uuid            NOT NULL,
    supplier_contact_name   text,
    buyer_id                uuid,

    -- Shipping terms
    incoterms_code          text,
    incoterms_location      text,
    freight_terms           text,

    -- Address linkage
    delivery_address_id     uuid,
    billing_address_id      uuid,

    -- Payment terms
    payment_term_id         uuid,
    payment_method_id       uuid,

    -- Tax
    tax_treatment           text            DEFAULT 'STANDARD',
    withholding_tax_applicable boolean      NOT NULL DEFAULT false,

    -- Receipt basis flags
    gr_based_iv             boolean         NOT NULL DEFAULT true,
    service_based_iv        boolean         NOT NULL DEFAULT false,
    evaluated_receipt       boolean         NOT NULL DEFAULT false,

    -- Running totals (trigger-synced caches; source of truth in ledger/document children)
    line_count              smallint        NOT NULL DEFAULT 0,
    total_received_amount   numeric(18,4)   NOT NULL DEFAULT 0,
    total_invoiced_amount   numeric(18,4)   NOT NULL DEFAULT 0,
    total_paid_amount       numeric(18,4)   NOT NULL DEFAULT 0,

    -- Metadata
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT cp_pkey              PRIMARY KEY (id),
    CONSTRAINT cp_tenant_id_uq      UNIQUE (tenant_id, id),
    CONSTRAINT cp_commitment_uq     UNIQUE (commitment_id),
    CONSTRAINT cp_tax_treatment_chk CHECK (tax_treatment IS NULL OR tax_treatment IN (
        'STANDARD','ZERO_RATED','EXEMPT','REVERSE_CHARGE','OUT_OF_SCOPE')),
    CONSTRAINT cp_no_self_parent    CHECK (parent_contract_id IS DISTINCT FROM commitment_id),
    CONSTRAINT cp_received_nonneg   CHECK (total_received_amount >= 0),
    CONSTRAINT cp_invoiced_nonneg   CHECK (total_invoiced_amount >= 0),
    CONSTRAINT cp_paid_nonneg       CHECK (total_paid_amount >= 0)
);

COMMENT ON TABLE document.commitment_procurement IS
    'Procurement-commercial extension of document.commitment. 1:1 child. '
    'Running totals are derived caches, not source of truth. '
    'Source: ledger.commitment_fulfillment (receipts), document.purchase_invoice (invoices), '
    'document.payment_entry (payments).';


-- ============================================================================
-- §4.2  document.commitment_line — PO / contract line items
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.commitment_line (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,

    -- Parent commitment
    commitment_id           uuid            NOT NULL,
    line_no                 smallint        NOT NULL,

    -- Source line links
    requisition_line_id     uuid,
    parent_contract_line_id uuid,

    -- Item description
    item_id                 uuid,
    item_code               text,
    item_description        text            NOT NULL,
    procurement_type        text            NOT NULL DEFAULT 'goods',
    spend_category_id       uuid,
    business_intent_id      uuid,

    -- Quantity / price
    uom_code                text            NOT NULL,
    quantity                numeric(18,4)   NOT NULL,
    over_delivery_tolerance  numeric(5,2)   DEFAULT 0,
    under_delivery_tolerance numeric(5,2)   DEFAULT 0,

    unit_price              numeric(18,4)   NOT NULL DEFAULT 0,
    price_unit              numeric(18,4)   NOT NULL DEFAULT 1,
    currency_code           character(3)    NOT NULL,
    net_amount              numeric(18,4)   GENERATED ALWAYS AS (
                                (quantity * unit_price) / NULLIF(price_unit, 0)
                            ) STORED,
    discount_pct            numeric(5,2)    DEFAULT 0,
    discount_amount         numeric(18,4)   DEFAULT 0,

    -- Tax
    tax_group_id            uuid,
    withholding_tax_group_id uuid,

    -- Delivery
    required_by_date        date,
    promised_date           date,
    delivery_site_id        uuid,
    delivery_warehouse_id   uuid,
    storage_location        text,

    -- Dimensions
    cost_center_id          uuid,
    profit_center_id        uuid,
    project_id              uuid,
    site_id                 uuid,
    dimension_set_id        uuid,

    -- Asset flag
    is_asset                boolean         NOT NULL DEFAULT false,
    asset_category_id       uuid,

    -- Derived caches (trigger-synced)
    received_quantity       numeric(18,4)   NOT NULL DEFAULT 0,
    invoiced_quantity       numeric(18,4)   NOT NULL DEFAULT 0,
    remaining_quantity      numeric(18,4)   GENERATED ALWAYS AS (
                                quantity - received_quantity
                            ) STORED,

    -- Release caches (trigger-synced from commitment_release_allocation)
    released_quantity       numeric(18,4)   NOT NULL DEFAULT 0,
    released_amount         numeric(18,4)   NOT NULL DEFAULT 0,
    remaining_release_qty   numeric(18,4)   GENERATED ALWAYS AS (
                                quantity - released_quantity
                            ) STORED,
    remaining_release_amt   numeric(18,4)   GENERATED ALWAYS AS (
                                (quantity * unit_price) / NULLIF(price_unit, 0) - released_amount
                            ) STORED,

    is_fully_received       boolean         NOT NULL DEFAULT false,
    is_fully_invoiced       boolean         NOT NULL DEFAULT false,
    is_closed               boolean         NOT NULL DEFAULT false,

    -- Narrative
    notes                   text,

    -- Metadata
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,
    status                  text            NOT NULL DEFAULT 'open',

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT cl_pkey              PRIMARY KEY (id),
    CONSTRAINT cl_tenant_id_uq      UNIQUE (tenant_id, id),
    CONSTRAINT cl_line_no_uq        UNIQUE (commitment_id, line_no),
    CONSTRAINT cl_line_no_chk       CHECK (line_no > 0),
    CONSTRAINT cl_qty_pos           CHECK (quantity > 0),
    CONSTRAINT cl_price_nonneg      CHECK (unit_price >= 0),
    CONSTRAINT cl_price_unit_pos    CHECK (price_unit > 0),
    CONSTRAINT cl_proc_type_chk     CHECK (procurement_type IN ('goods','services','mixed')),
    CONSTRAINT cl_status_chk        CHECK (status IN (
        'open','partially_received','fully_received',
        'partially_invoiced','fully_invoiced','closed','cancelled')),
    CONSTRAINT cl_received_nonneg   CHECK (received_quantity >= 0),
    CONSTRAINT cl_invoiced_nonneg   CHECK (invoiced_quantity >= 0),
    CONSTRAINT cl_released_nonneg   CHECK (released_quantity >= 0),
    CONSTRAINT cl_tolerance_chk     CHECK (
        (over_delivery_tolerance IS NULL OR over_delivery_tolerance >= 0)
        AND (under_delivery_tolerance IS NULL OR under_delivery_tolerance >= 0)),
    CONSTRAINT cl_discount_chk      CHECK (discount_pct IS NULL OR discount_pct BETWEEN 0 AND 100),
    CONSTRAINT cl_no_self_parent    CHECK (parent_contract_line_id IS DISTINCT FROM id)
);

COMMENT ON TABLE document.commitment_line IS
    'PO / contract line items. Mutable operational detail – document schema, not ledger. '
    'received_quantity, invoiced_quantity, released_quantity are derived caches. '
    'Source of truth: ledger.commitment_fulfillment (receipts), '
    'document.commitment_release_allocation (blanket/framework releases).';


-- ============================================================================
-- §4.3  document.commitment_release_allocation
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.commitment_release_allocation (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,

    -- Parent / release links
    parent_commitment_id    uuid            NOT NULL,
    parent_line_id          uuid            NOT NULL,
    release_commitment_id   uuid            NOT NULL,
    release_line_id         uuid            NOT NULL,

    -- Amounts
    released_quantity       numeric(18,4)   NOT NULL DEFAULT 0,
    released_amount         numeric(18,4)   NOT NULL DEFAULT 0,
    currency_code           character(3)    NOT NULL,

    -- Release event
    released_at             timestamptz     NOT NULL DEFAULT now(),
    released_by             uuid            NOT NULL,

    -- Lifecycle
    status                  text            NOT NULL DEFAULT 'active',

    -- Metadata
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT cra_pkey             PRIMARY KEY (id),
    CONSTRAINT cra_tenant_id_uq     UNIQUE (tenant_id, id),
    CONSTRAINT cra_release_line_uq  UNIQUE (release_commitment_id, release_line_id),
    CONSTRAINT cra_qty_nonneg       CHECK (released_quantity >= 0),
    CONSTRAINT cra_amt_nonneg       CHECK (released_amount >= 0),
    CONSTRAINT cra_status_chk       CHECK (status IN ('active','cancelled','superseded')),
    CONSTRAINT cra_no_self_release  CHECK (parent_commitment_id <> release_commitment_id)
);

COMMENT ON TABLE document.commitment_release_allocation IS
    'Tracks qty/amount drawn from parent BLANKET_PO or FRAMEWORK_AGREEMENT line '
    'by each release PO line. Source of truth for release exhaustion checks.';


-- ============================================================================
-- §5.1  document.commitment_party_snapshot
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.commitment_party_snapshot (
    -- Identity
    id                  uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id           uuid            NOT NULL,

    -- Parent commitment
    commitment_id       uuid            NOT NULL,
    snapshot_type       text            NOT NULL DEFAULT 'SUPPLIER',

    -- Party identity
    party_id            uuid            NOT NULL,
    party_code          text            NOT NULL,
    party_name          text            NOT NULL,
    tax_registration_no text,
    legal_entity_name   text,
    country_code        character(2),

    -- Contact
    contact_name        text,
    contact_email       text,
    contact_phone       text,

    -- Capture audit (append-only)
    captured_at         timestamptz     NOT NULL DEFAULT now(),
    captured_by         uuid            NOT NULL,
    metadata            jsonb           NOT NULL DEFAULT '{}'::jsonb,

    CONSTRAINT cps_pkey                 PRIMARY KEY (id),
    CONSTRAINT cps_tenant_id_uq         UNIQUE (tenant_id, id),
    CONSTRAINT cps_commitment_type_uq   UNIQUE (commitment_id, snapshot_type),
    CONSTRAINT cps_type_chk             CHECK (snapshot_type IN ('SUPPLIER','BUYER'))
);


-- ============================================================================
-- §5.2  document.commitment_address_snapshot
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.commitment_address_snapshot (
    -- Identity
    id                  uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id           uuid            NOT NULL,

    -- Parent commitment
    commitment_id       uuid            NOT NULL,
    address_type        text            NOT NULL,

    -- Address
    address_line_1      text            NOT NULL,
    address_line_2      text,
    city                text,
    state_province      text,
    postal_code         text,
    country_code        character(2)    NOT NULL,

    -- Capture audit (append-only)
    captured_at         timestamptz     NOT NULL DEFAULT now(),
    captured_by         uuid            NOT NULL,

    CONSTRAINT cas_pkey                 PRIMARY KEY (id),
    CONSTRAINT cas_tenant_id_uq         UNIQUE (tenant_id, id),
    CONSTRAINT cas_commitment_type_uq   UNIQUE (commitment_id, address_type),
    CONSTRAINT cas_type_chk             CHECK (address_type IN ('DELIVERY','BILLING','SHIP_FROM'))
);


-- ============================================================================
-- §13  document.obligation_horizon — multi-year demand signal
-- ============================================================================
-- obligation_tier = lifecycle progression (PLANNED → FORECAST → RESERVED → COMMITTED → CONSUMED).
-- status = operational state (active | cancelled | superseded).
-- variance_to_original = computed delta from baseline; NULL when original_amount not yet set.
-- Child of document.commitment.

CREATE TABLE IF NOT EXISTS document.obligation_horizon (
    -- Identity
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,

    -- Parent document
    commitment_id           uuid        NOT NULL,
    schedule_id             uuid,

    -- Fiscal scope
    fiscal_year             smallint    NOT NULL,
    period_from             smallint    NOT NULL DEFAULT 1,
    period_to               smallint    NOT NULL DEFAULT 12,

    -- Obligation state
    obligation_tier         text        NOT NULL DEFAULT 'PLANNED',
    amount                  numeric(18,4) NOT NULL,
    original_amount         numeric(18,4),
    currency_code           text        NOT NULL,

    -- Budget linkage
    fp_id                   uuid,
    intent_id               uuid,
    company_code_id         uuid,

    -- Spread
    spread_method           text        NOT NULL DEFAULT 'EVEN',
    period_amounts          jsonb,
    confidence              numeric(3,2) NOT NULL DEFAULT 1.00,
    source_type             text        NOT NULL DEFAULT 'CONTRACT',

    -- Escalation
    escalation_formula      jsonb,
    escalation_applied_at   timestamptz,

    -- FX
    contract_currency_code  text,
    contract_amount         numeric(18,4),
    exchange_rate           numeric(12,6),
    rate_type               text,

    -- Retention
    retention_pct           numeric(5,2),
    retention_release_date  date,

    -- Amendment tracking
    amendment_count         smallint    NOT NULL DEFAULT 0,
    variance_to_original    numeric(18,4) GENERATED ALWAYS AS (amount - original_amount) STORED,

    -- Lifecycle events (timestamps; not replacements for status)
    promoted_at             timestamptz,
    reserved_at             timestamptz,
    funding_txn_id          uuid,

    -- Metadata
    metadata                jsonb       NOT NULL DEFAULT '{}',

    -- Lifecycle
    status            text             NOT NULL DEFAULT 'active',
    is_active         boolean          GENERATED ALWAYS AS (status = 'active') STORED,
    status_changed_at timestamptz,
    status_changed_by uuid,

    -- Audit
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT oh_pkey              PRIMARY KEY (id),
    CONSTRAINT oh_status_chk        CHECK (status IN ('active','cancelled','superseded')),
    CONSTRAINT oh_tier_chk          CHECK (obligation_tier IN (
        'PLANNED','FORECAST','RESERVED','COMMITTED','CONSUMED')),
    CONSTRAINT oh_spread_chk        CHECK (spread_method IN (
        'EVEN','FRONT_LOADED','BACK_LOADED','MILESTONE','CUSTOM')),
    CONSTRAINT oh_source_chk        CHECK (source_type IN (
        'CONTRACT','PO','SUBSCRIPTION','LEASE','FORECAST_MODEL','MANUAL')),
    CONSTRAINT oh_period_range_chk  CHECK (
        period_from BETWEEN 1 AND 12
        AND period_to BETWEEN 1 AND 12
        AND period_from <= period_to),
    CONSTRAINT oh_confidence_chk    CHECK (confidence BETWEEN 0 AND 1),
    CONSTRAINT oh_amount_chk        CHECK (amount >= 0),
    CONSTRAINT oh_retention_chk     CHECK (retention_pct IS NULL OR retention_pct BETWEEN 0 AND 100),
    CONSTRAINT oh_amendment_chk     CHECK (amendment_count >= 0)
);

COMMENT ON TABLE document.obligation_horizon IS
    'Engine 4.13: multi-year demand signal. '
    'obligation_tier: PLANNED → FORECAST → RESERVED → COMMITTED → CONSUMED. '
    'Created on contract signing; advanced by budget lifecycle events. '
    'Child of document.commitment. variance_to_original = GENERATED (amount - original_amount).';


-- ============================================================================
-- §CMT2  document.forecast_scenario — what-if forecast scenario envelope
-- ============================================================================
-- Contains forecast_line items for one version of a forward-looking projection.
-- Multiple scenarios enable side-by-side comparison (best/worst/expected).

CREATE TABLE IF NOT EXISTS document.forecast_scenario (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,
    code                    text            NOT NULL,
    name                    text            NOT NULL,

    -- Company scope
    company_code_id         uuid            NOT NULL,

    -- Classification
    description             text,
    scenario_type           text            NOT NULL DEFAULT 'EXPECTED',
    scenario_purpose        text            NOT NULL DEFAULT 'BUDGET',

    -- Fiscal scope
    fiscal_year             smallint        NOT NULL,
    period_from             smallint        NOT NULL DEFAULT 1,
    period_to               smallint        NOT NULL DEFAULT 12,

    -- Model linkage (optional — for driver-based forecasts)
    planning_model_id       uuid,

    -- Ownership
    responsible_person_id   uuid,

    -- Currency
    base_currency_code      character(3)    NOT NULL,

    -- Totals (trigger-synced from lines)
    total_amount            numeric(18,4)   NOT NULL DEFAULT 0,
    line_count              smallint        NOT NULL DEFAULT 0,

    -- Versioning
    version                 integer         NOT NULL DEFAULT 1,
    based_on_scenario_id    uuid,
    is_baseline             boolean         NOT NULL DEFAULT false,

    -- Comparison
    variance_to_baseline    numeric(18,4),
    confidence_level        numeric(3,2),

    -- Approval
    approved_at             timestamptz,
    approved_by             uuid,
    published_at            timestamptz,
    published_by            uuid,

    -- Tags & Metadata
    tags                    jsonb           NOT NULL DEFAULT '[]'::jsonb,
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Lifecycle
    status                  text            NOT NULL DEFAULT 'draft',
    is_active               boolean         GENERATED ALWAYS AS (
                                status IN ('draft','in_review','approved','published')
                            ) STORED,
    status_changed_at       timestamptz,
    status_changed_by       uuid,

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT fs_pkey                  PRIMARY KEY (id),
    CONSTRAINT fs_tenant_id_uq          UNIQUE (tenant_id, id),
    CONSTRAINT fs_tenant_code_ver_uq    UNIQUE (tenant_id, company_code_id, code, version),
    CONSTRAINT fs_code_nonempty         CHECK (btrim(code) <> ''),
    CONSTRAINT fs_name_nonempty         CHECK (btrim(name) <> ''),
    CONSTRAINT fs_status_chk            CHECK (status IN (
        'draft','in_review','approved','published','superseded','archived','cancelled')),
    CONSTRAINT fs_type_chk              CHECK (scenario_type IN (
        'EXPECTED','BEST_CASE','WORST_CASE','STRETCH','CONSERVATIVE',
        'BASELINE','WHAT_IF','SENSITIVITY')),
    CONSTRAINT fs_purpose_chk           CHECK (scenario_purpose IN (
        'BUDGET','FORECAST','REFORECAST','PROJECTION','STRATEGIC','SCENARIO_ANALYSIS')),
    CONSTRAINT fs_period_range_chk      CHECK (
        period_from BETWEEN 1 AND 16
        AND period_to BETWEEN 1 AND 16
        AND period_from <= period_to),
    CONSTRAINT fs_version_chk           CHECK (version >= 1),
    CONSTRAINT fs_confidence_chk        CHECK (confidence_level IS NULL OR confidence_level BETWEEN 0 AND 1),
    CONSTRAINT fs_no_self_base          CHECK (based_on_scenario_id IS DISTINCT FROM id)
);

COMMENT ON TABLE document.forecast_scenario IS
    'What-if forecast scenario envelope. Contains control.forecast_line items. '
    'scenario_type: EXPECTED, BEST_CASE, WORST_CASE, etc. for side-by-side comparison. '
    'Versioned per (tenant, company, code). Links to master.planning_model for driver-based forecasts. '
    'Status lifecycle: draft → in_review → approved → published → superseded | archived.';

-- FILE: /d/Products/athyper/server/db/sql/04_tables/004c_document_attachments.sql
-- ─── document.doc_attachment ─────────────────────────────────────────────────
--
-- Inline file storage for document attachments.
-- Stores base64-encoded file content directly in the row — no S3 dependency.
-- Suitable for development and moderate-size files (< 25 MB).
--
-- Linked to a document by (tenant_id, entity_type, entity_id):
--   entity_type  — document entity slug, e.g. 'purchase_invoice'
--   entity_id    — document primary key UUID
--
-- Upload flow: BFF relay converts multipart/form-data → base64 JSON →
--   runtime stores base64 in data_base64.
-- Download flow: GET .../attachments/:id/download streams decoded bytes.
 
CREATE TABLE IF NOT EXISTS document.doc_attachment (
    id              uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid            NOT NULL,
    entity_type     text            NOT NULL,
    entity_id       uuid            NOT NULL,
    filename        text            NOT NULL,
    content_type    text            NOT NULL DEFAULT 'application/octet-stream',
    size_bytes      bigint          NOT NULL DEFAULT 0,
    data_base64     text            NOT NULL DEFAULT '',
    uploaded_by     uuid,
    created_at      timestamptz     NOT NULL DEFAULT now(),
    created_by      uuid            NOT NULL,
    updated_at      timestamptz,
    updated_by      uuid,
 
    CONSTRAINT doc_attachment_pkey          PRIMARY KEY (id),
    CONSTRAINT doc_attachment_tenant_id_uq  UNIQUE (tenant_id, id),
    CONSTRAINT doc_attachment_filename_chk  CHECK (btrim(filename) <> ''),
    CONSTRAINT doc_attachment_size_chk      CHECK (size_bytes >= 0)
);
 
CREATE INDEX IF NOT EXISTS doc_attachment_entity_idx
    ON document.doc_attachment (tenant_id, entity_type, entity_id);
 
COMMENT ON TABLE document.doc_attachment IS
    'Inline document file attachments. Base64 content in data_base64. '
    'entity_type = document entity name slug; entity_id = document PK.';
 
COMMENT ON COLUMN document.doc_attachment.data_base64 IS
    'Base64-encoded file content. Empty string for metadata-only records '
    '(e.g. after migration to S3-backed master.attachment).';
 
 
-- FK constraints

DO $$ BEGIN
    ALTER TABLE document.doc_attachment
        ADD CONSTRAINT da_tenant_fk
        FOREIGN KEY (tenant_id) REFERENCES master.tenant (id) ON DELETE CASCADE;
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
    ALTER TABLE document.doc_attachment
        ADD CONSTRAINT da_uploaded_by_fk
        FOREIGN KEY (uploaded_by) REFERENCES master.principal (id) ON DELETE SET NULL;
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
    ALTER TABLE document.doc_attachment
        ADD CONSTRAINT da_created_by_fk
        FOREIGN KEY (created_by) REFERENCES master.principal (id) ON DELETE RESTRICT;
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
    ALTER TABLE document.doc_attachment
        ADD CONSTRAINT da_updated_by_fk
        FOREIGN KEY (updated_by) REFERENCES master.principal (id) ON DELETE SET NULL;
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
 
 
-- FILE: /d/Products/athyper/server/db/sql/04_tables/004d_document_invoice.sql
-- 04_tables/004d_document_invoice.sql
-- Scope: Invoice document tables
-- Domain: purchase_invoice, purchase_invoice_line,
--         invoice_party_snapshot, invoice_address_snapshot,
--         invoice_bank_snapshot, invoice_tax_snapshot,
--         invoice_match_case, match_exception,
--         payment_term_application (belongs with invoice domain)
-- Depends on: 01_schemas, 04_tables/003_master.sql, 03d_master_payment_terms.sql,
--             04_tables/004_document.sql (workflow_request),
--             04_tables/004b_document_commitment.sql (commitment, commitment_line)
-- Load order: 004d (after 004c_document_p2p.sql)

-- ============================================================================
-- §9  document.purchase_invoice  (approvable)
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.purchase_invoice (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,
    company_code_id         uuid            NOT NULL,

    -- Natural keys
    invoice_number          text            NOT NULL,
    fiscal_document_number  text,

    -- Classification
    invoice_source          text            NOT NULL DEFAULT 'PO_BASED',
    invoice_type            text            NOT NULL DEFAULT 'STANDARD',
    description             text,

    -- Counterparty
    supplier_id             uuid,
    supplier_invoice_number text            NOT NULL,
    supplier_invoice_date   date            NOT NULL,

    -- Parent commitment
    commitment_id           uuid,

    -- Dates
    document_date           date            NOT NULL DEFAULT CURRENT_DATE,
    posting_date            date            NOT NULL DEFAULT CURRENT_DATE,
    received_date           date            NOT NULL DEFAULT CURRENT_DATE,
    baseline_date           date,
    due_date                date,

    -- Amounts
    currency_code           character(3)    NOT NULL,
    base_currency_code      character(3)    NOT NULL,
    exchange_rate           numeric(18,10),

    subtotal_amount         numeric(18,4)   NOT NULL DEFAULT 0,
    discount_amount         numeric(18,4)   NOT NULL DEFAULT 0,
    freight_amount          numeric(18,4)   NOT NULL DEFAULT 0,
    misc_charges_amount     numeric(18,4)   NOT NULL DEFAULT 0,
    total_amount            numeric(18,4)   NOT NULL DEFAULT 0,

    tax_amount              numeric(18,4)   NOT NULL DEFAULT 0,
    withholding_tax_amount  numeric(18,4)   NOT NULL DEFAULT 0,

    payable_amount          numeric(18,4)   GENERATED ALWAYS AS (
                                total_amount - withholding_tax_amount
                            ) STORED,

    -- Payment terms
    payment_term_id         uuid,
    term_snapshot           jsonb,
    payment_method_id       uuid,

    -- Advance deduction
    advance_deduction_amount numeric(18,4)  NOT NULL DEFAULT 0,

    -- Retention (AP Retention Payable — liability, NOT receivable asset)
    retention_amount        numeric(18,4)   NOT NULL DEFAULT 0,
    retention_pct           numeric(5,2),

    -- Payment tracking
    paid_amount             numeric(18,4)   NOT NULL DEFAULT 0,
    outstanding_amount      numeric(18,4)   GENERATED ALWAYS AS (
                                total_amount - withholding_tax_amount
                                - advance_deduction_amount - retention_amount - paid_amount
                            ) STORED,

    -- Budget
    budget_allocation_id    uuid,
    budget_check_result     text,

    -- Fiscal scope
    fiscal_year             smallint        NOT NULL,
    period_number           smallint        NOT NULL,

    -- Dimensions
    cost_center_id          uuid,
    profit_center_id        uuid,
    project_id              uuid,
    site_id                 uuid,
    dimension_set_id        uuid,

    -- Posting
    ap_je_id                uuid,
    is_posted               boolean         NOT NULL DEFAULT false,
    posted_at               timestamptz,
    posted_by               uuid,

    -- Matching
    match_type              text            NOT NULL DEFAULT 'THREE_WAY',
    match_status            text            NOT NULL DEFAULT 'unmatched',

    -- Reversal / credit note
    is_reversal             boolean         NOT NULL DEFAULT false,
    reversal_of_id          uuid,
    is_credit_note          boolean         NOT NULL DEFAULT false,

    -- Workflow
    workflow_request_id     uuid,
    approved_at             timestamptz,
    approved_by             uuid,

    -- Hold
    is_on_hold              boolean         NOT NULL DEFAULT false,
    hold_reason             text,

    -- Line count + notes
    line_count              smallint        NOT NULL DEFAULT 0,
    notes                   text,

    -- Tags & Metadata
    tags                    jsonb           NOT NULL DEFAULT '[]'::jsonb,
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Lifecycle
    status                  text            NOT NULL DEFAULT 'draft',
    is_active               boolean         GENERATED ALWAYS AS (
                                status IN ('draft','pending_approval','approved','posted',
                                           'partially_paid','on_hold')
                            ) STORED,
    status_changed_at       timestamptz,
    status_changed_by       uuid,

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT pi_pkey              PRIMARY KEY (id),
    CONSTRAINT pi_tenant_id_uq      UNIQUE (tenant_id, id),
    CONSTRAINT pi_tenant_number_uq  UNIQUE (tenant_id, company_code_id, invoice_number),
    CONSTRAINT pi_number_nonempty   CHECK (btrim(invoice_number) <> ''),
    CONSTRAINT pi_status_chk        CHECK (status IN (
        'draft','pending_approval','approved','posted','partially_paid',
        'fully_paid','on_hold','reversed','cancelled','rejected')),
    CONSTRAINT pi_source_chk        CHECK (invoice_source IN (
        'PO_BASED','CONTRACT_BASED','NON_PO','ONE_TIME_VENDOR')),
    CONSTRAINT pi_type_chk          CHECK (invoice_type IN (
        'STANDARD','CREDIT_NOTE','DEBIT_NOTE','ADVANCE','RETENTION_RELEASE',
        'PROFORMA','SELF_BILLED','DOWN_PAYMENT','FINAL')),
    CONSTRAINT pi_match_type_chk    CHECK (match_type IN (
        'THREE_WAY','TWO_WAY','NO_MATCH','EVALUATED_RECEIPT')),
    CONSTRAINT pi_match_status_chk  CHECK (match_status IN (
        'unmatched','partially_matched','fully_matched','match_exception')),
    CONSTRAINT pi_commitment_req    CHECK (
        invoice_source NOT IN ('PO_BASED','CONTRACT_BASED')
        OR commitment_id IS NOT NULL),
    CONSTRAINT pi_amount_chk        CHECK (total_amount >= 0 OR is_credit_note),
    CONSTRAINT pi_period_chk        CHECK (period_number BETWEEN 1 AND 16),
    CONSTRAINT pi_budget_chk        CHECK (budget_check_result IS NULL OR budget_check_result IN (
        'PASSED','WARNED','OVERRIDE','BLOCKED','EXEMPT')),
    CONSTRAINT pi_no_self_reversal  CHECK (reversal_of_id IS DISTINCT FROM id),
    CONSTRAINT pi_retention_chk     CHECK (
        retention_pct IS NULL OR retention_pct BETWEEN 0 AND 100),
    CONSTRAINT pi_posting_pair_chk  CHECK ((posted_at IS NULL) = (posted_by IS NULL))
);

COMMENT ON TABLE document.purchase_invoice IS
    'Approvable AP invoice. Four sources: PO_BASED, CONTRACT_BASED, NON_PO, ONE_TIME_VENDOR. '
    'Vendor identity frozen in invoice_party_snapshot + invoice_address_snapshot + invoice_bank_snapshot. '
    'Tax determined by existing engine; tax_amount is a display cache. '
    'Retention creates AP Retention Payable (liability), not a receivable asset.';


-- ============================================================================
-- §9.1  document.purchase_invoice_line
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.purchase_invoice_line (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,

    -- Parent
    purchase_invoice_id     uuid            NOT NULL,
    line_no                 smallint        NOT NULL,

    -- Source line links
    commitment_line_id      uuid,
    goods_receipt_line_id   uuid,
    ses_line_id             uuid,

    -- Item
    item_id                 uuid,
    item_description        text            NOT NULL,
    procurement_type        text            NOT NULL DEFAULT 'goods',
    spend_category_id       uuid,
    business_intent_id      uuid,

    -- Quantity / price
    uom_code                text            NOT NULL,
    quantity                numeric(18,4)   NOT NULL,
    unit_price              numeric(18,4)   NOT NULL,
    price_unit              numeric(18,4)   NOT NULL DEFAULT 1,
    net_amount              numeric(18,4)   GENERATED ALWAYS AS (
                                (quantity * unit_price) / NULLIF(price_unit, 0)
                            ) STORED,

    -- Discounts
    discount_pct            numeric(5,2)    DEFAULT 0,
    discount_amount         numeric(18,4)   DEFAULT 0,

    -- Tax
    tax_group_id            uuid,
    tax_amount              numeric(18,4)   NOT NULL DEFAULT 0,
    withholding_tax_group_id uuid,
    withholding_tax_amount  numeric(18,4)   NOT NULL DEFAULT 0,

    gross_amount            numeric(18,4)   NOT NULL DEFAULT 0,

    -- Dimensions
    cost_center_id          uuid,
    profit_center_id        uuid,
    project_id              uuid,
    site_id                 uuid,
    dimension_set_id        uuid,

    -- Asset
    is_asset                boolean         NOT NULL DEFAULT false,
    asset_category_id       uuid,

    -- Match tracking
    matched_quantity        numeric(18,4)   NOT NULL DEFAULT 0,
    match_status            text            NOT NULL DEFAULT 'unmatched',

    -- Notes & metadata
    notes                   text,
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,
    status                  text            NOT NULL DEFAULT 'open',

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT pil_pkey             PRIMARY KEY (id),
    CONSTRAINT pil_tenant_id_uq     UNIQUE (tenant_id, id),
    CONSTRAINT pil_line_uq          UNIQUE (purchase_invoice_id, line_no),
    CONSTRAINT pil_line_no_chk      CHECK (line_no > 0),
    CONSTRAINT pil_qty_nonzero      CHECK (quantity <> 0),
    CONSTRAINT pil_price_nonneg     CHECK (unit_price >= 0),
    CONSTRAINT pil_price_unit_pos   CHECK (price_unit > 0),
    CONSTRAINT pil_proc_type_chk    CHECK (procurement_type IN (
        'goods','services','mixed','freight','misc')),
    CONSTRAINT pil_match_status_chk CHECK (match_status IN (
        'unmatched','partially_matched','fully_matched','match_exception')),
    CONSTRAINT pil_tax_nonneg       CHECK (tax_amount >= 0),
    CONSTRAINT pil_wht_nonneg       CHECK (withholding_tax_amount >= 0),
    CONSTRAINT pil_discount_chk     CHECK (discount_pct IS NULL OR discount_pct BETWEEN 0 AND 100)
);


-- ============================================================================
-- §5.3  document.invoice_party_snapshot  (identity only; address is separate)
