        'SUPPLIER','REMIT_TO','BILLING','DELIVERY'))
);


-- ============================================================================
-- §5.5  document.invoice_bank_snapshot
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.invoice_bank_snapshot (
    -- Identity
    id                  uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id           uuid            NOT NULL,

    -- Parent invoice
    purchase_invoice_id uuid            NOT NULL,

    -- Bank details
    bank_name           text            NOT NULL,
    bank_country_code   character(2),
    account_holder_name text            NOT NULL,
    account_number      text,
    iban                text,
    swift_bic           text,
    routing_number      text,
    bank_branch         text,

    -- Capture audit (append-only)
    captured_at         timestamptz     NOT NULL DEFAULT now(),
    captured_by         uuid            NOT NULL,

    CONSTRAINT ibs_pkey         PRIMARY KEY (id),
    CONSTRAINT ibs_tenant_id_uq UNIQUE (tenant_id, id),
    CONSTRAINT ibs_invoice_uq   UNIQUE (purchase_invoice_id),
    CONSTRAINT ibs_account_chk  CHECK (account_number IS NOT NULL OR iban IS NOT NULL)
);


-- ============================================================================
-- §5.6  document.invoice_tax_snapshot  (only where legally required)
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.invoice_tax_snapshot (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,

    -- Parent invoice
    purchase_invoice_id     uuid            NOT NULL,
    invoice_line_id         uuid,

    -- Tax determination
    tax_group_id            uuid            NOT NULL,
    tax_component_code      text            NOT NULL,
    tax_rate_schedule_id    uuid,
    tax_base_amount         numeric(18,4)   NOT NULL,
    tax_rate                numeric(7,4)    NOT NULL,
    tax_amount              numeric(18,4)   NOT NULL,
    currency_code           character(3)    NOT NULL,

    -- Flags
    is_recoverable          boolean         NOT NULL DEFAULT true,
    is_withholding          boolean         NOT NULL DEFAULT false,

    -- Capture audit (append-only)
    captured_at             timestamptz     NOT NULL DEFAULT now(),
    captured_by             uuid            NOT NULL,

    CONSTRAINT its_pkey             PRIMARY KEY (id),
    CONSTRAINT its_tenant_id_uq     UNIQUE (tenant_id, id),
    CONSTRAINT its_tax_rate_nonneg  CHECK (tax_rate >= 0),
    CONSTRAINT its_base_nonneg      CHECK (tax_base_amount >= 0)
);

COMMENT ON TABLE document.invoice_tax_snapshot IS
    'Frozen tax determination at invoice time. '
    'Create only where legal/regulatory requirements mandate it. '
    'Otherwise posted tax facts in ledger.tax_calculation are authoritative.';


-- ============================================================================
-- §10.1  document.invoice_match_case
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.invoice_match_case (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,
    company_code_id         uuid            NOT NULL,

    -- Invoice + commitment link
    purchase_invoice_id     uuid            NOT NULL,
    commitment_id           uuid,

    -- Match result
    match_type              text            NOT NULL DEFAULT 'THREE_WAY',
    match_result            text            NOT NULL DEFAULT 'pending',

    -- Variances
    total_quantity_variance numeric(18,4)   NOT NULL DEFAULT 0,
    total_price_variance    numeric(18,4)   NOT NULL DEFAULT 0,
    total_amount_variance   numeric(18,4)   NOT NULL DEFAULT 0,

    -- Exception summary
    has_exceptions          boolean         NOT NULL DEFAULT false,
    exception_count         smallint        NOT NULL DEFAULT 0,

    -- Match event
    matched_at              timestamptz,
    matched_by              uuid,

    -- Metadata
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,
    status                  text            NOT NULL DEFAULT 'pending',

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT imc_pkey         PRIMARY KEY (id),
    CONSTRAINT imc_tenant_id_uq UNIQUE (tenant_id, id),
    CONSTRAINT imc_invoice_uq   UNIQUE (tenant_id, purchase_invoice_id),
    CONSTRAINT imc_type_chk     CHECK (match_type IN (
        'THREE_WAY','TWO_WAY','NO_MATCH','EVALUATED_RECEIPT')),
    CONSTRAINT imc_result_chk   CHECK (match_result IN (
        'pending','matched','matched_with_tolerance',
        'exception','force_matched','rejected')),
    CONSTRAINT imc_status_chk   CHECK (status IN (
        'pending','in_progress','completed','exception','resolved','cancelled')),
    CONSTRAINT imc_exception_nonneg CHECK (exception_count >= 0)
);


-- ============================================================================
-- §10.2  document.match_exception  (per-line; independent workflow routing)
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.match_exception (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,

    -- Parent
    invoice_match_case_id   uuid            NOT NULL,
    invoice_line_id         uuid            NOT NULL,

    -- Exception detail
    exception_type          text            NOT NULL,
    exception_subtype       text,

    -- Variance amounts
    expected_value          numeric(18,4),
    actual_value            numeric(18,4),
    variance_amount         numeric(18,4)   NOT NULL,
    variance_pct            numeric(7,4),
    currency_code           character(3)    NOT NULL,

    -- Tolerance
    tolerance_pct           numeric(5,2),
    tolerance_amount        numeric(18,4),
    is_within_tolerance     boolean         NOT NULL DEFAULT false,

    -- Resolution
    resolution_type         text,
    resolution_notes        text,
    resolved_by             uuid,
    resolved_at             timestamptz,

    -- Workflow
    workflow_request_id     uuid,

    -- Metadata
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,
    status                  text            NOT NULL DEFAULT 'open',

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT me_pkey          PRIMARY KEY (id),
    CONSTRAINT me_tenant_id_uq  UNIQUE (tenant_id, id),
    CONSTRAINT me_type_chk      CHECK (exception_type IN (
        'PRICE_VARIANCE','QUANTITY_VARIANCE','AMOUNT_VARIANCE',
        'MISSING_RECEIPT','DUPLICATE_INVOICE','TAX_VARIANCE',
        'FX_VARIANCE','RETENTION_VARIANCE','ADVANCE_RECOVERY_MISMATCH')),
    CONSTRAINT me_status_chk    CHECK (status IN (
        'open','pending_approval','approved','rejected',
        'force_matched','written_off','cancelled')),
    CONSTRAINT me_resolution_chk CHECK (resolution_type IS NULL OR resolution_type IN (
        'ACCEPTED','FORCE_MATCHED','CREDIT_NOTE_REQUESTED','WRITTEN_OFF',
        'PRICE_ADJUSTMENT','QUANTITY_ADJUSTMENT','REJECTED')),
    CONSTRAINT me_resolved_pair_chk CHECK (
        (resolved_by IS NULL) = (resolved_at IS NULL))
);

COMMENT ON TABLE document.match_exception IS
    'Per-line match variances requiring resolution. Clean matches are tracked on '
    'purchase_invoice_line.match_status + matched_quantity only.';


-- ============================================================================
-- §PT4  document.payment_term_application — invoice × clause evaluation result
-- ============================================================================
-- Moved from 004a_document_payment_terms.sql. Belongs with invoice domain.
-- One row per invoice × clause (× line) evaluation.

CREATE TABLE IF NOT EXISTS document.payment_term_application (
    -- Identity
    id                          uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id                   uuid            NOT NULL,

    -- Invoice + commitment context
    invoice_id                  uuid            NOT NULL,
    invoice_line_id             uuid,
    commitment_id               uuid,

    -- Term reference
    payment_term_id             uuid,
    clause_id                   uuid,
    term_snapshot               jsonb,
    clause_snapshot             jsonb,

    -- Evaluation result
    application_status          text            NOT NULL DEFAULT 'APPLIED',
    clause_type                 text            NOT NULL,
    clause_code                 text            NOT NULL,

    -- Amounts
    calculated_basis_amount     numeric(18,4)   NOT NULL,
    default_pct                 numeric(5,2),
    applied_pct                 numeric(5,2),
    default_amount              numeric(18,4)   NOT NULL,
    applied_amount              numeric(18,4)   NOT NULL,

    -- Edit flags
    is_user_editable            boolean         NOT NULL DEFAULT false,
    evaluation_sequence_no      integer         NOT NULL,
    running_total_amount        numeric(18,4)   NOT NULL DEFAULT 0,
    remaining_balance_amount    numeric(18,4)   NOT NULL DEFAULT 0,
    is_effective                boolean         NOT NULL DEFAULT true,

    -- Reversal / supersession
    reversed_by_application_id  uuid,
    superseded_by_application_id uuid,

    -- Override reason
    system_reason_code          text,
    manual_override_reason      text,

    -- Override workflow
    workflow_request_id         uuid,
    override_requested_by       uuid,
    override_requested_at       timestamptz,
    override_decision           text,
    override_decided_by         uuid,
    override_decided_at         timestamptz,

    -- Due date fields
    schedule_id                 uuid,
    base_event_date             date,
    days_applied                smallint,
    resolved_due_date           date,

    -- Metadata
    metadata                    jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Audit
    created_at                  timestamptz     NOT NULL DEFAULT now(),
    created_by                  uuid            NOT NULL,
    updated_at                  timestamptz,
    updated_by                  uuid,

    CONSTRAINT pta_pkey                     PRIMARY KEY (id),
    CONSTRAINT pta_tenant_id_uq             UNIQUE (tenant_id, id),
    CONSTRAINT pta_status_chk               CHECK (application_status IN (
        'APPLIED','SKIPPED','CLAMPED','EXHAUSTED','NOT_YET_ELIGIBLE')),
    CONSTRAINT pta_clause_type_chk          CHECK (clause_type IN (
        'ADVANCE','ADVANCE_RECOVERY','RETENTION','RETENTION_RELEASE','DUE_DATE')),
    CONSTRAINT pta_system_reason_chk        CHECK (system_reason_code IS NULL
        OR system_reason_code IN (
        'CEILING_CLAMPED','CEILING_REACHED','THRESHOLD_NOT_MET',
        'CAP_EXHAUSTED','CATCH_UP','FLEXIBILITY_APPLIED')),
    CONSTRAINT pta_override_decision_chk    CHECK (override_decision IS NULL
        OR override_decision IN ('approve','reject','escalate')),
    CONSTRAINT pta_term_snap_chk            CHECK (
        term_snapshot IS NULL OR jsonb_typeof(term_snapshot) = 'object'),
    CONSTRAINT pta_clause_snap_chk          CHECK (
        clause_snapshot IS NULL OR jsonb_typeof(clause_snapshot) = 'object'),
    CONSTRAINT pta_basis_nonneg             CHECK (calculated_basis_amount >= 0),
    CONSTRAINT pta_default_amt_nonneg       CHECK (default_amount >= 0),
    CONSTRAINT pta_applied_nonneg           CHECK (applied_amount >= 0),
    CONSTRAINT pta_running_nonneg           CHECK (running_total_amount >= 0),
    CONSTRAINT pta_remaining_nonneg         CHECK (remaining_balance_amount >= 0),
    CONSTRAINT pta_eval_seq_positive        CHECK (evaluation_sequence_no > 0),
    CONSTRAINT pta_override_reason_chk      CHECK (
        manual_override_reason IS NOT NULL
        OR system_reason_code IS NOT NULL
        OR (
            (applied_pct IS NULL OR default_pct IS NULL OR applied_pct = default_pct)
            AND applied_amount = default_amount
        )),
    CONSTRAINT pta_no_self_reverse          CHECK (reversed_by_application_id IS DISTINCT FROM id),
    CONSTRAINT pta_no_self_supersede        CHECK (superseded_by_application_id IS DISTINCT FROM id),
    CONSTRAINT pta_reversal_effective_chk   CHECK (
        reversed_by_application_id IS NULL OR is_effective = false),
    CONSTRAINT pta_override_consistency_chk CHECK (
        override_decision IS NULL
        OR (override_decided_by IS NOT NULL AND override_decided_at IS NOT NULL)),
    CONSTRAINT pta_deduction_needs_commitment CHECK (
        commitment_id IS NOT NULL
        OR clause_type NOT IN ('ADVANCE','ADVANCE_RECOVERY','RETENTION','RETENTION_RELEASE')),
    CONSTRAINT pta_schedule_needs_commitment CHECK (
        schedule_id IS NULL OR commitment_id IS NOT NULL),
    CONSTRAINT pta_due_date_req_chk CHECK (
        clause_type <> 'DUE_DATE' OR resolved_due_date IS NOT NULL),
    CONSTRAINT pta_due_date_no_clause_chk CHECK (
        clause_type <> 'DUE_DATE' OR clause_id IS NULL),
    CONSTRAINT pta_due_date_code_chk CHECK (
        clause_type <> 'DUE_DATE' OR clause_code = 'DUE_DATE'),
    CONSTRAINT pta_due_date_base_chk CHECK (
        clause_type <> 'DUE_DATE' OR base_event_date IS NOT NULL),
    CONSTRAINT pta_nonpo_snapshot_chk CHECK (
        commitment_id IS NOT NULL OR term_snapshot IS NOT NULL),
    CONSTRAINT pta_nonpo_term_ref_chk CHECK (
        commitment_id IS NOT NULL OR payment_term_id IS NOT NULL)
);

CREATE UNIQUE INDEX IF NOT EXISTS pta_invoice_clause_uq
    ON document.payment_term_application (
        invoice_id, clause_code,
        COALESCE(invoice_line_id, '00000000-0000-0000-0000-000000000000'),
        evaluation_sequence_no
    );

COMMENT ON TABLE document.payment_term_application IS
    'Invoice × clause evaluation result. One row per invoice × clause (× line) evaluation.';

-- FILE: /d/Products/athyper/server/db/sql/04_tables/004e_document_payment.sql
-- 04_tables/004e_document_payment.sql
-- Scope: Payment document tables
-- Domain: payment_entry, payment_entry_allocation,
--         payment_remittance_output, payment_term_discount_result
-- Depends on: 01_schemas, 04_tables/003_master.sql, 03d_master_payment_terms.sql,
--             04_tables/004_document.sql (workflow_request, render_output),
--             04_tables/004b_document_commitment.sql (commitment),
--             04_tables/004d_document_invoice.sql (purchase_invoice, payment_term_application)
-- Load order: 004e (after 004d_document_invoice.sql)

-- ============================================================================
-- §11  document.payment_entry  (approvable)
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.payment_entry (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,
    company_code_id         uuid            NOT NULL,

    -- Natural key
    payment_number          text            NOT NULL,

    -- Classification
    payment_type            text            NOT NULL DEFAULT 'STANDARD',
    payment_direction       text            NOT NULL DEFAULT 'OUTBOUND',

    -- Counterparty
    supplier_id             uuid,
    supplier_name           text            NOT NULL,

    -- Payment method + bank
    payment_method_id       uuid            NOT NULL,
    bank_account_id         uuid,
    supplier_bank_link_id   uuid,

    -- Reference numbers
    payment_reference       text,
    bank_reference          text,
    check_number            text,

    -- Dates
    document_date           date            NOT NULL DEFAULT CURRENT_DATE,
    posting_date            date            NOT NULL DEFAULT CURRENT_DATE,
    value_date              date            NOT NULL DEFAULT CURRENT_DATE,

    -- Amounts
    currency_code           character(3)    NOT NULL,
    base_currency_code      character(3)    NOT NULL,
    exchange_rate           numeric(18,10),
    payment_amount          numeric(18,4)   NOT NULL,
    base_amount             numeric(18,4),

    -- Payment currency (third leg when paying in a different currency)
    payment_currency_code   character(3),
    payment_exchange_rate   numeric(18,10),
    payment_currency_amount numeric(18,4),

    -- Fiscal scope
    fiscal_year             smallint        NOT NULL,
    period_number           smallint        NOT NULL,

    -- Posting
    payment_je_id           uuid,
    is_posted               boolean         NOT NULL DEFAULT false,
    posted_at               timestamptz,
    posted_by               uuid,

    -- Reversal
    is_reversal             boolean         NOT NULL DEFAULT false,
    reversal_of_id          uuid,
    reversal_reason         text,

    -- Workflow
    workflow_request_id     uuid,
    approved_at             timestamptz,
    approved_by             uuid,

    -- Batch payment
    payment_run_id          uuid,
    is_batch_payment        boolean         NOT NULL DEFAULT false,

    -- Transmission
    is_printed              boolean         NOT NULL DEFAULT false,
    is_transmitted          boolean         NOT NULL DEFAULT false,
    transmission_status     text,

    -- Void
    is_voided               boolean         NOT NULL DEFAULT false,
    voided_at               timestamptz,
    voided_by               uuid,
    void_reason             text,

    -- Bank reconciliation
    cleared_date            date,

    -- Line count + notes
    line_count              smallint        NOT NULL DEFAULT 0,
    notes                   text,

    -- Tags & Metadata
    tags                    jsonb           NOT NULL DEFAULT '[]'::jsonb,
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Lifecycle
    status                  text            NOT NULL DEFAULT 'draft',
    is_active               boolean         GENERATED ALWAYS AS (
                                status IN ('draft','pending_approval','approved','posted',
                                           'transmitted','printed')
                            ) STORED,
    status_changed_at       timestamptz,
    status_changed_by       uuid,

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT pe_pkey              PRIMARY KEY (id),
    CONSTRAINT pe_tenant_id_uq      UNIQUE (tenant_id, id),
    CONSTRAINT pe_tenant_number_uq  UNIQUE (tenant_id, company_code_id, payment_number),
    CONSTRAINT pe_number_nonempty   CHECK (btrim(payment_number) <> ''),
    CONSTRAINT pe_status_chk        CHECK (status IN (
        'draft','pending_approval','approved','posted','transmitted',
        'printed','cleared','reversed','voided','cancelled','rejected')),
    CONSTRAINT pe_type_chk          CHECK (payment_type IN (
        'STANDARD','ADVANCE','RETENTION_RELEASE','PARTIAL','FINAL',
        'DOWN_PAYMENT','URGENT','NETTING')),
    CONSTRAINT pe_direction_chk     CHECK (payment_direction IN ('OUTBOUND','INBOUND')),
    CONSTRAINT pe_amount_pos        CHECK (payment_amount > 0),
    CONSTRAINT pe_period_chk        CHECK (period_number BETWEEN 1 AND 16),
    CONSTRAINT pe_no_self_reversal  CHECK (reversal_of_id IS DISTINCT FROM id),
    CONSTRAINT pe_void_chk          CHECK (NOT is_voided OR voided_at IS NOT NULL),
    CONSTRAINT pe_posting_pair_chk  CHECK ((posted_at IS NULL) = (posted_by IS NULL))
);

COMMENT ON TABLE document.payment_entry IS
    'Approvable AP payment. Accounting driven by control.payment_settlement_rule posting roles. '
    'Settlement posting: Dr AP Trade Payable → Cr Bank + optional Cr Discount Income + Dr/Cr FX.';


-- ============================================================================
-- §11.1  document.payment_entry_allocation
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.payment_entry_allocation (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,

    -- Parent payment
    payment_entry_id        uuid            NOT NULL,
    line_no                 smallint        NOT NULL,

    -- Allocated document
    purchase_invoice_id     uuid,
    commitment_id           uuid,

    -- Amounts
    currency_code           character(3)    NOT NULL,
    allocated_amount        numeric(18,4)   NOT NULL,
    discount_amount         numeric(18,4)   NOT NULL DEFAULT 0,
    withholding_tax_amount  numeric(18,4)   NOT NULL DEFAULT 0,
    advance_recovery_amount numeric(18,4)   NOT NULL DEFAULT 0,
    retention_amount        numeric(18,4)   NOT NULL DEFAULT 0,
    net_payment_amount      numeric(18,4)   GENERATED ALWAYS AS (
                                allocated_amount - discount_amount - withholding_tax_amount
                                - advance_recovery_amount - retention_amount
                            ) STORED,

    -- FX
    base_currency_code      character(3),
    exchange_rate           numeric(18,10),
    base_amount             numeric(18,4),
    fx_gain_loss            numeric(18,4)   NOT NULL DEFAULT 0,

    -- Discount
    is_discount_taken       boolean         NOT NULL DEFAULT false,
    discount_due_date       date,
    payment_term_application_id uuid,

    -- Notes & metadata
    notes                   text,
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Audit (append-only)
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,

    CONSTRAINT pea_pkey                     PRIMARY KEY (id),
    CONSTRAINT pea_tenant_id_uq             UNIQUE (tenant_id, id),
    CONSTRAINT pea_line_uq                  UNIQUE (payment_entry_id, line_no),
    CONSTRAINT pea_line_no_chk              CHECK (line_no > 0),
    CONSTRAINT pea_allocated_pos            CHECK (allocated_amount > 0),
    CONSTRAINT pea_invoice_or_cmt           CHECK (
        purchase_invoice_id IS NOT NULL OR commitment_id IS NOT NULL),
    CONSTRAINT pea_deductions_lte_allocated CHECK (
        discount_amount + withholding_tax_amount
        + advance_recovery_amount + retention_amount
        <= allocated_amount),
    CONSTRAINT pea_deductions_nonneg        CHECK (
        discount_amount >= 0
        AND withholding_tax_amount >= 0
        AND advance_recovery_amount >= 0
        AND retention_amount >= 0)
);


-- ============================================================================
-- §11.2  document.payment_remittance_output
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.payment_remittance_output (
    -- Identity
    id                  uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id           uuid            NOT NULL,
    company_code_id     uuid            NOT NULL,

    -- Natural key
    remittance_number   text            NOT NULL,

    -- Parent payment + supplier
    payment_entry_id    uuid            NOT NULL,
    supplier_id         uuid            NOT NULL,

    -- Amounts
    currency_code       character(3)    NOT NULL,
    total_amount        numeric(18,4)   NOT NULL,
    net_remitted        numeric(18,4)   NOT NULL,

    -- Delivery
    delivery_method     text            NOT NULL DEFAULT 'EMAIL',
    delivered_at        timestamptz,
    delivery_status     text            NOT NULL DEFAULT 'pending',

    -- Render output link
    render_output_id    uuid,

    -- Metadata
    metadata            jsonb           NOT NULL DEFAULT '{}'::jsonb,
    status              text            NOT NULL DEFAULT 'draft',

    -- Audit
    created_at          timestamptz     NOT NULL DEFAULT now(),
    created_by          uuid            NOT NULL,
    updated_at          timestamptz,
    updated_by          uuid,

    CONSTRAINT pro_pkey             PRIMARY KEY (id),
    CONSTRAINT pro_tenant_id_uq     UNIQUE (tenant_id, id),
    CONSTRAINT pro_tenant_number_uq UNIQUE (tenant_id, company_code_id, remittance_number),
    CONSTRAINT pro_delivery_chk     CHECK (delivery_method IN (
        'EMAIL','PORTAL','EDI','FAX','PRINT','API')),
    CONSTRAINT pro_delivery_status_chk CHECK (delivery_status IN (
        'pending','sent','delivered','failed','bounced')),
    CONSTRAINT pro_status_chk       CHECK (status IN (
        'draft','generated','sent','delivered','failed','cancelled'))
);


-- ============================================================================
-- §PT5  document.payment_term_discount_result — settlement-time discount
-- ============================================================================
-- Moved from 004a_document_payment_terms.sql. Belongs with payment domain.
-- Reversals use is_reversal + reverses_id (append-only).

CREATE TABLE IF NOT EXISTS document.payment_term_discount_result (
    -- Identity
    id                          uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id                   uuid            NOT NULL,

    -- Payment + invoice context
    payment_id                  uuid            NOT NULL,
    invoice_id                  uuid            NOT NULL,
    commitment_id               uuid,

    -- Term reference
    payment_term_id             uuid,
    discount_tier_id            uuid,

    -- Amounts
    allocated_payment_amount    numeric(18,4)   NOT NULL,
    qualification_date          date            NOT NULL,
    qualified_tier_no           smallint,
    qualified_days_actual       smallint        NOT NULL,
    discount_basis_amount       numeric(18,4)   NOT NULL,
    discount_pct                numeric(5,2),
    discount_amount             numeric(18,4)   NOT NULL,

    -- Result
    application_status          text            NOT NULL,
    is_reversal                 boolean         NOT NULL DEFAULT false,
    reverses_id                 uuid,

    -- Metadata
    metadata                    jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Audit (append-only)
    created_at                  timestamptz     NOT NULL DEFAULT now(),
    created_by                  uuid            NOT NULL,

    CONSTRAINT ptdr_pkey                PRIMARY KEY (id),
    CONSTRAINT ptdr_tenant_id_uq        UNIQUE (tenant_id, id),
    CONSTRAINT ptdr_status_chk          CHECK (application_status IN (
        'QUALIFIED','NOT_QUALIFIED','PARTIAL','WAIVED','EXPIRED','REVERSED')),
    CONSTRAINT ptdr_basis_nonneg        CHECK (discount_basis_amount >= 0),
    CONSTRAINT ptdr_alloc_nonneg        CHECK (allocated_payment_amount >= 0),
    CONSTRAINT ptdr_discount_nonneg     CHECK (discount_amount >= 0),
    CONSTRAINT ptdr_days_nonneg         CHECK (qualified_days_actual >= 0),
    CONSTRAINT ptdr_pct_range           CHECK (discount_pct IS NULL OR discount_pct BETWEEN 0 AND 100),
    CONSTRAINT ptdr_no_self_reverse     CHECK (reverses_id IS DISTINCT FROM id),
    CONSTRAINT ptdr_reversal_ref_chk    CHECK (NOT is_reversal OR reverses_id IS NOT NULL),
    CONSTRAINT ptdr_nonpo_term_ref_chk  CHECK (
        commitment_id IS NOT NULL OR payment_term_id IS NOT NULL)
);

CREATE UNIQUE INDEX IF NOT EXISTS ptdr_payment_invoice_tier_uq
    ON document.payment_term_discount_result (
        payment_id, invoice_id, COALESCE(qualified_tier_no, 0)
    )
    WHERE is_reversal = false;

CREATE UNIQUE INDEX IF NOT EXISTS ptdr_single_reversal_uq
    ON document.payment_term_discount_result (reverses_id)
    WHERE is_reversal = true;

COMMENT ON TABLE document.payment_term_discount_result IS
    'Settlement-time discount realization. Reversals use is_reversal + reverses_id (append-only).';

-- FILE: /d/Products/athyper/server/db/sql/04_tables/004f_document_assets.sql
-- 04_tables/004f_document_assets.sql
-- Scope: Fixed Asset Transaction document tables
-- Domain: asset_transaction, depreciation_run, depreciation_run_line,
--         depreciation_schedule
-- Depends on: 01_schemas, 04_tables/003_master.sql,
--             04_tables/004a_document_journal.sql (journal_entry)
-- Load order: 004f (after 004a_document_journal.sql)

-- =============================================================================
-- §AT1  document.asset_transaction — asset lifecycle events
-- =============================================================================
-- Capitalize, depreciate, revalue, impair, dispose, transfer, retire, adjust.
-- asset_book_id is the authoritative book link. book_type is denormalized
-- convenience. Consistency enforced by document.trg_asset_txn_book_guard().

CREATE TABLE IF NOT EXISTS document.asset_transaction (
    -- Identity
    id               uuid         NOT NULL DEFAULT shared.uuidv7(),
    tenant_id        uuid         NOT NULL,
    code             text         NOT NULL DEFAULT '',
    name             text         NOT NULL DEFAULT '',

    -- Company scope (Tier 1 UUID)
    company_code_id  uuid         NOT NULL,

    -- Asset + book linkage
    asset_id                 uuid         NOT NULL,
    asset_book_id            uuid,
    book_type                text,
    txn_type                 text         NOT NULL,

    -- Amounts
    amount                   numeric(18,4) NOT NULL,
    currency_code            character(3) NOT NULL DEFAULT 'USD',

    -- Period alignment
    effective_date           date         NOT NULL,
    fiscal_year              smallint     NOT NULL,
    period_number            smallint     NOT NULL,

    -- State capture
    from_values              jsonb,
    to_values                jsonb,

    -- Linkage
    reference_je_id          uuid,
    depreciation_run_id      uuid,
    depreciation_run_line_id uuid,

    -- Reversal support
    reversal_of_id           uuid,
    is_reversal              boolean      NOT NULL DEFAULT false,

    -- Actor tracking
    performed_by             uuid         NOT NULL,
    performed_at             timestamptz  NOT NULL DEFAULT now(),
    notes                    text,

    -- Posting
    posted_at                timestamptz,
    posted_by                uuid,

    -- Tags & Metadata
    tags             jsonb        NOT NULL DEFAULT '[]'::jsonb,
    metadata         jsonb        NOT NULL DEFAULT '{}'::jsonb,

    -- Lifecycle
    status           text         NOT NULL DEFAULT 'draft',
    is_active        boolean      GENERATED ALWAYS AS (status IN ('draft', 'posted')) STORED,
    status_changed_at timestamptz,
    status_changed_by uuid,

    -- Audit
    created_at       timestamptz  NOT NULL DEFAULT now(),
    created_by       uuid         NOT NULL,
    updated_at       timestamptz,
    updated_by       uuid,

    CONSTRAINT asset_txn_pkey           PRIMARY KEY (id),
    CONSTRAINT asset_txn_tenant_id_uq   UNIQUE (tenant_id, id),
    CONSTRAINT asset_txn_reversal_chk   CHECK (
        (is_reversal = false AND reversal_of_id IS NULL)
        OR (is_reversal = true AND reversal_of_id IS NOT NULL)
    )
);

COMMENT ON TABLE document.asset_transaction IS
    'Asset lifecycle events. Links to asset_book_id (authoritative) and retains '
    'book_type as denormalized convenience. Consistency enforced by trigger.';


-- =============================================================================
-- §AT2  document.depreciation_run — batch depreciation run header
-- =============================================================================
-- Idempotency enforced via conditional unique index on idempotency_key.

CREATE TABLE IF NOT EXISTS document.depreciation_run (
    -- Identity
    id               uuid         NOT NULL DEFAULT shared.uuidv7(),
    tenant_id        uuid         NOT NULL,
    code             text         NOT NULL DEFAULT '',
    name             text         NOT NULL DEFAULT '',

    -- Company scope (Tier 1 UUID)
    company_code_id  uuid         NOT NULL,

    -- Book + period
    book_type                text         NOT NULL,
    book_id                  uuid,
    fiscal_year              smallint     NOT NULL,
    period_number            smallint     NOT NULL,

    -- Run metrics
    asset_count              integer      NOT NULL DEFAULT 0,
    total_amount             numeric(18,4) NOT NULL DEFAULT 0,
    currency_code            character(3) NOT NULL DEFAULT 'USD',
    error_count              integer      NOT NULL DEFAULT 0,
    error_log                jsonb,

    -- Timing
    started_at               timestamptz,
    completed_at             timestamptz,

    -- Linkage
    reference_je_id          uuid,

    -- Reversal
    reversal_of_id           uuid,
    is_reversal              boolean      NOT NULL DEFAULT false,

    -- Actor
    run_by                   uuid         NOT NULL,

    -- Idempotency
    idempotency_key          text,

    -- Posting
    posted_at                timestamptz,
    posted_by                uuid,

    -- Metadata
    metadata         jsonb        NOT NULL DEFAULT '{}'::jsonb,

    -- Lifecycle
    status           text         NOT NULL DEFAULT 'planned',
    is_active        boolean      GENERATED ALWAYS AS (status IN ('planned', 'running')) STORED,
    status_changed_at timestamptz,
    status_changed_by uuid,

    -- Audit
    created_at       timestamptz  NOT NULL DEFAULT now(),
    created_by       uuid         NOT NULL,
    updated_at       timestamptz,
    updated_by       uuid,

    CONSTRAINT depreciation_run_pkey           PRIMARY KEY (id),
    CONSTRAINT depreciation_run_tenant_id_uq   UNIQUE (tenant_id, id),
    CONSTRAINT depreciation_run_period_book_uq
        UNIQUE (tenant_id, company_code_id, book_type, fiscal_year, period_number, is_reversal),
    CONSTRAINT depreciation_run_reversal_chk   CHECK (
        (is_reversal = false AND reversal_of_id IS NULL)
        OR (is_reversal = true AND reversal_of_id IS NOT NULL)
    ),
    CONSTRAINT depreciation_run_error_count_pos CHECK (error_count >= 0)
);

COMMENT ON TABLE document.depreciation_run IS
    'Batch depreciation run header. Idempotency enforced via conditional '
    'unique index on (tenant_id, company_code_id, idempotency_key).';


-- =============================================================================
-- §AT3  document.depreciation_run_line — per-asset run detail
-- =============================================================================
-- Asset/book mismatch prevented by composite FK (tenant_id, asset_book_id, asset_id)
-- referencing master.asset_book (tenant_id, id, asset_id).
-- This table is immutable after creation (log.trg_prevent_mutation).

CREATE TABLE IF NOT EXISTS document.depreciation_run_line (
    -- Identity
    id               uuid         NOT NULL DEFAULT shared.uuidv7(),
    tenant_id        uuid         NOT NULL,

    -- Parent run + asset
    run_id                   uuid         NOT NULL,
    asset_id                 uuid         NOT NULL,
    asset_book_id            uuid         NOT NULL,

    -- Calculated amounts
    depreciation_amount      numeric(18,4) NOT NULL,
    currency_code            character(3) NOT NULL DEFAULT 'USD',

    -- Book values at time of calculation (snapshot)
    cost_basis_at_run        numeric(18,4) NOT NULL,
    accum_depr_before        numeric(18,4) NOT NULL,
    accum_depr_after         numeric(18,4) NOT NULL,
    nbv_after                numeric(18,4) NOT NULL,

    -- Method applied
    depreciation_method      text         NOT NULL,
    useful_life_months       integer      NOT NULL,
    remaining_life_months    integer      NOT NULL,

    -- Linkage to asset_transaction
    asset_transaction_id     uuid,

    -- Line status
    line_status              text         NOT NULL DEFAULT 'calculated',
    error_message            text,

    -- Audit (immutable — no updated_at)
    created_at       timestamptz  NOT NULL DEFAULT now(),
    created_by       uuid         NOT NULL,

    CONSTRAINT depreciation_run_line_pkey           PRIMARY KEY (id),
    CONSTRAINT depreciation_run_line_tenant_id_uq   UNIQUE (tenant_id, id),
    CONSTRAINT depreciation_run_line_run_asset_uq   UNIQUE (run_id, asset_book_id),
    CONSTRAINT depreciation_run_line_amount_pos     CHECK (depreciation_amount >= 0)
);

COMMENT ON TABLE document.depreciation_run_line IS
    'Per-asset line detail within a depreciation run. Reconcilable to run header total. '
    'Asset/book mismatch prevented by composite FK (tenant_id, asset_book_id, asset_id). '
    'Immutable after creation — log.trg_prevent_mutation blocks UPDATE/DELETE.';


-- =============================================================================
-- §AT4  document.depreciation_schedule — planned month-by-month projection
-- =============================================================================
-- Supports versioning and plan-vs-actual via generated variance_amount.

CREATE TABLE IF NOT EXISTS document.depreciation_schedule (
    -- Identity
    id               uuid         NOT NULL DEFAULT shared.uuidv7(),
    tenant_id        uuid         NOT NULL,

    -- Asset book + version
    asset_book_id            uuid         NOT NULL,
    schedule_version         smallint     NOT NULL DEFAULT 1,

    -- Period identification
    fiscal_year              smallint     NOT NULL,
    period_number            smallint     NOT NULL,
    period_date              date         NOT NULL,

    -- Planned amounts
    schedule_amount          numeric(18,4) NOT NULL,
    cumulative_amount        numeric(18,4) NOT NULL,
    opening_nbv              numeric(18,4) NOT NULL,
    closing_nbv              numeric(18,4) NOT NULL,
    currency_code            character(3) NOT NULL DEFAULT 'USD',

    -- Actual (populated after depreciation run)
    actual_amount            numeric(18,4),
    actual_run_line_id       uuid,
    variance_amount          numeric(18,4) GENERATED ALWAYS AS
                                 (CASE WHEN actual_amount IS NOT NULL
                                       THEN actual_amount - schedule_amount
                                       ELSE NULL END) STORED,

    -- Flags
    is_final_period          boolean      NOT NULL DEFAULT false,
    notes                    text,

    -- Audit
    created_at       timestamptz  NOT NULL DEFAULT now(),
    created_by       uuid         NOT NULL,
    updated_at       timestamptz,
    updated_by       uuid,

    CONSTRAINT depreciation_schedule_pkey PRIMARY KEY (id),
    CONSTRAINT depreciation_schedule_tenant_id_uq UNIQUE (tenant_id, id),
    CONSTRAINT depreciation_schedule_book_ver_period_uq
        UNIQUE (asset_book_id, schedule_version, fiscal_year, period_number),
    CONSTRAINT depreciation_schedule_amount_pos CHECK (schedule_amount >= 0),
    CONSTRAINT depreciation_schedule_cum_pos   CHECK (cumulative_amount >= 0)
);

COMMENT ON TABLE document.depreciation_schedule IS
    'Planned month-by-month depreciation projection per asset_book. '
    'Supports versioning and plan-vs-actual via generated variance_amount.';

