-- ============================================================================
-- §ICA1  document.intercompany_agreement — IC transfer pricing rulebook
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.intercompany_agreement (
    -- Identity
    id                          uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id                   uuid            NOT NULL,
    code                        text            NOT NULL DEFAULT '',
    name                        text            NOT NULL DEFAULT '',
    company_code_id             uuid            NOT NULL,

    -- Natural key
    agreement_number            text            NOT NULL,

    -- Classification
    source_company_code_id      uuid            NOT NULL,
    dest_company_code_id        uuid            NOT NULL,
    agreement_type              text            NOT NULL,
    description                 text,

    -- Transfer pricing
    transfer_pricing_method     text            NOT NULL,
    markup_pct                  numeric(7,4),
    arm_length_basis            text,

    -- Amounts
    currency_code               character(3)    NOT NULL,
    base_currency_code          character(3),
    annual_value                numeric(18,4),
    total_value                 numeric(18,4),

    -- Dates
    effective_from              date            NOT NULL,
    effective_to                date,

    -- Conflict resolution
    priority                    smallint        NOT NULL DEFAULT 0,
    conflict_strategy           text            NOT NULL DEFAULT 'HIGHEST_PRIORITY',

    -- Versioning
    version                     smallint        NOT NULL DEFAULT 1,
    supersedes_id               uuid,

    -- Dimensions
    cost_center_id              uuid,
    profit_center_id            uuid,
    project_id                  uuid,
    site_id                     uuid,
    dimension_set_id            uuid,

    -- Ownership + workflow
    agreement_owner_id          uuid,
    approved_at                 timestamptz,
    approved_by                 uuid,
    workflow_request_id         uuid,

    -- Tags & Metadata
    tags                        jsonb           NOT NULL DEFAULT '[]'::jsonb,
    metadata                    jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Lifecycle
    status                      text            NOT NULL DEFAULT 'draft',
    is_active                   boolean         GENERATED ALWAYS AS (
                                    status IN ('draft', 'active')
                                ) STORED,
    status_changed_at           timestamptz,
    status_changed_by           uuid,

    -- Audit
    created_at                  timestamptz     NOT NULL DEFAULT now(),
    created_by                  uuid            NOT NULL,
    updated_at                  timestamptz,
    updated_by                  uuid,

    CONSTRAINT ica_pkey              PRIMARY KEY (id),
    CONSTRAINT ica_tenant_id_uq      UNIQUE (tenant_id, id),
    CONSTRAINT ica_tenant_number_uq  UNIQUE (tenant_id, company_code_id, agreement_number),
    CONSTRAINT ica_number_nonempty   CHECK (btrim(agreement_number) <> ''),
    CONSTRAINT ica_entity_chk        CHECK (source_company_code_id IS DISTINCT FROM dest_company_code_id),
    CONSTRAINT ica_agreement_type_chk CHECK (agreement_type IN (
        'GOODS','SERVICES','LOAN','ROYALTY','MANAGEMENT_FEE','COST_SHARING','OTHER')),
    CONSTRAINT ica_tp_method_chk     CHECK (transfer_pricing_method IN (
        'CUP','COST_PLUS','RESALE_MINUS','TNMM','PROFIT_SPLIT','COMPARABLE_PROFIT','OTHER')),
    CONSTRAINT ica_markup_chk        CHECK (markup_pct IS NULL OR markup_pct BETWEEN -100 AND 1000),
    CONSTRAINT ica_conflict_chk      CHECK (conflict_strategy IN (
        'HIGHEST_PRIORITY','MOST_SPECIFIC','ERROR_ON_CONFLICT')),
    CONSTRAINT ica_effective_date_chk CHECK (effective_to IS NULL OR effective_to >= effective_from),
    CONSTRAINT ica_no_self_supersede CHECK (supersedes_id IS DISTINCT FROM id),
    CONSTRAINT ica_status_chk        CHECK (status IN (
        'draft','active','suspended','superseded','expired','cancelled')),
    CONSTRAINT ica_priority_chk      CHECK (priority >= 0),
    CONSTRAINT ica_version_chk       CHECK (version >= 1)
);

COMMENT ON TABLE document.intercompany_agreement IS
    'IC transfer pricing agreement between two company codes. '
    'OECD methods: CUP, COST_PLUS, RESALE_MINUS, TNMM, PROFIT_SPLIT, COMPARABLE_PROFIT. '
    'Conflict resolution via priority + conflict_strategy. '
    'Version chain via supersedes_id. Status: draft → active → suspended|superseded|expired|cancelled.';


-- ============================================================================
-- §ICA2  document.intercompany_transaction — bilateral IC billing events
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.intercompany_transaction (
    -- Identity
    id                          uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id                   uuid            NOT NULL,
    code                        text            NOT NULL DEFAULT '',
    name                        text            NOT NULL DEFAULT '',
    company_code_id             uuid            NOT NULL,

    -- Natural key
    ic_txn_number               text            NOT NULL,

    -- Parties
    source_company_code_id      uuid            NOT NULL,
    dest_company_code_id        uuid            NOT NULL,

    -- Classification
    txn_type                    text            NOT NULL,

    -- Dates
    document_date               date            NOT NULL,
    posting_date                date            NOT NULL,

    -- Amounts
    currency_code               character(3)    NOT NULL,
    amount                      numeric(18,4)   NOT NULL,

    -- Transfer pricing
    agreement_id                uuid,
    transfer_price              numeric(18,4),
    arm_length_price            numeric(18,4),
    pricing_variance            numeric(18,4)   GENERATED ALWAYS AS (
                                    transfer_price - arm_length_price
                                ) STORED,

    -- Base currency
    base_currency_code          character(3)    NOT NULL,
    exchange_rate               numeric(18,10),
    base_amount                 numeric(18,4),

    -- GL linkage
    source_je_id                uuid,
    dest_je_id                  uuid,

    -- Mirror
    mirror_txn_id               uuid,
    is_mirror                   boolean         NOT NULL DEFAULT false,

    -- Match
    match_status                text            NOT NULL DEFAULT 'UNMATCHED',
    matched_at                  timestamptz,
    discrepancy_amount          numeric(18,4),
    discrepancy_reason          text,

    -- Netting
    netting_batch_id            uuid,

    -- Fiscal scope
    fiscal_year                 smallint        NOT NULL,
    period_number               smallint,

    -- Dimensions
    cost_center_id              uuid,
    profit_center_id            uuid,
    project_id                  uuid,
    site_id                     uuid,
    dimension_set_id            uuid,

    -- Narrative
    description                 text,

    -- Tags & Metadata
    tags                        jsonb           NOT NULL DEFAULT '[]'::jsonb,
    metadata                    jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Lifecycle
    status                      text            NOT NULL DEFAULT 'draft',
    is_active                   boolean         GENERATED ALWAYS AS (
                                    status IN ('draft','created','posted','netted')
                                ) STORED,
    status_changed_at           timestamptz,
    status_changed_by           uuid,

    -- Posting
    posted_at                   timestamptz,
    posted_by                   uuid,

    -- Audit
    created_at                  timestamptz     NOT NULL DEFAULT now(),
    created_by                  uuid            NOT NULL,
    updated_at                  timestamptz,
    updated_by                  uuid,

    CONSTRAINT ict_pkey              PRIMARY KEY (id),
    CONSTRAINT ict_tenant_id_uq      UNIQUE (tenant_id, id),
    CONSTRAINT ict_tenant_number_uq  UNIQUE (tenant_id, company_code_id, ic_txn_number),
    CONSTRAINT ict_number_nonempty   CHECK (btrim(ic_txn_number) <> ''),
    CONSTRAINT ict_entity_chk        CHECK (source_company_code_id IS DISTINCT FROM dest_company_code_id),
    CONSTRAINT ict_type_chk          CHECK (txn_type IN (
        'RECHARGE','PURCHASE','SALE','LOAN_DRAWDOWN','LOAN_REPAYMENT',
        'ROYALTY','MANAGEMENT_FEE','COST_ALLOCATION','DIVIDEND','OTHER')),
    CONSTRAINT ict_doc_date_chk      CHECK (document_date <= posting_date),
    CONSTRAINT ict_amount_positive   CHECK (amount > 0),
    CONSTRAINT ict_match_status_chk  CHECK (match_status IN (
        'UNMATCHED','MATCHED','DISPUTED','PARTIALLY_MATCHED')),
    CONSTRAINT ict_status_chk        CHECK (status IN (
        'draft','created','posted','netted','settled','disputed','cancelled','reversed')),
    CONSTRAINT ict_no_self_mirror    CHECK (mirror_txn_id IS DISTINCT FROM id),
    CONSTRAINT ict_fx_rate_chk       CHECK (currency_code = base_currency_code OR exchange_rate IS NOT NULL),
    CONSTRAINT ict_period_chk        CHECK (period_number IS NULL OR period_number BETWEEN 1 AND 16)
);

COMMENT ON TABLE document.intercompany_transaction IS
    'IC billing event between two company codes. Dual-currency (transaction + base). '
    'pricing_variance GENERATED (transfer_price - arm_length_price). '
    'Mirror transactions auto-created on counterparty side (is_mirror = true). '
    'Status: draft → created → posted → netted → settled | disputed | reversed.';


-- ============================================================================
-- §ICA3  document.netting_batch — settlement netting header
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.netting_batch (
    -- Identity
    id                          uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id                   uuid            NOT NULL,
    company_code_id             uuid            NOT NULL,

    -- Natural key
    batch_number                text            NOT NULL,

    -- Parties
    company_code_a_id           uuid            NOT NULL,
    company_code_b_id           uuid            NOT NULL,

    -- Dates
    batch_date                  date            NOT NULL,
    cut_off_date                date            NOT NULL,
    settlement_date             date,

    -- Amounts
    currency_code               character(3)    NOT NULL,
    gross_amount_a_to_b         numeric(18,4)   NOT NULL DEFAULT 0,
    gross_amount_b_to_a         numeric(18,4)   NOT NULL DEFAULT 0,
    gross_amount                numeric(18,4)   GENERATED ALWAYS AS (
                                    gross_amount_a_to_b + gross_amount_b_to_a
                                ) STORED,
    net_amount                  numeric(18,4)   NOT NULL DEFAULT 0,
    net_direction               text            NOT NULL DEFAULT 'ZERO',
    txn_count                   integer         NOT NULL DEFAULT 0,

    -- GL linkage
    settlement_je_id            uuid,

    -- Fiscal scope
    fiscal_year                 smallint        NOT NULL,
    period_number               smallint,

    -- Idempotency
    idempotency_key             text,

    -- Tags & Metadata
    tags                        jsonb           NOT NULL DEFAULT '[]'::jsonb,
    metadata                    jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Lifecycle
    status                      text            NOT NULL DEFAULT 'draft',
    is_active                   boolean         GENERATED ALWAYS AS (
                                    status IN ('draft','calculated','approved')
                                ) STORED,
    status_changed_at           timestamptz,
    status_changed_by           uuid,

    -- Settlement audit
    settled_at                  timestamptz,
    settled_by                  uuid,
    approved_at                 timestamptz,
    approved_by                 uuid,

    -- Audit
    created_at                  timestamptz     NOT NULL DEFAULT now(),
    created_by                  uuid            NOT NULL,
    updated_at                  timestamptz,
    updated_by                  uuid,

    CONSTRAINT nb_pkey               PRIMARY KEY (id),
    CONSTRAINT nb_tenant_id_uq       UNIQUE (tenant_id, id),
    CONSTRAINT nb_tenant_number_uq   UNIQUE (tenant_id, company_code_id, batch_number),
    CONSTRAINT nb_number_nonempty    CHECK (btrim(batch_number) <> ''),
    CONSTRAINT nb_entity_chk         CHECK (company_code_a_id IS DISTINCT FROM company_code_b_id),
    CONSTRAINT nb_direction_chk      CHECK (net_direction IN ('A_TO_B','B_TO_A','ZERO')),
    CONSTRAINT nb_gross_a_nonneg     CHECK (gross_amount_a_to_b >= 0),
    CONSTRAINT nb_gross_b_nonneg     CHECK (gross_amount_b_to_a >= 0),
    CONSTRAINT nb_net_nonneg         CHECK (net_amount >= 0),
    CONSTRAINT nb_txn_count_nonneg   CHECK (txn_count >= 0),
    CONSTRAINT nb_cutoff_chk         CHECK (cut_off_date <= batch_date),
    CONSTRAINT nb_settlement_chk     CHECK (settlement_date IS NULL OR settlement_date >= batch_date),
    CONSTRAINT nb_status_chk         CHECK (status IN (
        'draft','calculated','approved','settled','cancelled')),
    CONSTRAINT nb_period_chk         CHECK (period_number IS NULL OR period_number BETWEEN 1 AND 16)
);

COMMENT ON TABLE document.netting_batch IS
    'Bilateral IC netting batch header. gross_amount GENERATED (a_to_b + b_to_a). '
    'net_amount = |a_to_b - b_to_a|; net_direction indicates payer. '
    'Status: draft → calculated → approved → settled | cancelled.';


-- ============================================================================
-- §ICA4  document.ic_elimination — consolidation elimination document
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.ic_elimination (
    -- Identity
    id                              uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id                       uuid            NOT NULL,
    company_code_id                 uuid            NOT NULL,

    -- Natural key
    elimination_code                text            NOT NULL,

    -- Parties
    source_company_code_id          uuid            NOT NULL,
    counterparty_company_code_id    uuid            NOT NULL,

    -- Classification
    elimination_type                text            NOT NULL,
    consolidation_group             text            NOT NULL,

    -- Book + period
    book_id                         uuid            NOT NULL,
    fiscal_year                     smallint        NOT NULL,
    period_number                   smallint        NOT NULL,

    -- Dates
    elimination_date                date            NOT NULL,
    posting_date                    date            NOT NULL,

    -- Amounts
    elimination_amount              numeric(18,4)   NOT NULL,
    currency_code                   character(3)    NOT NULL,
    functional_currency_code        character(3)    NOT NULL,
    exchange_rate                   numeric(18,10),
    functional_amount               numeric(18,4),

    -- Line count
    line_count                      smallint        NOT NULL DEFAULT 0,

    -- GL linkage
    ic_transaction_id               uuid,
    je_id                           uuid,
    reversal_je_id                  uuid,

    -- AI-assisted approval
    decision_score                  numeric(5,4),
    approval_route                  text            NOT NULL DEFAULT 'STANDARD',

    -- Tags & Metadata
    tags                            jsonb           NOT NULL DEFAULT '[]'::jsonb,
    metadata                        jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Lifecycle
    status                          text            NOT NULL DEFAULT 'calculated',
    is_active                       boolean         GENERATED ALWAYS AS (
                                        status IN ('calculated','approved','posted')
                                    ) STORED,
    status_changed_at               timestamptz,
    status_changed_by               uuid,

    -- Approval + posting audit
    approved_at                     timestamptz,
    approved_by                     uuid,
    posted_at                       timestamptz,
    posted_by                       uuid,

    -- Audit
    created_at                      timestamptz     NOT NULL DEFAULT now(),
    created_by                      uuid            NOT NULL,
    updated_at                      timestamptz,
    updated_by                      uuid,

    CONSTRAINT ice_pkey              PRIMARY KEY (id),
    CONSTRAINT ice_tenant_id_uq      UNIQUE (tenant_id, id),
    CONSTRAINT ice_tenant_code_uq    UNIQUE (tenant_id, company_code_id, elimination_code),
    CONSTRAINT ice_code_nonempty     CHECK (btrim(elimination_code) <> ''),
    CONSTRAINT ice_entity_chk        CHECK (source_company_code_id IS DISTINCT FROM counterparty_company_code_id),
    CONSTRAINT ice_type_chk          CHECK (elimination_type IN (
        'REVENUE_EXPENSE','RECEIVABLE_PAYABLE','INVENTORY_MARKUP',
        'IC_PROFIT','MINORITY_INTEREST','INVESTMENT','DIVIDEND','LOAN','OTHER')),
    CONSTRAINT ice_approval_chk      CHECK (approval_route IN ('AUTO','STANDARD','ENHANCED','MANUAL')),
    CONSTRAINT ice_score_chk         CHECK (decision_score IS NULL OR decision_score BETWEEN 0 AND 1),
    CONSTRAINT ice_amount_positive   CHECK (elimination_amount > 0),
    CONSTRAINT ice_date_chk          CHECK (elimination_date <= posting_date),
    CONSTRAINT ice_status_chk        CHECK (status IN (
        'calculated','approved','posted','reversed','rejected','cancelled')),
    CONSTRAINT ice_period_chk        CHECK (period_number BETWEEN 1 AND 16),
    CONSTRAINT ice_fx_rate_chk       CHECK (currency_code = functional_currency_code OR exchange_rate IS NOT NULL),
    CONSTRAINT ice_no_self_je        CHECK (je_id IS DISTINCT FROM reversal_je_id)
);

COMMENT ON TABLE document.ic_elimination IS
    'IC elimination operational document. Produces a JE (source_doc_type = ic_elimination). '
    'AI-assisted: decision_score (0-1) drives approval_route (AUTO/STANDARD/ENHANCED/MANUAL). '
    'Children: ledger.ic_elimination_line. '
    'Status: calculated → approved → posted → reversed | rejected | cancelled.';

-- FILE: /d/Products/athyper/server/db/sql/04_tables/004h_document_inventory.sql
-- 04_tables/004h_document_inventory.sql
-- Scope: Inventory Management document tables
-- Domain: stocktake, stocktake_line
-- Depends on: 01_schemas, 04_tables/003_master.sql,
--             04_tables/004a_document_journal.sql (journal_entry)
-- Load order: 004h (after 004a_document_journal.sql)

-- ============================================================================
-- §ST1  document.stocktake — physical inventory count header
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.stocktake (
    -- Identity
    id                  uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id           uuid            NOT NULL,

    -- Company scope
    company_code_id     uuid            NOT NULL,

    -- Scope
    warehouse_id        uuid            NOT NULL,

    -- Document header
    reference_no        text,
    stocktake_date      date            NOT NULL,

    -- Denormalised line aggregates (maintained by trg_stl_denorm_counts trigger)
    total_line_count    integer         NOT NULL DEFAULT 0,
    variance_line_count integer         NOT NULL DEFAULT 0,

    -- GL linkage (set on completion within posting transaction)
    variance_je_id      uuid,

    -- Completion audit
    completed_at        timestamptz,
    completed_by        uuid,

    -- Metadata
    metadata            jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Lifecycle
    status              text            NOT NULL DEFAULT 'planned',
    is_active           boolean         GENERATED ALWAYS AS (status IN ('planned', 'in_progress')) STORED,
    status_changed_at   timestamptz,
    status_changed_by   uuid,

    -- Audit
    created_at          timestamptz     NOT NULL DEFAULT now(),
    created_by          uuid            NOT NULL,
    updated_at          timestamptz,
    updated_by          uuid,

    CONSTRAINT st_pkey              PRIMARY KEY (id),
    CONSTRAINT st_tenant_id_uq      UNIQUE (tenant_id, id),
    CONSTRAINT st_status_chk        CHECK (status IN ('planned', 'in_progress', 'completed', 'cancelled')),
    CONSTRAINT st_completed_chk     CHECK (
                                        status <> 'completed'
                                        OR (completed_at IS NOT NULL AND completed_by IS NOT NULL)
                                    ),
    CONSTRAINT st_variance_je_chk   CHECK (variance_je_id IS NULL OR status = 'completed'),
    CONSTRAINT st_line_count_chk    CHECK (total_line_count >= 0 AND variance_line_count >= 0),
    CONSTRAINT st_reference_no_chk  CHECK (reference_no IS NULL OR btrim(reference_no) <> '')
);

COMMENT ON TABLE document.stocktake IS
    'Physical inventory count header. Lifecycle: planned → in_progress → completed | cancelled. '
    'Lines remain editable while status is planned/in_progress; immutable thereafter (app-layer). '
    'Financial impact recorded as ADJUSTMENT rows in ledger.inventory_movement at completion. '
    'total_line_count / variance_line_count maintained by trg_stl_denorm_counts trigger.';


-- ============================================================================
-- §ST2  document.stocktake_line — physical count lines
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.stocktake_line (
    -- Identity
    id                  uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id           uuid            NOT NULL,

    -- Parent linkage
    stocktake_id        uuid            NOT NULL,
    line_no             smallint        NOT NULL,

    -- Position key
    item_id             uuid            NOT NULL,
    warehouse_id        uuid            NOT NULL,   -- denormalised from header
    lot_number          text,
    serial_number       text,

    -- Count quantities
    system_qty          numeric(18,4)   NOT NULL,
    counted_qty         numeric(18,4)   NOT NULL,
    variance_qty        numeric(18,4)   GENERATED ALWAYS AS (counted_qty - system_qty) STORED,

    -- Valuation
    unit_cost           numeric(18,4)   NOT NULL,
    variance_value      numeric(18,4)   GENERATED ALWAYS AS ((counted_qty - system_qty) * unit_cost) STORED,
    currency_code       character(3)    NOT NULL,

    -- Posting linkage (set when parent stocktake completes)
    posted_at           timestamptz,
    posted_by           uuid,

    -- Metadata
    metadata            jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Audit
    created_at          timestamptz     NOT NULL DEFAULT now(),
    created_by          uuid            NOT NULL,
    updated_at          timestamptz,
    updated_by          uuid,

    CONSTRAINT stl_pkey             PRIMARY KEY (id),
    CONSTRAINT stl_tenant_id_uq     UNIQUE (tenant_id, id),
    CONSTRAINT stl_line_uq          UNIQUE (stocktake_id, line_no),
    CONSTRAINT stl_line_no_chk      CHECK (line_no > 0),
    CONSTRAINT stl_system_qty_chk   CHECK (system_qty >= 0),
    CONSTRAINT stl_unit_cost_chk    CHECK (unit_cost >= 0),
    CONSTRAINT stl_currency_chk     CHECK (btrim(currency_code::text) <> ''),
    CONSTRAINT stl_posting_pair_chk CHECK ((posted_at IS NULL) = (posted_by IS NULL))
);

COMMENT ON TABLE document.stocktake_line IS
    'Physical count lines for a stocktake document. Editable while parent status is '
    'planned/in_progress; immutable once parent reaches completed (enforced at app layer). '
    'variance_qty = GENERATED (counted - system). variance_value = GENERATED (variance × unit_cost). '
    'warehouse_id denormalised from parent header for direct indexed variance queries.';

-- FILE: /d/Products/athyper/server/db/sql/04_tables/004i_document_p2p.sql
-- 04_tables/004i_document_p2p.sql
-- Scope: Procure-to-Pay (P2P) procurement document tables
-- Domain: purchase_requisition, purchase_requisition_line,
--         purchase_order_confirmation, purchase_order_confirmation_line,
--         delivery_note, delivery_note_line,
--         goods_receipt, goods_receipt_line,
--         service_entry_sheet, service_entry_sheet_line
-- Depends on: 01_schemas, 04_tables/003_master.sql,
--             04_tables/004_document.sql (workflow_request),
--             04_tables/004b_document_commitment.sql (commitment, commitment_line)
-- Load order: 004c (after 004b_document_commitment.sql)
-- Design ref: scc_p2p_final_merged.md v4.0
--
-- ENGINEERING NOTE – Foreign-key cardinality convention
-- ─────────────────────────────────────────────────────────────────────────────
-- Single-column UUID FK: globally-unique orchestration/posting roots (je_id,
--   workflow_request_id). tenant_id redundant. Indexes single-column.
-- Tenant-scoped composite FK: all business records (supplier, commitment, etc.).
--   Required for row-level isolation at DB layer.
-- ─────────────────────────────────────────────────────────────────────────────

-- ============================================================================
-- §3.1  document.purchase_requisition  (approvable)
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.purchase_requisition (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,
    code                    text            NOT NULL DEFAULT '',
    name                    text            NOT NULL DEFAULT '',
    company_code_id         uuid            NOT NULL,

    -- Natural key
    requisition_number      text            NOT NULL,

    -- Classification
    requisition_type        text            NOT NULL DEFAULT 'STANDARD',
    description             text,
    priority                text            NOT NULL DEFAULT 'normal',

    -- Requestor
    requested_by            uuid            NOT NULL,
    requested_for           uuid,

    -- Dates
    document_date           date            NOT NULL DEFAULT CURRENT_DATE,
    required_by_date        date,

    -- Suggested supplier
    suggested_supplier_id   uuid,

    -- Amounts
    currency_code           character(3)    NOT NULL,
    base_currency_code      character(3)    NOT NULL,
    exchange_rate           numeric(18,10),
    total_estimated_amount  numeric(18,4)   NOT NULL DEFAULT 0,

    -- Budget
    budget_allocation_id    uuid,
    budget_check_result     text,

    -- Encumbrance
    encumbrance_type        text            NOT NULL DEFAULT 'PRE_ENCUMBRANCE',
    is_encumbered           boolean         NOT NULL DEFAULT false,
    encumbrance_je_id       uuid,

    -- Fiscal scope
    fiscal_year             smallint        NOT NULL,
    period_number           smallint,

    -- Dimensions
    cost_center_id          uuid,
    profit_center_id        uuid,
    project_id              uuid,
    site_id                 uuid,
    dimension_set_id        uuid,

    -- Conversion tracking
    is_fully_converted      boolean         NOT NULL DEFAULT false,
    converted_po_count      smallint        NOT NULL DEFAULT 0,

    -- Approval
    approved_at             timestamptz,
    approved_by             uuid,
    workflow_request_id     uuid,

    -- Line count
    line_count              smallint        NOT NULL DEFAULT 0,

    -- Close
    closed_at               timestamptz,
    closed_by               uuid,
    close_reason            text,

    -- Notes
    notes                   text,

    -- Tags & Metadata
    tags                    jsonb           NOT NULL DEFAULT '[]'::jsonb,
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Lifecycle
    status                  text            NOT NULL DEFAULT 'draft',
    is_active               boolean         GENERATED ALWAYS AS (
                                status IN ('draft','pending_approval','approved','partially_converted')
                            ) STORED,
    status_changed_at       timestamptz,
    status_changed_by       uuid,

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT pr_pkey              PRIMARY KEY (id),
    CONSTRAINT pr_tenant_id_uq      UNIQUE (tenant_id, id),
    CONSTRAINT pr_tenant_number_uq  UNIQUE (tenant_id, company_code_id, requisition_number),
    CONSTRAINT pr_number_nonempty   CHECK (btrim(requisition_number) <> ''),
    CONSTRAINT pr_status_chk        CHECK (status IN (
        'draft','pending_approval','approved','rejected',
        'partially_converted','fully_converted','closed','cancelled')),
    CONSTRAINT pr_type_chk          CHECK (requisition_type IN (
        'STANDARD','URGENT','BLANKET','FRAMEWORK_CALL_OFF','CAPEX')),
    CONSTRAINT pr_check_chk         CHECK (budget_check_result IS NULL OR budget_check_result IN (
        'PASSED','WARNED','OVERRIDE','BLOCKED','EXEMPT')),
    CONSTRAINT pr_encumbrance_chk   CHECK (encumbrance_type IN (
        'NONE','PRE_ENCUMBRANCE','STATISTICAL_ONLY')),
    CONSTRAINT pr_amount_nonneg     CHECK (total_estimated_amount >= 0),
    CONSTRAINT pr_period_chk        CHECK (period_number IS NULL OR period_number BETWEEN 1 AND 16)
);

COMMENT ON TABLE document.purchase_requisition IS
    'Internal purchase request. Approvable document. '
    'Pre-encumbrance at approval reserves budget before PO. '
    'Status: draft → pending_approval → approved → partially_converted → fully_converted.';


-- ============================================================================
-- §3.2  document.purchase_requisition_line
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.purchase_requisition_line (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,

    -- Parent
    purchase_requisition_id uuid            NOT NULL,
    line_no                 smallint        NOT NULL,

    -- Item
    item_id                 uuid,
    item_description        text            NOT NULL,
    procurement_type        text            NOT NULL DEFAULT 'goods',
    spend_category_id       uuid,
    business_intent_id      uuid,

    -- Quantity / price
    uom_code                text            NOT NULL,
    quantity                numeric(18,4)   NOT NULL,
    estimated_unit_price    numeric(18,4)   NOT NULL DEFAULT 0,
    currency_code           character(3)    NOT NULL,
    estimated_amount        numeric(18,4)   GENERATED ALWAYS AS (
                                quantity * estimated_unit_price
                            ) STORED,

    -- Tax
    tax_group_id            uuid,

    -- Delivery
    required_by_date        date,
    delivery_site_id        uuid,
    delivery_warehouse_id   uuid,

    -- Dimensions
    cost_center_id          uuid,
    profit_center_id        uuid,
    project_id              uuid,
    site_id                 uuid,
    dimension_set_id        uuid,

    -- Suggested supplier
    suggested_supplier_id   uuid,

    -- Conversion tracking
    converted_quantity      numeric(18,4)   NOT NULL DEFAULT 0,
    remaining_quantity      numeric(18,4)   GENERATED ALWAYS AS (
                                quantity - converted_quantity
                            ) STORED,

    -- Notes & metadata
    notes                   text,
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,
    status                  text            NOT NULL DEFAULT 'open',

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT prl_pkey             PRIMARY KEY (id),
    CONSTRAINT prl_tenant_id_uq     UNIQUE (tenant_id, id),
    CONSTRAINT prl_line_no_uq       UNIQUE (purchase_requisition_id, line_no),
    CONSTRAINT prl_line_no_chk      CHECK (line_no > 0),
    CONSTRAINT prl_qty_pos          CHECK (quantity > 0),
    CONSTRAINT prl_price_nonneg     CHECK (estimated_unit_price >= 0),
    CONSTRAINT prl_proc_type_chk    CHECK (procurement_type IN ('goods','services','mixed')),
    CONSTRAINT prl_status_chk       CHECK (status IN (
        'open','partially_converted','converted','cancelled')),
    CONSTRAINT prl_converted_chk    CHECK (converted_quantity >= 0 AND converted_quantity <= quantity)
);


-- ============================================================================
-- §6  document.purchase_order_confirmation  (supplier artifact – not approvable)
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.purchase_order_confirmation (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,
    company_code_id         uuid            NOT NULL,

    -- Natural key
    confirmation_number     text            NOT NULL,

    -- Parent commitment + supplier
    commitment_id           uuid            NOT NULL,
    supplier_id             uuid            NOT NULL,

    -- Vendor details
    vendor_reference_number text,
    vendor_confirmation_date date,
    confirmation_type       text            NOT NULL DEFAULT 'FULL_CONFIRM',

    -- Document date + amounts
    document_date           date            NOT NULL DEFAULT CURRENT_DATE,
    currency_code           character(3)    NOT NULL,
    confirmed_total_amount  numeric(18,4)   NOT NULL DEFAULT 0,

    -- Amendment
    amendment_commitment_id uuid,

    -- Notes & metadata
    notes                   text,
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,
    status                  text            NOT NULL DEFAULT 'received',

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT poc_pkey             PRIMARY KEY (id),
    CONSTRAINT poc_tenant_id_uq     UNIQUE (tenant_id, id),
    CONSTRAINT poc_tenant_number_uq UNIQUE (tenant_id, company_code_id, confirmation_number),
    CONSTRAINT poc_status_chk       CHECK (status IN (
        'received','confirmed','changes_proposed','changes_accepted',
        'changes_rejected','rejected','cancelled')),
    CONSTRAINT poc_type_chk         CHECK (confirmation_type IN (
        'FULL_CONFIRM','PARTIAL_CONFIRM','CHANGE_PROPOSAL','REJECTION'))
);

COMMENT ON TABLE document.purchase_order_confirmation IS
    'Supplier acknowledgement of a PO. Not approvable. '
    'Vendor change proposals route approval through a commitment amendment, not this table.';


-- ============================================================================
-- §6  document.purchase_order_confirmation_line
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.purchase_order_confirmation_line (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,

    -- Parent
    confirmation_id         uuid            NOT NULL,
    line_no                 smallint        NOT NULL,

    -- Commitment line reference
    commitment_line_id      uuid            NOT NULL,

    -- Confirmed values
    confirmed_quantity      numeric(18,4)   NOT NULL,
    confirmed_unit_price    numeric(18,4)   NOT NULL,
    confirmed_delivery_date date,

    -- Variances
    quantity_variance       numeric(18,4)   NOT NULL DEFAULT 0,
    price_variance          numeric(18,4)   NOT NULL DEFAULT 0,

    -- Line status
    line_status             text            NOT NULL DEFAULT 'confirmed',
    vendor_notes            text,

    -- Metadata
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Audit (append-only)
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,

    CONSTRAINT pocl_pkey            PRIMARY KEY (id),
    CONSTRAINT pocl_tenant_id_uq    UNIQUE (tenant_id, id),
    CONSTRAINT pocl_line_uq         UNIQUE (confirmation_id, line_no),
    CONSTRAINT pocl_line_no_chk     CHECK (line_no > 0),
    CONSTRAINT pocl_qty_pos         CHECK (confirmed_quantity > 0),
    CONSTRAINT pocl_price_nonneg    CHECK (confirmed_unit_price >= 0),
    CONSTRAINT pocl_line_status_chk CHECK (line_status IN (
        'confirmed','changed','rejected','partial'))
);


-- ============================================================================
-- §7  document.delivery_note  (logistics artifact – not approvable)
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.delivery_note (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,
    company_code_id         uuid            NOT NULL,

    -- Natural key
    delivery_note_number    text            NOT NULL,

    -- Commitment + supplier
    commitment_id           uuid            NOT NULL,
    supplier_id             uuid            NOT NULL,

    -- Vendor references
    vendor_delivery_note_no text,
    vendor_dispatch_date    date,
    bill_of_lading_no       text,
    tracking_number         text,

    -- Dates
    document_date           date            NOT NULL DEFAULT CURRENT_DATE,
    expected_arrival_date   date,
    actual_arrival_date     date,

    -- Delivery location
    delivery_site_id        uuid            NOT NULL,
    delivery_warehouse_id   uuid,

    -- Carrier
    carrier_name            text,
    transport_mode          text,

    -- Inspection
    requires_inspection     boolean         NOT NULL DEFAULT false,
    inspection_status       text,

    -- Receipt status
    is_fully_receipted      boolean         NOT NULL DEFAULT false,

    -- Amounts
    currency_code           character(3)    NOT NULL,
    total_amount            numeric(18,4)   NOT NULL DEFAULT 0,

    -- Notes & metadata
    notes                   text,
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,
    status                  text            NOT NULL DEFAULT 'draft',

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT dn_pkey              PRIMARY KEY (id),
    CONSTRAINT dn_tenant_id_uq      UNIQUE (tenant_id, id),
    CONSTRAINT dn_tenant_number_uq  UNIQUE (tenant_id, company_code_id, delivery_note_number),
    CONSTRAINT dn_amount_nonneg     CHECK (total_amount >= 0),
    CONSTRAINT dn_status_chk        CHECK (status IN (
        'draft','in_transit','arrived','partially_receipted',
        'fully_receipted','returned','cancelled'))
);


-- ============================================================================
-- §7  document.delivery_note_line
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.delivery_note_line (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,

    -- Parent
    delivery_note_id        uuid            NOT NULL,
    line_no                 smallint        NOT NULL,

    -- Commitment line
    commitment_line_id      uuid            NOT NULL,

    -- Item
    item_id                 uuid,
    item_description        text            NOT NULL,

    -- Quantity
    uom_code                text            NOT NULL,
    shipped_quantity        numeric(18,4)   NOT NULL,
    received_quantity       numeric(18,4)   NOT NULL DEFAULT 0,
    damaged_quantity        numeric(18,4)   NOT NULL DEFAULT 0,
    rejected_quantity       numeric(18,4)   NOT NULL DEFAULT 0,
    accepted_quantity       numeric(18,4)   GENERATED ALWAYS AS (
                                received_quantity - damaged_quantity - rejected_quantity
                            ) STORED,

    -- Lot / batch / serial tracking
    lot_number              text,
    serial_numbers          text[],
    batch_number            text,
    expiry_date             date,

    -- Notes & metadata
    notes                   text,
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,
    status                  text            NOT NULL DEFAULT 'open',

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT dnl_pkey             PRIMARY KEY (id),
    CONSTRAINT dnl_tenant_id_uq     UNIQUE (tenant_id, id),
    CONSTRAINT dnl_line_uq          UNIQUE (delivery_note_id, line_no),
    CONSTRAINT dnl_line_no_chk      CHECK (line_no > 0),
    CONSTRAINT dnl_shipped_pos      CHECK (shipped_quantity > 0),
    CONSTRAINT dnl_received_nonneg  CHECK (received_quantity >= 0),
    CONSTRAINT dnl_damaged_nonneg   CHECK (damaged_quantity >= 0),
    CONSTRAINT dnl_rejected_nonneg  CHECK (rejected_quantity >= 0),
    CONSTRAINT dnl_qty_chk          CHECK (
        damaged_quantity + rejected_quantity <= received_quantity),
    CONSTRAINT dnl_status_chk       CHECK (status IN (
        'open','partially_receipted','receipted','returned','cancelled'))
);


-- ============================================================================
-- §8  document.goods_receipt  (approvable – triggers inventory + accrual)
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.goods_receipt (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,
    company_code_id         uuid            NOT NULL,

    -- Natural key
    receipt_number          text            NOT NULL,

    -- Commitment + delivery
    commitment_id           uuid            NOT NULL,
    delivery_note_id        uuid,
    supplier_id             uuid            NOT NULL,

    -- Dates
    document_date           date            NOT NULL DEFAULT CURRENT_DATE,
    posting_date            date            NOT NULL DEFAULT CURRENT_DATE,

    -- Location
    receiving_site_id       uuid            NOT NULL,
    receiving_warehouse_id  uuid            NOT NULL,

    -- Amounts
    currency_code           character(3)    NOT NULL,
    base_currency_code      character(3)    NOT NULL,
    exchange_rate           numeric(18,10),
    total_amount            numeric(18,4)   NOT NULL DEFAULT 0,

    -- Fiscal scope
    fiscal_year             smallint        NOT NULL,
    period_number           smallint        NOT NULL,

    -- Posting
    accrual_je_id           uuid,
    is_posted               boolean         NOT NULL DEFAULT false,
    posted_at               timestamptz,
    posted_by               uuid,

    -- Reversal
    is_reversal             boolean         NOT NULL DEFAULT false,
    reversal_of_id          uuid,

    -- Workflow
    workflow_request_id     uuid,
    approved_at             timestamptz,
    approved_by             uuid,

    -- Notes & metadata
    notes                   text,
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Lifecycle
    status                  text            NOT NULL DEFAULT 'draft',
    is_active               boolean         GENERATED ALWAYS AS (
                                status IN ('draft','pending_approval','approved','posted')
                            ) STORED,
    status_changed_at       timestamptz,
    status_changed_by       uuid,

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT gr_pkey              PRIMARY KEY (id),
    CONSTRAINT gr_tenant_id_uq      UNIQUE (tenant_id, id),
    CONSTRAINT gr_tenant_number_uq  UNIQUE (tenant_id, company_code_id, receipt_number),
    CONSTRAINT gr_status_chk        CHECK (status IN (
        'draft','pending_approval','approved','posted','reversed','cancelled')),
    CONSTRAINT gr_posting_pair_chk  CHECK ((posted_at IS NULL) = (posted_by IS NULL)),
    CONSTRAINT gr_no_self_reversal  CHECK (reversal_of_id IS DISTINCT FROM id),
    CONSTRAINT gr_period_chk        CHECK (period_number BETWEEN 1 AND 16),
    CONSTRAINT gr_amount_nonneg     CHECK (total_amount >= 0)
);

COMMENT ON TABLE document.goods_receipt IS
    'Approvable GR. On posting: ledger.inventory_movement (RECEIPT), '
    'ledger.inventory_valuation_layer, GR/IR accrual JE, ledger.commitment_fulfillment. '
    'Updates commitment_line.received_quantity cache via trigger.';


-- ============================================================================
-- §8.1  document.goods_receipt_line
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.goods_receipt_line (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,

    -- Parent
    goods_receipt_id        uuid            NOT NULL,
    line_no                 smallint        NOT NULL,

    -- Commitment + delivery links
    commitment_line_id      uuid            NOT NULL,
    delivery_note_line_id   uuid,

    -- Item
    item_id                 uuid            NOT NULL,
    item_description        text            NOT NULL,

    -- Quantity
    uom_code                text            NOT NULL,
    received_quantity       numeric(18,4)   NOT NULL,
    accepted_quantity       numeric(18,4)   NOT NULL,
    rejected_quantity       numeric(18,4)   NOT NULL DEFAULT 0,

    -- Price
    unit_price              numeric(18,4)   NOT NULL,
    currency_code           character(3)    NOT NULL,
    net_amount              numeric(18,4)   GENERATED ALWAYS AS (
                                accepted_quantity * unit_price
                            ) STORED,

    -- Storage location
    warehouse_id            uuid            NOT NULL,
    storage_location        text,

    -- Lot / batch / serial tracking
    lot_number              text,
    serial_number           text,
    batch_number            text,
    expiry_date             date,

    -- Dimensions
    cost_center_id          uuid,
    profit_center_id        uuid,
    project_id              uuid,

    -- Populated at posting time
    inventory_movement_id   uuid,
    fulfillment_id          uuid,

    -- Asset
    is_asset                boolean         NOT NULL DEFAULT false,
    asset_transaction_id    uuid,

    -- Notes & metadata
    notes                   text,
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,
    status                  text            NOT NULL DEFAULT 'open',

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT grl_pkey             PRIMARY KEY (id),
    CONSTRAINT grl_tenant_id_uq     UNIQUE (tenant_id, id),
    CONSTRAINT grl_line_uq          UNIQUE (goods_receipt_id, line_no),
    CONSTRAINT grl_line_no_chk      CHECK (line_no > 0),
    CONSTRAINT grl_qty_pos          CHECK (received_quantity > 0),
    CONSTRAINT grl_accepted_nonneg  CHECK (accepted_quantity >= 0),
    CONSTRAINT grl_rejected_nonneg  CHECK (rejected_quantity >= 0),
    CONSTRAINT grl_qty_chk          CHECK (
        accepted_quantity + rejected_quantity <= received_quantity),
    CONSTRAINT grl_price_nonneg     CHECK (unit_price >= 0),
    CONSTRAINT grl_status_chk       CHECK (status IN (
        'open','posted','reversed','cancelled'))
);


-- ============================================================================
-- §8.2  document.service_entry_sheet  (approvable – two-step)
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.service_entry_sheet (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,
    company_code_id         uuid            NOT NULL,

    -- Natural key
    ses_number              text            NOT NULL,

    -- Commitment + supplier
    commitment_id           uuid            NOT NULL,
    supplier_id             uuid            NOT NULL,

    -- Dates
    document_date           date            NOT NULL DEFAULT CURRENT_DATE,
    posting_date            date            NOT NULL DEFAULT CURRENT_DATE,
    service_period_from     date            NOT NULL,
    service_period_to       date            NOT NULL,

    -- Amounts
    currency_code           character(3)    NOT NULL,
    base_currency_code      character(3)    NOT NULL,
    exchange_rate           numeric(18,10),
    total_amount            numeric(18,4)   NOT NULL DEFAULT 0,

    -- Fiscal scope
    fiscal_year             smallint        NOT NULL,
    period_number           smallint        NOT NULL,

    -- Posting
    accrual_je_id           uuid,
    is_posted               boolean         NOT NULL DEFAULT false,
    posted_at               timestamptz,
    posted_by               uuid,

    -- Acceptance
    accepted_by             uuid,
    accepted_at             timestamptz,

    -- Reversal
    is_reversal             boolean         NOT NULL DEFAULT false,
    reversal_of_id          uuid,

    -- Workflow
    workflow_request_id     uuid,
    approved_at             timestamptz,
    approved_by             uuid,

    -- Lifecycle
    status                  text            NOT NULL DEFAULT 'draft',
    is_active               boolean         GENERATED ALWAYS AS (
                                status IN ('draft','pending_acceptance','accepted',
                                           'pending_approval','approved','posted')
                            ) STORED,
    status_changed_at       timestamptz,
    status_changed_by       uuid,

    -- Notes & metadata
    notes                   text,
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT ses_pkey              PRIMARY KEY (id),
    CONSTRAINT ses_tenant_id_uq      UNIQUE (tenant_id, id),
    CONSTRAINT ses_tenant_number_uq  UNIQUE (tenant_id, company_code_id, ses_number),
    CONSTRAINT ses_status_chk        CHECK (status IN (
        'draft','pending_acceptance','accepted','pending_approval',
        'approved','posted','reversed','cancelled')),
    CONSTRAINT ses_period_range_chk  CHECK (service_period_to >= service_period_from),
    CONSTRAINT ses_no_self_reversal  CHECK (reversal_of_id IS DISTINCT FROM id),
    CONSTRAINT ses_period_chk        CHECK (period_number BETWEEN 1 AND 16),
    CONSTRAINT ses_amount_nonneg     CHECK (total_amount >= 0)
);

COMMENT ON TABLE document.service_entry_sheet IS
    'Approvable SES. Two-step: acceptance by requestor (pending_acceptance→accepted), '
    'then finance approval (pending_approval→approved). '
    'On posting: accrual JE (Dr Expense, Cr GR/IR Clearing) + ledger.commitment_fulfillment.';


-- ============================================================================
-- §8.3  document.service_entry_sheet_line
-- ============================================================================

CREATE TABLE IF NOT EXISTS document.service_entry_sheet_line (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,

    -- Parent
    service_entry_sheet_id  uuid            NOT NULL,
    line_no                 smallint        NOT NULL,

    -- Commitment line
    commitment_line_id      uuid            NOT NULL,

    -- Service description
    item_id                 uuid,
    service_description     text            NOT NULL,
    spend_category_id       uuid,
    business_intent_id      uuid,

    -- Quantity / price
    uom_code                text            NOT NULL,
    quantity                numeric(18,4)   NOT NULL,
    unit_price              numeric(18,4)   NOT NULL,
    net_amount              numeric(18,4)   GENERATED ALWAYS AS (
                                quantity * unit_price
                            ) STORED,

    -- Milestone
    completion_pct          numeric(5,2),
    milestone_name          text,

    -- Tax
    tax_group_id            uuid,
    tax_amount              numeric(18,4)   NOT NULL DEFAULT 0,

    -- Dimensions
    cost_center_id          uuid,
    profit_center_id        uuid,
    project_id              uuid,

    -- Populated at posting time
    fulfillment_id          uuid,

    -- Notes & metadata
    notes                   text,
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,
    status                  text            NOT NULL DEFAULT 'open',

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT sesl_pkey            PRIMARY KEY (id),
    CONSTRAINT sesl_tenant_id_uq    UNIQUE (tenant_id, id),
    CONSTRAINT sesl_line_uq         UNIQUE (service_entry_sheet_id, line_no),
    CONSTRAINT sesl_line_no_chk     CHECK (line_no > 0),
    CONSTRAINT sesl_qty_pos         CHECK (quantity > 0),
    CONSTRAINT sesl_price_nonneg    CHECK (unit_price >= 0),
    CONSTRAINT sesl_tax_nonneg      CHECK (tax_amount >= 0),
    CONSTRAINT sesl_pct_chk         CHECK (
        completion_pct IS NULL OR completion_pct BETWEEN 0 AND 100),
    CONSTRAINT sesl_status_chk      CHECK (status IN (
        'open','posted','reversed','cancelled'))
);

-- FILE: /d/Products/athyper/server/db/sql/04_tables/004j_document_import.sql
-- 04_tables/004j_document_import.sql
-- Scope: Bulk import execution tables — request header + chunk work units.
-- Depends on: 01_schemas, 03_bootstrap_functions (shared.uuidv7), 004_document.sql (document schema)

-- ══════════════════════════════════════════════════════════════════════════════
-- §1  document.import_request — bulk import submission header
-- ══════════════════════════════════════════════════════════════════════════════
-- One row per import submission. id is returned to the frontend as uploadToken
-- and jobId. File is stored in object storage at file_ref.
-- Dry-runs do not create a row; only actual imports are persisted.
CREATE TABLE IF NOT EXISTS document.import_request (
    -- Identity
    id              uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid            NOT NULL,

    -- Target
    entity_name     text            NOT NULL,       -- e.g. 'supplier', 'journal_entry'

    -- File
    file_ref        text            NOT NULL,       -- S3 object key
    file_name       text            NOT NULL,       -- original filename for display
    file_size_bytes bigint,
    file_format     text            NOT NULL DEFAULT 'csv',   -- csv | xlsx | tsv

    -- Mapping (snapshot at submission time)
    mapping_config  jsonb           NOT NULL DEFAULT '[]',    -- ColumnMapping[]
    import_mode     text            NOT NULL DEFAULT 'create', -- create | update | upsert

    -- Processing options
    options         jsonb           NOT NULL DEFAULT '{}',    -- { chunk_size, error_threshold_pct }

    -- Progress (updated by worker)
    total_rows      integer,
    processed_rows  integer         NOT NULL DEFAULT 0,
    success_count   integer         NOT NULL DEFAULT 0,
    error_count     integer         NOT NULL DEFAULT 0,

    -- Lifecycle
    status          text            NOT NULL DEFAULT 'uploaded',
    -- uploaded → processing → completed | failed | cancelled
    error_summary   jsonb,
    started_at      timestamptz,
    completed_at    timestamptz,

    -- Audit
    submitted_by    uuid            NOT NULL,
    created_at      timestamptz     NOT NULL DEFAULT now(),
    created_by      uuid            NOT NULL,
    updated_at      timestamptz,
    updated_by      uuid,

    CONSTRAINT import_request_pkey              PRIMARY KEY (id),
    CONSTRAINT import_request_tenant_uq         UNIQUE (tenant_id, id),
    CONSTRAINT import_request_entity_fmt        CHECK (btrim(entity_name) <> ''),
    CONSTRAINT import_request_file_fmt          CHECK (btrim(file_ref) <> ''),
    CONSTRAINT import_request_format_chk        CHECK (file_format IN ('csv', 'xlsx', 'tsv')),
    CONSTRAINT import_request_mode_chk          CHECK (import_mode IN ('create', 'update', 'upsert')),
    CONSTRAINT import_request_status_chk        CHECK (status IN (
        'uploaded', 'processing', 'completed', 'failed', 'cancelled'
    )),
    CONSTRAINT import_request_rows_chk          CHECK (
        processed_rows >= 0 AND success_count >= 0 AND error_count >= 0
    ),
    CONSTRAINT import_request_mapping_chk       CHECK (jsonb_typeof(mapping_config) = 'array'),
    CONSTRAINT import_request_options_chk       CHECK (jsonb_typeof(options) = 'object')
);

CREATE INDEX IF NOT EXISTS import_request_tenant_status_idx
    ON document.import_request (tenant_id, status, created_at DESC);

CREATE INDEX IF NOT EXISTS import_request_tenant_entity_idx
    ON document.import_request (tenant_id, entity_name, created_at DESC);

COMMENT ON TABLE  document.import_request IS
    'Bulk import submission. id = uploadToken returned to client. '
    'File stored in object storage at file_ref. '
    'Status: uploaded → processing → completed | failed | cancelled.';


-- ══════════════════════════════════════════════════════════════════════════════
-- §2  document.import_request_chunk — independently retryable row batches
-- ══════════════════════════════════════════════════════════════════════════════
-- Each chunk is a BullMQ job unit. Default chunk_size = 500 rows.
-- Errors stored as JSON array for per-row error reporting.
CREATE TABLE IF NOT EXISTS document.import_request_chunk (
    -- Identity
    id                  uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id           uuid        NOT NULL,
    import_request_id   uuid        NOT NULL,   -- FK: document.import_request.id

    -- Position
    chunk_index         smallint    NOT NULL,   -- 0-based ordering
    row_start           integer     NOT NULL,   -- 1-based spreadsheet row number (inclusive)
    row_end             integer     NOT NULL,   -- inclusive

    -- Lifecycle
    status              text        NOT NULL DEFAULT 'pending',
    -- pending → processing → completed | failed | cancelled

    -- Counts
    success_count       integer     NOT NULL DEFAULT 0,
    error_count         integer     NOT NULL DEFAULT 0,

    -- Per-row errors: [{row_number, field, error_code, message}]
    errors_json         jsonb       NOT NULL DEFAULT '[]',

    -- BullMQ correlation
    job_id              text,
    attempt_no          smallint    NOT NULL DEFAULT 1,

    -- Timing
    started_at          timestamptz,
    completed_at        timestamptz,
    duration_ms         integer,

    CONSTRAINT import_chunk_pkey            PRIMARY KEY (id),
    CONSTRAINT import_chunk_request_fk      FOREIGN KEY (import_request_id)
                                                REFERENCES document.import_request (id)
                                                ON DELETE CASCADE,
    CONSTRAINT import_chunk_status_chk      CHECK (status IN (
        'pending', 'processing', 'completed', 'failed', 'cancelled'
    )),
    CONSTRAINT import_chunk_rows_chk        CHECK (
        row_start > 0 AND row_end >= row_start AND chunk_index >= 0
    ),
    CONSTRAINT import_chunk_counts_chk     CHECK (
        success_count >= 0 AND error_count >= 0
    ),
    CONSTRAINT import_chunk_errors_chk     CHECK (jsonb_typeof(errors_json) = 'array')
);

CREATE INDEX IF NOT EXISTS import_chunk_request_idx
    ON document.import_request_chunk (import_request_id, chunk_index);

CREATE INDEX IF NOT EXISTS import_chunk_status_idx
    ON document.import_request_chunk (import_request_id, status)
    WHERE status IN ('pending', 'processing');

COMMENT ON TABLE  document.import_request_chunk IS
    'Independently retryable batch of rows within an import request. '
    'Each chunk becomes one BullMQ job on the jobs-import queue. '
    'errors_json: [{row_number, field, error_code, message}] per failed row.';

-- FILE: /d/Products/athyper/server/db/sql/04_tables/005_ledger.sql
-- 04_tables/005_ledger.sql
-- Depends on: 01_schemas, 03_bootstrap_functions (shared.uuidv7)
-- Ledger schema tables. Column order: Identity → Table-specific → Audit.

-- §1  ledger.gl_balance — period-level balance store
-- UPSERT target for PostingService.
-- closing = GENERATED from opening + period (accounting identity enforced).
-- version column for optimistic locking / concurrency control.
-- 3 first-class dimensions + dimension_set for long tail.
CREATE TABLE IF NOT EXISTS ledger.gl_balance (
    -- Identity
    id               uuid         NOT NULL DEFAULT shared.uuidv7(),
    tenant_id        uuid         NOT NULL,

    -- Company scope (Tier 1 UUID)
    company_code_id  uuid         NOT NULL,

    -- Account + Book
    gl_account_id    uuid         NOT NULL,
    book_id          uuid         NOT NULL,

    -- Period
    fiscal_year      smallint     NOT NULL,
    period_number    smallint     NOT NULL,
    currency_code    character(3) NOT NULL,

    -- First-class dimensions
    cost_center_id   uuid,
    profit_center_id uuid,
    project_id       uuid,

    -- Composite dimensions
    dimension_set_id uuid,

    -- Balances
    opening_debit    numeric(18,4) NOT NULL DEFAULT 0,
    opening_credit   numeric(18,4) NOT NULL DEFAULT 0,
    period_debit     numeric(18,4) NOT NULL DEFAULT 0,
    period_credit    numeric(18,4) NOT NULL DEFAULT 0,
    closing_debit    numeric(18,4) GENERATED ALWAYS AS (opening_debit + period_debit) STORED,
    closing_credit   numeric(18,4) GENERATED ALWAYS AS (opening_credit + period_credit) STORED,

    -- Concurrency
    version          integer      NOT NULL DEFAULT 1,
    last_je_id       uuid,
    last_posted_at   timestamptz,

    -- Audit
    created_at       timestamptz  NOT NULL DEFAULT now(),
    created_by       uuid         NOT NULL,
    updated_at       timestamptz,
    updated_by       uuid,

    CONSTRAINT gl_balance_pkey PRIMARY KEY (id),
    CONSTRAINT gl_balance_opening_nonneg_chk CHECK (
        opening_debit >= 0 AND opening_credit >= 0
    ),
    CONSTRAINT gl_balance_period_nonneg_chk CHECK (
        period_debit >= 0 AND period_credit >= 0
    ),
    CONSTRAINT gl_balance_version_chk CHECK (version >= 1),
    CONSTRAINT gl_balance_period_range_chk CHECK (period_number BETWEEN 0 AND 16)
);

COMMENT ON TABLE ledger.gl_balance IS
    'Period-level GL balance store. UPSERT target for PostingService. '
    'closing = GENERATED (opening + period) — accounting identity enforced at schema level. '
    'Concurrent-safe via ON CONFLICT DO UPDATE SET period_debit += EXCLUDED.period_debit. '
    '3 first-class dimensions (CC, PC, project) + dimension_set for long tail.';


-- =============================================================================
-- §2  ledger.asset_revaluation_reserve — append-only revaluation/impairment ledger
-- =============================================================================
-- Immutable (insert-only). log.trg_prevent_mutation() blocks UPDATE/DELETE.
-- Rows are inserted as posted fact. Draft staging happens in
-- document.asset_transaction; only when that transaction is posted does
-- the reserve row get inserted. posted_at/posted_by set at insert time.

CREATE TABLE IF NOT EXISTS ledger.asset_revaluation_reserve (
    -- Identity
    id               uuid         NOT NULL DEFAULT shared.uuidv7(),
    tenant_id        uuid         NOT NULL,

    -- Company scope (Tier 1 UUID)
    company_code_id  uuid         NOT NULL,

    -- Table-specific (asset + book linkage)
    asset_id                 uuid         NOT NULL,
    asset_book_id            uuid         NOT NULL,
    book_type                text         NOT NULL,

    -- Table-specific (reserve movement)
    reserve_type             text         NOT NULL,
    movement_amount          numeric(18,4) NOT NULL,
    balance_after            numeric(18,4) NOT NULL,
    currency_code            character(3) NOT NULL DEFAULT 'USD',

    -- Table-specific (period context)
    effective_date           date         NOT NULL,
    fiscal_year              smallint     NOT NULL,
    period_number            smallint     NOT NULL,

    -- Table-specific (source)
    asset_transaction_id     uuid         NOT NULL,
    reference_je_id          uuid,

    -- Table-specific (valuation detail)
    carrying_amount          numeric(18,4) NOT NULL,
    fair_value               numeric(18,4),
    recoverable_amount       numeric(18,4),
    valuation_method         text,
    appraiser_ref            text,
    notes                    text,

    -- Audit (immutable — created_at/created_by + posted stamps only, no updated_at)
    created_at       timestamptz  NOT NULL DEFAULT now(),
    created_by       uuid         NOT NULL,
    posted_at        timestamptz  NOT NULL DEFAULT now(),
    posted_by        uuid         NOT NULL,

    CONSTRAINT asset_reval_reserve_pkey PRIMARY KEY (id),
    CONSTRAINT asset_reval_reserve_tenant_id_uq UNIQUE (tenant_id, id)
);

COMMENT ON TABLE ledger.asset_revaluation_reserve IS
    'APPEND-ONLY ledger entries tracking revaluation surplus and impairment '
    'reserves per asset per book. Immutability enforced by log.trg_prevent_mutation(). '
    'No draft semantics — rows are inserted as posted fact.';


-- ============================================================================
-- TAX + FX ENGINE — Ledger schema tables
-- ============================================================================

-- ── ledger.tax_calculation ───────────────────────────────────────────────────
-- Per-line tax results. Append-only — no UPDATE, no DELETE.
-- No status column: rows born immutable at posting time.
-- Reversals: new row with negative amounts + reverses_calculation_id FK to original.
-- FK to tax_rate_schedule uses tenant-composite for consistent isolation.
CREATE TABLE IF NOT EXISTS ledger.tax_calculation (
    -- Identity
    id                          uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id                   uuid            NOT NULL,

    -- Table-specific
    company_code_id             uuid            NOT NULL,
    book_id                     uuid            NOT NULL,
    fiscal_period_id            uuid,
    doc_type                    text            NOT NULL,
    doc_id                      uuid            NOT NULL,
    doc_line_id                 uuid,
    doc_line_index              smallint,
    jurisdiction_id             uuid            NOT NULL,
    tax_type_id                 uuid            NOT NULL,
    component_code              text,
    tax_group_id                uuid,
    tax_rate_schedule_id        uuid,
    base_amount                 numeric(18,4)   NOT NULL,
    rate_kind                   text            NOT NULL DEFAULT 'PERCENT',
    rate_value                  numeric(18,6)   NOT NULL,
    calculation_basis           text            NOT NULL DEFAULT 'LINE_NET',
    tax_amount                  numeric(18,4)   NOT NULL,
    rounding_adjustment         numeric(18,4)   NOT NULL DEFAULT 0,
    currency_code               character(3)    NOT NULL,
    base_currency_amount        numeric(18,4),
    exchange_rate               numeric(18,10),
    tax_direction               text            NOT NULL,
    tax_treatment               text            NOT NULL DEFAULT 'STANDARD',
    recoverability_mode         text            NOT NULL DEFAULT 'NONE',
    credit_recovery_pct         numeric(5,2),
    reverse_charge_mode         text            NOT NULL DEFAULT 'NONE',
    is_wht                      boolean         NOT NULL DEFAULT false,
    wht_basis                   text,
    wht_certificate_no          text,
    wht_base_amount             numeric(18,4),
    reference_je_id             uuid,
    reference_je_line_id        uuid,
    idempotency_key             text,
    -- Reversal linkage (append-only — original row never modified)
    reverses_calculation_id     uuid,
    fiscal_year                 smallint        NOT NULL,
    period_number               smallint        NOT NULL,

    -- Audit (immutable — no updated_at)
    posted_at                   timestamptz     NOT NULL DEFAULT now(),
    posted_by                   uuid            NOT NULL,
    created_at                  timestamptz     NOT NULL DEFAULT now(),
    created_by                  uuid            NOT NULL,

    CONSTRAINT tc_pkey              PRIMARY KEY (id),
    CONSTRAINT tc_tenant_id_uq      UNIQUE (tenant_id, id),
    CONSTRAINT tc_direction_chk     CHECK (tax_direction IN (
        'PURCHASE','SALE','PAYMENT','IMPORT','EXPORT')),
    CONSTRAINT tc_treatment_chk     CHECK (tax_treatment IN (
        'STANDARD','EXEMPT','ZERO_RATED','REVERSE_CHARGE','WITHHOLDING','NON_TAXABLE')),
    CONSTRAINT tc_rate_kind_chk     CHECK (rate_kind IN ('PERCENT','FIXED','PER_UNIT')),
    CONSTRAINT tc_recover_chk       CHECK (recoverability_mode IN ('FULL','PARTIAL','NONE','CONDITIONAL')),
    CONSTRAINT tc_reverse_chk       CHECK (reverse_charge_mode IN ('NONE','SELF_ASSESS','FULL')),
    CONSTRAINT tc_base_nonneg       CHECK (base_amount >= 0)
);
COMMENT ON TABLE ledger.tax_calculation IS
    'Per-line tax results. Fully append-only — no UPDATE, no DELETE. '
    'No status column: rows born immutable at posting time. '
    'Reversals: new row with negative amounts + reverses_calculation_id FK to original. '
    'FK to tax_rate_schedule uses tenant-composite (tenant_id, tax_rate_schedule_id).';


-- ── ledger.tax_credit_movement ───────────────────────────────────────────────
-- Append-only movement ledger. Each posting, reversal, amendment, carry-forward
-- is a separate immutable row. aggregate.tax_credit_summary materializes period snapshot.
CREATE TABLE IF NOT EXISTS ledger.tax_credit_movement (
    -- Identity
    id                          uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id                   uuid            NOT NULL,

    -- Table-specific
    company_code_id             uuid            NOT NULL,
    book_id                     uuid            NOT NULL,
    jurisdiction_id             uuid            NOT NULL,
    tax_type_id                 uuid            NOT NULL,
    fiscal_year                 smallint        NOT NULL,
    period_number               smallint        NOT NULL,
    movement_type               text            NOT NULL,
    -- Amounts (positive = credit/receivable, negative = debit/payable)
    input_amount                numeric(18,4)   NOT NULL DEFAULT 0,
    output_amount               numeric(18,4)   NOT NULL DEFAULT 0,
    wht_deducted_amount         numeric(18,4)   NOT NULL DEFAULT 0,
    wht_suffered_amount         numeric(18,4)   NOT NULL DEFAULT 0,
    -- Source references
    source_tax_calculation_id   uuid,
    source_movement_id          uuid,
    currency_code               character(3)    NOT NULL,
    reason                      text,
    reference                   text,

    -- Audit (immutable — created_at/created_by only)
    created_at                  timestamptz     NOT NULL DEFAULT now(),
    created_by                  uuid            NOT NULL,

    CONSTRAINT tcm_pkey             PRIMARY KEY (id),
    CONSTRAINT tcm_tenant_id_uq     UNIQUE (tenant_id, id),
    CONSTRAINT tcm_type_chk         CHECK (movement_type IN (
        'POSTING','REVERSAL','AMENDMENT','CARRY_FORWARD','ADJUSTMENT')),
    CONSTRAINT tcm_period_chk       CHECK (period_number BETWEEN 1 AND 16),
    CONSTRAINT tcm_reversal_ref     CHECK (
        movement_type NOT IN ('REVERSAL','AMENDMENT') OR source_movement_id IS NOT NULL)
);
COMMENT ON TABLE ledger.tax_credit_movement IS
    'Append-only movement entries. Each posting, reversal, amendment, '
    'carry-forward is a separate immutable row. '
    'aggregate.tax_credit_summary materializes the period snapshot from movements.';


-- ── ledger.fx_revaluation_line ───────────────────────────────────────────────
-- Immutable lines created during an FX revaluation run.
-- Corrections require a new revaluation run (which auto-reverses the previous).
CREATE TABLE IF NOT EXISTS ledger.fx_revaluation_line (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,

    -- Table-specific
    run_id                  uuid            NOT NULL,
    line_no                 smallint        NOT NULL,
    gl_account_id           uuid            NOT NULL,
    currency_code           character(3)    NOT NULL,
    balance_type            text            NOT NULL,
    -- Source identity for audit trail
    source_entity_type      text,
    source_entity_id        uuid,
    source_doc_id           uuid,
    counterparty_type       text,
    counterparty_id         uuid,
    original_balance        numeric(18,4)   NOT NULL,
    original_functional     numeric(18,4)   NOT NULL,
    original_rate           numeric(18,10)  NOT NULL,
    closing_rate            numeric(18,10)  NOT NULL,
    revalued_functional     numeric(18,4)   NOT NULL,
    unrealized_gain_loss    numeric(18,4)   NOT NULL,
    cost_center_id          uuid,
    profit_center_id        uuid,
    dimension_set_id        uuid,

    -- Audit (immutable)
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,

    CONSTRAINT fxrl_pkey                PRIMARY KEY (id),
    CONSTRAINT fxrl_tenant_id_uq        UNIQUE (tenant_id, id),
    CONSTRAINT fxrl_run_line_uq         UNIQUE (run_id, line_no),
    CONSTRAINT fxrl_balance_type_chk    CHECK (balance_type IN (
        'AR','AP','BANK','INTERCOMPANY','LOAN','OTHER')),
    CONSTRAINT fxrl_source_type_chk     CHECK (source_entity_type IS NULL
        OR source_entity_type IN (
            'OPEN_AP_ITEM','OPEN_AR_ITEM','BANK_BALANCE','IC_LOAN','GL_MONETARY_BALANCE')),
    CONSTRAINT fxrl_counterparty_chk    CHECK (counterparty_type IS NULL
        OR counterparty_type IN ('SUPPLIER','CUSTOMER','INTERCOMPANY','BANK')),
    CONSTRAINT fxrl_line_no_chk         CHECK (line_no > 0),
    CONSTRAINT fxrl_rate_positive       CHECK (original_rate > 0 AND closing_rate > 0)
);
COMMENT ON TABLE ledger.fx_revaluation_line IS
    'Immutable revaluation line per open item/balance. Created during the run; '
    'never modified. source_entity_type/id enables full audit trail and replay. '
    'Corrections: create a new run — auto-reversal handles the prior run.';


-- ── ledger.consolidation_elimination ─────────────────────────────────────────
-- IC elimination entries. source/dest company via UUID FKs (authoritative).
-- Text entity codes kept as denormalized display cache only.
CREATE TABLE IF NOT EXISTS ledger.consolidation_elimination (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,

    -- Table-specific (consolidation scope)
    company_code_id         uuid            NOT NULL,
    book_id                 uuid            NOT NULL,
    fiscal_year             smallint        NOT NULL,
    period_number           smallint        NOT NULL,
    elimination_type        text            NOT NULL,
    consolidation_group     text,

    -- IC engine link (FK → document.ic_elimination)
    ic_elimination_id       uuid,

    -- UUID FK references (authoritative)
    source_company_code_id  uuid            NOT NULL,
    dest_company_code_id    uuid            NOT NULL,
    amount                  numeric(18,4)   NOT NULL,
    currency_code           character(3)    NOT NULL,
    functional_currency_code character(3),
    exchange_rate           numeric(18,10),
    functional_amount       numeric(18,4),
    reference_je_id         uuid,
    reversal_je_id          uuid,

    -- Approval
    approval_route          text            NOT NULL DEFAULT 'STANDARD',
    decision_score          numeric(5,4),
    approved_at             timestamptz,
    approved_by             uuid,

    -- Summary counters
    line_count              smallint        NOT NULL DEFAULT 0,

    -- Tags & Metadata
    tags                    jsonb           NOT NULL DEFAULT '[]'::jsonb,
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Lifecycle
    status                  text            NOT NULL DEFAULT 'calculated',
    posted_at               timestamptz,
    posted_by               uuid,

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT ce_pkey              PRIMARY KEY (id),
    CONSTRAINT ce_tenant_id_uq      UNIQUE (tenant_id, id),
    CONSTRAINT ce_type_chk          CHECK (elimination_type IN (
        'IC_REVENUE_EXPENSE','IC_RECEIVABLE_PAYABLE','IC_PROFIT',
        'MINORITY_INTEREST','INVESTMENT')),
    CONSTRAINT ce_status_chk        CHECK (status IN ('calculated','posted','reviewed')),
    CONSTRAINT ce_period_chk        CHECK (period_number BETWEEN 1 AND 16),
    CONSTRAINT ce_entity_chk        CHECK (source_company_code_id IS DISTINCT FROM dest_company_code_id),
    CONSTRAINT ce_line_count_chk    CHECK (line_count >= 0),
    CONSTRAINT ce_decision_chk      CHECK (decision_score IS NULL OR decision_score BETWEEN 0 AND 1)
);
COMMENT ON TABLE ledger.consolidation_elimination IS
    'IC elimination entries. source/dest as UUID FKs to company_code (authoritative). '
    'ic_elimination_id links to document.ic_elimination for engine-driven eliminations. '
    'functional_currency_code/exchange_rate/functional_amount support multi-currency reporting. '
    'approval_route + decision_score support workflow-gated approvals.';


-- ══════════════════════════════════════════════════════════════════════════════
-- BUDGET · COMMITMENT · PLANNING ENGINE — Ledger tables
-- ══════════════════════════════════════════════════════════════════════════════

-- ============================================================================
-- §BL1  ledger.commitment_schedule — periodic payment / milestone schedule
-- ============================================================================
-- Payment plan or milestone schedule for a commitment. Each row = one
-- scheduled payment date + amount. Tracks planned vs actual timing.
-- ============================================================================
CREATE TABLE IF NOT EXISTS ledger.commitment_schedule (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,

    -- Parent commitment
    commitment_id           uuid            NOT NULL,

    -- Line sequencing
    schedule_no             smallint        NOT NULL,

    -- Schedule type
    schedule_type           text            NOT NULL DEFAULT 'PERIODIC',
    milestone_name          text,

    -- Dates
    due_date                date            NOT NULL,
    expected_date           date,
    actual_date             date,

    -- Amounts
    currency_code           character(3)    NOT NULL,
    scheduled_amount        numeric(18,4)   NOT NULL,
    fulfilled_amount        numeric(18,4)   NOT NULL DEFAULT 0,
    remaining_amount        numeric(18,4)   GENERATED ALWAYS AS (
                                scheduled_amount - fulfilled_amount
                            ) STORED,
    base_amount             numeric(18,4),
    exchange_rate           numeric(18,10),

    -- Budget linkage (narrows to allocation for period-level reservation)
    budget_allocation_id    uuid,

    -- Fiscal period
    fiscal_year             smallint        NOT NULL,
    period_number           smallint        NOT NULL,

    -- Retention tracking
    is_retention            boolean         NOT NULL DEFAULT false,
    retention_release_date  date,

    -- Metadata
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Lifecycle
    status                  text            NOT NULL DEFAULT 'pending',
    is_active               boolean         GENERATED ALWAYS AS (
                                status IN ('pending','partially_fulfilled')
                            ) STORED,
    status_changed_at       timestamptz,
    status_changed_by       uuid,

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT cs_pkey                  PRIMARY KEY (id),
    CONSTRAINT cs_tenant_id_uq          UNIQUE (tenant_id, id),
    CONSTRAINT cs_commitment_seq_uq     UNIQUE (commitment_id, schedule_no),
    CONSTRAINT cs_status_chk            CHECK (status IN (
        'pending','partially_fulfilled','fulfilled','skipped','cancelled')),
    CONSTRAINT cs_type_chk              CHECK (schedule_type IN (
        'PERIODIC','MILESTONE','ADVANCE','RETENTION','FINAL','IRREGULAR')),
    CONSTRAINT cs_amount_nonneg         CHECK (scheduled_amount >= 0),
    CONSTRAINT cs_fulfilled_nonneg      CHECK (fulfilled_amount >= 0),
    CONSTRAINT cs_fulfilled_lte_sched   CHECK (fulfilled_amount <= scheduled_amount),
    CONSTRAINT cs_period_chk            CHECK (period_number BETWEEN 1 AND 16)
);

COMMENT ON TABLE ledger.commitment_schedule IS
    'Payment plan / milestone schedule for a commitment. Each row = one scheduled '
    'installment or milestone. remaining_amount = GENERATED (scheduled - fulfilled). '
    'is_retention marks retention-clause rows for deferred release. '
    'budget_allocation_id enables period-level budget reservation at schedule grain.';


-- ============================================================================
-- §BL2  ledger.commitment_fulfillment — consumption / drawdown against commitment
-- ============================================================================
-- Records actual fulfillment events: goods received, services accepted, payment.
-- Immutable (append-only). Reversals: new row with is_reversal = true.
-- ============================================================================
CREATE TABLE IF NOT EXISTS ledger.commitment_fulfillment (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,

    -- Parent commitment and optional schedule line
    commitment_id           uuid            NOT NULL,
    schedule_id             uuid,

    -- Fulfillment event
    fulfillment_type        text            NOT NULL,
    reference_doc_type      text,
    reference_doc_id        uuid,
    reference_line_id       uuid,

    -- Amounts
    currency_code           character(3)    NOT NULL,
    base_currency_code      character(3)    NOT NULL,
    amount                  numeric(18,4)   NOT NULL,
    base_amount             numeric(18,4),
    exchange_rate           numeric(18,10),

    -- Fiscal period
    fiscal_year             smallint        NOT NULL,
    period_number           smallint        NOT NULL,
    fulfillment_date        date            NOT NULL,

    -- Flags
    is_partial              boolean         NOT NULL DEFAULT false,
    is_reversal             boolean         NOT NULL DEFAULT false,
    reverses_id             uuid,

    -- Notes
    notes                   text,

    -- Metadata
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Audit (immutable — no updated_at)
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,

    CONSTRAINT cf_pkey                  PRIMARY KEY (id),
    CONSTRAINT cf_tenant_id_uq          UNIQUE (tenant_id, id),
    CONSTRAINT cf_type_chk              CHECK (fulfillment_type IN (
        'GRN','SERVICE_RECEIPT','PAYMENT','MILESTONE_COMPLETE','PARTIAL_DELIVERY',
        'INVOICE_MATCH','ADVANCE_RECOVERY','RETENTION_RELEASE')),
    CONSTRAINT cf_amount_nonneg         CHECK (amount >= 0),
    CONSTRAINT cf_period_chk            CHECK (period_number BETWEEN 1 AND 16),
    CONSTRAINT cf_no_self_reversal      CHECK (reverses_id IS DISTINCT FROM id),
    CONSTRAINT cf_reversal_ref_chk      CHECK (
        NOT is_reversal OR reverses_id IS NOT NULL)
);

COMMENT ON TABLE ledger.commitment_fulfillment IS
    'APPEND-ONLY fulfillment events against a commitment. Each row = goods receipt, '
    'service acceptance, payment, or milestone completion. '
    'Reversals: new row with is_reversal = true + reverses_id → original row. '
    'No UPDATE, no DELETE — enforced by log.trg_prevent_mutation().';


-- ============================================================================
-- §BL3  ledger.budget_transaction — budget reservation & release ledger
-- ============================================================================
-- Immutable movement ledger for all budget actions. Append-only.
-- Every RESERVE/COMMIT/CONSUME/RELEASE/TRANSFER/ADJUSTMENT creates one row.
-- Idempotency key prevents duplicate processing.
-- ============================================================================
CREATE TABLE IF NOT EXISTS ledger.budget_transaction (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,

    -- Target allocation
    budget_allocation_id    uuid            NOT NULL,

    -- Movement
    txn_type                text            NOT NULL,
    direction               text            NOT NULL,     -- DEBIT = reduces available; CREDIT = restores
    amount                  numeric(18,4)   NOT NULL,
    currency_code           character(3)    NOT NULL,

    -- Period context
    fiscal_year             smallint        NOT NULL,
    period_number           smallint        NOT NULL,
    effective_date          date            NOT NULL DEFAULT CURRENT_DATE,

    -- Source document
    source_doc_type         text,
    source_doc_id           uuid,
    commitment_id           uuid,

    -- State snapshots (allocation amounts before/after)
    previous_state          jsonb           NOT NULL,
    resulting_state         jsonb           NOT NULL,

    -- Idempotency + expiry
    idempotency_key         text,
    expires_at              timestamptz,

    -- Audit context
    reason                  text,
    performed_by            uuid            NOT NULL,
    performed_at            timestamptz     NOT NULL DEFAULT now(),

    -- Metadata
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Audit (immutable — no updated_at)
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,

    CONSTRAINT btr_pkey                 PRIMARY KEY (id),
    CONSTRAINT btr_tenant_id_uq         UNIQUE (tenant_id, id),
    CONSTRAINT btr_idempotency_uq       UNIQUE (idempotency_key),
    CONSTRAINT btr_type_chk             CHECK (txn_type IN (
        'RESERVE','COMMIT','CONSUME','RELEASE',
        'TRANSFER_IN','TRANSFER_OUT','ADJUSTMENT','CARRY_FORWARD','LAPSE')),
    CONSTRAINT btr_direction_chk        CHECK (direction IN ('DEBIT','CREDIT')),
    CONSTRAINT btr_amount_pos           CHECK (amount > 0),
    CONSTRAINT btr_period_chk           CHECK (period_number BETWEEN 1 AND 16),
    CONSTRAINT btr_state_obj_chk        CHECK (
        jsonb_typeof(previous_state) = 'object'
        AND jsonb_typeof(resulting_state) = 'object')
);

COMMENT ON TABLE ledger.budget_transaction IS
    'IMMUTABLE (append-only) movement ledger for all budget lifecycle events. '
    'txn_type: RESERVE → COMMIT → CONSUME → RELEASE; TRANSFER_IN/OUT; ADJUSTMENT; CARRY_FORWARD; LAPSE. '
    'direction: DEBIT = reduces available balance; CREDIT = restores available balance. '
    'previous_state / resulting_state capture allocation amounts before and after. '
    'idempotency_key prevents duplicate processing.';


-- ============================================================================
-- §BL4  ledger.budget_transfer — inter-allocation transfer
-- ============================================================================
-- Formalises movement of budget authority between allocations.
-- Creates paired budget_transaction rows (TRANSFER_OUT + TRANSFER_IN).
-- ============================================================================
CREATE TABLE IF NOT EXISTS ledger.budget_transfer (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,

    -- Parties
    from_allocation_id      uuid            NOT NULL,
    to_allocation_id        uuid            NOT NULL,

    -- Transfer details
    amount                  numeric(18,4)   NOT NULL,
    currency_code           character(3)    NOT NULL,
    fiscal_year             smallint        NOT NULL,
    transfer_date           date            NOT NULL,
    reason                  text            NOT NULL,
    notes                   text,

    -- Paired transaction references (set on approval/completion)
    from_txn_id             uuid,
    to_txn_id               uuid,

    -- Approval
    approved_at             timestamptz,
    approved_by             uuid,

    -- Metadata
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Lifecycle
    status                  text            NOT NULL DEFAULT 'pending',
    status_changed_at       timestamptz,
    status_changed_by       uuid,

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT btx_pkey                 PRIMARY KEY (id),
    CONSTRAINT btx_tenant_id_uq         UNIQUE (tenant_id, id),
    CONSTRAINT btx_status_chk           CHECK (status IN (
        'pending','approved','rejected','completed','reversed')),
    CONSTRAINT btx_amount_pos           CHECK (amount > 0),
    CONSTRAINT btx_no_self_transfer     CHECK (from_allocation_id IS DISTINCT FROM to_allocation_id),
    CONSTRAINT btx_reason_nonempty      CHECK (btrim(reason) <> ''),
    CONSTRAINT btx_approval_consistent  CHECK (
        (status IN ('pending','rejected') AND approved_at IS NULL AND approved_by IS NULL)
        OR (status NOT IN ('pending','rejected') AND approved_at IS NOT NULL AND approved_by IS NOT NULL)
    )
);

COMMENT ON TABLE ledger.budget_transfer IS
    'Formalised inter-allocation budget transfer. Approved transfers create paired '
    'ledger.budget_transaction rows: TRANSFER_OUT from source + TRANSFER_IN to dest. '
    'Status lifecycle: pending → approved → completed | rejected | reversed.';


-- ============================================================================
-- §BL5  ledger.budget_balance — period-level budget balance store (UPSERT)
-- ============================================================================
-- Materialised period snapshot. UPSERT target for budget service.
-- One row per (allocation, fiscal_year, period_number). Tracks opening/movement/closing.
-- version for optimistic concurrency. closing_amount is GENERATED.
-- ============================================================================
CREATE TABLE IF NOT EXISTS ledger.budget_balance (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,

    -- Source allocation
    budget_allocation_id    uuid            NOT NULL,

    -- Period key
    fiscal_year             smallint        NOT NULL,
    period_number           smallint        NOT NULL,
    currency_code           character(3)    NOT NULL,

    -- Balance buckets
    opening_amount          numeric(18,4)   NOT NULL DEFAULT 0,
    reserved_amount         numeric(18,4)   NOT NULL DEFAULT 0,
    consumed_amount         numeric(18,4)   NOT NULL DEFAULT 0,
    released_amount         numeric(18,4)   NOT NULL DEFAULT 0,
    adjusted_amount         numeric(18,4)   NOT NULL DEFAULT 0,

    -- closing = opening - reserved - consumed + released + adjusted
    closing_amount          numeric(18,4)   GENERATED ALWAYS AS (
                                opening_amount
                                - reserved_amount
                                - consumed_amount
                                + released_amount
                                + adjusted_amount
                            ) STORED,

    -- Concurrency
    version                 integer         NOT NULL DEFAULT 1,
    last_txn_id             uuid,
    last_updated_at         timestamptz,

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT bb_pkey                      PRIMARY KEY (id),
    CONSTRAINT bb_tenant_id_uq              UNIQUE (tenant_id, id),
    CONSTRAINT bb_allocation_period_uq      UNIQUE (budget_allocation_id, fiscal_year, period_number),
    CONSTRAINT bb_period_chk                CHECK (period_number BETWEEN 0 AND 16),
    CONSTRAINT bb_version_chk               CHECK (version >= 1),
    CONSTRAINT bb_opening_nonneg            CHECK (opening_amount >= 0),
    CONSTRAINT bb_reserved_nonneg           CHECK (reserved_amount >= 0),
    CONSTRAINT bb_consumed_nonneg           CHECK (consumed_amount >= 0),
    CONSTRAINT bb_released_nonneg           CHECK (released_amount >= 0)
);

COMMENT ON TABLE ledger.budget_balance IS
    'Period-level budget balance store. UPSERT target for budget lifecycle service. '
    'closing_amount = GENERATED (opening - reserved - consumed + released + adjusted). '
    'period_number 0 = annual / YTD summary row. '
    'Concurrent-safe via ON CONFLICT DO UPDATE with version increment. '
    'One row per (allocation, fiscal_year, period_number).';


-- ============================================================================
-- §BL6  ledger.planning_output — model-generated period output rows
-- ============================================================================
-- UPSERT target for planning calculation engine. One row per
-- (model, fiscal_year, period_number, gl_account, dimension_set).
-- Partial unique index (see below) handles nullable dimension columns.
-- ============================================================================
CREATE TABLE IF NOT EXISTS ledger.planning_output (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,

    -- Source model + formula
    planning_model_id       uuid            NOT NULL,
    formula_id              uuid,

    -- Account
    gl_account_id           uuid,

    -- Period
    fiscal_year             smallint        NOT NULL,
    period_number           smallint        NOT NULL,
    currency_code           character(3)    NOT NULL,

    -- Amounts
    planned_amount          numeric(18,4)   NOT NULL DEFAULT 0,
    prior_year_amount       numeric(18,4),
    variance_amount         numeric(18,4)   GENERATED ALWAYS AS (
                                planned_amount - COALESCE(prior_year_amount, 0)
                            ) STORED,

    -- Dimensions
    cost_center_id          uuid,
    profit_center_id        uuid,
    project_id              uuid,
    dimension_set_id        uuid,

    -- Driver inputs used (snapshot)
    driver_values           jsonb,

    -- Approval
    is_approved             boolean         NOT NULL DEFAULT false,
    approved_at             timestamptz,
    approved_by             uuid,

    -- Metadata
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Concurrency
    version                 integer         NOT NULL DEFAULT 1,

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT po_pkey                  PRIMARY KEY (id),
    CONSTRAINT po_tenant_id_uq          UNIQUE (tenant_id, id),
    CONSTRAINT po_period_chk            CHECK (period_number BETWEEN 1 AND 16),
    CONSTRAINT po_version_chk           CHECK (version >= 1)
);

-- Partial unique index for planning_output — handles nullable dimension columns.
CREATE UNIQUE INDEX IF NOT EXISTS ux_po_model_period_dim ON ledger.planning_output (
    planning_model_id,
    fiscal_year,
    period_number,
    COALESCE(gl_account_id,      '00000000-0000-0000-0000-000000000000'::uuid),
    COALESCE(cost_center_id,     '00000000-0000-0000-0000-000000000000'::uuid),
    COALESCE(profit_center_id,   '00000000-0000-0000-0000-000000000000'::uuid),
    COALESCE(project_id,         '00000000-0000-0000-0000-000000000000'::uuid),
    COALESCE(dimension_set_id,   '00000000-0000-0000-0000-000000000000'::uuid)
);

COMMENT ON TABLE ledger.planning_output IS
    'UPSERT target for planning calculation engine. One row per '
    '(model, year, period, account, dimension combination). '
    'variance_amount = GENERATED (planned - prior_year). '
    'Unique constraint via ux_po_model_period_dim partial index (handles NULLs). '
    'driver_values JSON snapshot enables audit/replay of calculation inputs.';


-- ══════════════════════════════════════════════════════════════════════════════
-- INVENTORY MANAGEMENT ENGINE — Ledger tables
-- ══════════════════════════════════════════════════════════════════════════════

-- ============================================================================
-- §INV1  ledger.inventory_balance
-- Real-time on-hand quantity and value per item/warehouse/lot/serial position.
-- ============================================================================
CREATE TABLE IF NOT EXISTS ledger.inventory_balance (
    -- Identity
    id                  uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id           uuid            NOT NULL,

    -- Company scope
    company_code_id     uuid            NOT NULL,

    -- Position key
    item_id             uuid            NOT NULL,
    warehouse_id        uuid            NOT NULL,
    lot_number          text,
    serial_number       text,

    -- Stock position
    quantity_on_hand    numeric(18,4)   NOT NULL DEFAULT 0,
    unit_cost           numeric(18,4)   NOT NULL DEFAULT 0,
    total_value         numeric(18,4)   GENERATED ALWAYS AS (quantity_on_hand * unit_cost) STORED,
    currency_code       character(3)    NOT NULL,

    -- Movement linkage (last event that changed this position)
    last_movement_at    timestamptz,
    last_movement_id    uuid,

    -- Concurrency
    version             integer         NOT NULL DEFAULT 1,

    -- Metadata
    metadata            jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Lifecycle
    status              shared.active_inactive_archived_d NOT NULL DEFAULT 'active',
    is_active           boolean         GENERATED ALWAYS AS (status = 'active') STORED,

    -- Audit
    created_at          timestamptz     NOT NULL DEFAULT now(),
    created_by          uuid            NOT NULL,
    updated_at          timestamptz,
    updated_by          uuid,

    CONSTRAINT ib_pkey          PRIMARY KEY (id),
    CONSTRAINT ib_tenant_id_uq  UNIQUE (tenant_id, id),
    CONSTRAINT ib_unit_cost_chk CHECK (unit_cost >= 0),
    CONSTRAINT ib_version_chk   CHECK (version >= 1),
    CONSTRAINT ib_currency_chk  CHECK (btrim(currency_code::text) <> '')
);

COMMENT ON TABLE ledger.inventory_balance IS
    'Real-time on-hand quantity and value per item/warehouse/lot/serial position. '
    'Mutable — updated by movement PostingService. Optimistic-locked via version column. '
    'Negative quantity_on_hand permitted when warehouse.is_negative_stock_allowed = true; '
    'no hard non-negative CHECK here. Natural key uniqueness enforced by four partial '
    'unique indexes (see 07_indexes/005_ledger.sql).';


-- ============================================================================
-- §INV2  ledger.inventory_movement
-- Single source of truth for all inventory quantity changes.
-- ============================================================================
CREATE TABLE IF NOT EXISTS ledger.inventory_movement (
    -- Identity
    id                  uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id           uuid            NOT NULL,

    -- Company scope
    company_code_id     uuid            NOT NULL,

    -- Position key
    item_id             uuid            NOT NULL,
    warehouse_id        uuid            NOT NULL,

    -- Movement classification (inline CHECK — see §6.9 of spec)
    movement_type       text            NOT NULL,

    -- Quantity & cost (signed — positive = IN, negative = OUT)
    quantity            numeric(18,4)   NOT NULL,
    unit_cost           numeric(18,4)   NOT NULL DEFAULT 0,
    total_value         numeric(18,4)   GENERATED ALWAYS AS (quantity * unit_cost) STORED,
    currency_code       character(3)    NOT NULL,

    -- Lot / serial
    lot_number          text,
    serial_number       text,

    -- Source document linkage
    ref_doc_type        text,
    ref_doc_id          uuid,

    -- Transfer linkage (both required for TRANSFER_OUT / TRANSFER_IN)
    source_warehouse_id uuid,
    dest_warehouse_id   uuid,

    -- Reversal chain (required when movement_type = 'REVERSAL')
    reversal_of_id      uuid,

    -- Execution metadata
    performed_at        timestamptz     NOT NULL DEFAULT now(),
    performed_by        uuid            NOT NULL,
    notes               text,

    -- GL posting fields — NULL at INSERT; enriched once within same posting txn
    reference_je_id     uuid,
    posted_at           timestamptz,
    posted_by           uuid,

    -- Metadata
    metadata            jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Audit (insert-only — no updated_at/updated_by)
    created_at          timestamptz     NOT NULL DEFAULT now(),
    created_by          uuid            NOT NULL,

    CONSTRAINT im_pkey                  PRIMARY KEY (id),
    CONSTRAINT im_tenant_id_uq          UNIQUE (tenant_id, id),
    CONSTRAINT im_movement_type_chk     CHECK (movement_type IN (
                                            'RECEIPT',
                                            'ISSUE_SALES',
                                            'ISSUE_PRODUCTION',
                                            'TRANSFER_OUT',
                                            'TRANSFER_IN',
                                            'ADJUSTMENT',
                                            'SCRAP',
                                            'RETURN',
                                            'OPENING_BALANCE',
                                            'REVERSAL'
                                        )),
    CONSTRAINT im_unit_cost_chk         CHECK (unit_cost >= 0),
    CONSTRAINT im_currency_chk          CHECK (btrim(currency_code::text) <> ''),
    CONSTRAINT im_reversal_ref_chk      CHECK (movement_type <> 'REVERSAL' OR reversal_of_id IS NOT NULL),
    CONSTRAINT im_no_self_reversal      CHECK (reversal_of_id IS DISTINCT FROM id),
    CONSTRAINT im_transfer_wh_chk       CHECK (
                                            movement_type NOT IN ('TRANSFER_OUT', 'TRANSFER_IN')
                                            OR (source_warehouse_id IS NOT NULL AND dest_warehouse_id IS NOT NULL)
                                        ),
    CONSTRAINT im_posting_pair_chk      CHECK (
                                            (posted_at IS NULL) = (posted_by IS NULL)
                                        )
);

COMMENT ON TABLE ledger.inventory_movement IS
    'Single source of truth for all inventory quantity changes. '
    'Effectively immutable: core business columns sealed at INSERT. '
    'Posting fields (reference_je_id, posted_at, posted_by) enriched once '
    'within the same posting transaction. Corrections via REVERSAL rows only. '
    'Signed quantity: positive = IN, negative = OUT.';


-- ============================================================================
-- §INV3  ledger.inventory_valuation_layer
-- Cost layers for FIFO / weighted-average / standard-cost / specific-id.
-- ============================================================================
CREATE TABLE IF NOT EXISTS ledger.inventory_valuation_layer (
    -- Identity
    id                      uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid            NOT NULL,

    -- Company scope
    company_code_id         uuid            NOT NULL,

    -- Position key
    item_id                 uuid            NOT NULL,
    warehouse_id            uuid            NOT NULL,

    -- Layer metadata
    layer_date              date            NOT NULL,
    receipt_movement_id     uuid            NOT NULL,

    -- Layer quantities
    original_qty            numeric(18,4)   NOT NULL,
    remaining_qty           numeric(18,4)   NOT NULL,

    -- Cost
    unit_cost               numeric(18,4)   NOT NULL,
    currency_code           character(3)    NOT NULL,

    -- Consumption flag
    is_consumed             boolean         NOT NULL DEFAULT false,

    -- Lot / serial (mirrors receipt movement for layer lookup efficiency)
    lot_number              text,
    serial_number           text,

    -- Metadata
    metadata                jsonb           NOT NULL DEFAULT '{}'::jsonb,

    -- Audit
    created_at              timestamptz     NOT NULL DEFAULT now(),
    created_by              uuid            NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT ivl_pkey               PRIMARY KEY (id),
    CONSTRAINT ivl_tenant_id_uq       UNIQUE (tenant_id, id),
    CONSTRAINT ivl_currency_chk       CHECK (btrim(currency_code::text) <> ''),
    CONSTRAINT ivl_original_qty_pos   CHECK (original_qty > 0),
    CONSTRAINT ivl_remaining_nonneg   CHECK (remaining_qty >= 0),
    CONSTRAINT ivl_remaining_lte_orig CHECK (remaining_qty <= original_qty),
    CONSTRAINT ivl_unit_cost_nonneg   CHECK (unit_cost >= 0),
    CONSTRAINT ivl_consumed_sync_chk  CHECK (is_consumed = (remaining_qty = 0))
);

COMMENT ON TABLE ledger.inventory_valuation_layer IS
    'Cost layers for FIFO/weighted-average/standard-cost/specific-identification costing. '
    'One row per stock receipt. remaining_qty decrements as issue movements consume the layer. '
    'FIFO scan uses partial index on (is_consumed = false) ordered by layer_date ASC. '
    'Mutable (remaining_qty / is_consumed updated by PostingService on issue).';


-- ══════════════════════════════════════════════════════════════════════════════
-- IC ENGINE — Ledger tables
-- ══════════════════════════════════════════════════════════════════════════════

-- ============================================================================
-- §IC1  ledger.ic_elimination_line — immutable debit/credit lines
-- ============================================================================
CREATE TABLE IF NOT EXISTS ledger.ic_elimination_line (
    id                          uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id                   uuid            NOT NULL,
    elimination_id              uuid            NOT NULL,
    company_code_id             uuid            NOT NULL,
    fiscal_year                 smallint        NOT NULL,
    period_number               smallint        NOT NULL,
    line_no                     smallint        NOT NULL,
    gl_account_id               uuid            NOT NULL,
    debit_amount                numeric(18,4)   NOT NULL DEFAULT 0,
    credit_amount               numeric(18,4)   NOT NULL DEFAULT 0,
    functional_debit            numeric(18,4)   NOT NULL DEFAULT 0,
    functional_credit           numeric(18,4)   NOT NULL DEFAULT 0,
    cost_center_id              uuid,
    profit_center_id            uuid,
    project_id                  uuid,
    site_id                     uuid,
    dimension_set_id            uuid,
    description                 text,
    created_at                  timestamptz     NOT NULL DEFAULT now(),
    created_by                  uuid            NOT NULL,

    CONSTRAINT icel_pkey             PRIMARY KEY (id),
    CONSTRAINT icel_tenant_id_uq     UNIQUE (tenant_id, id),
    CONSTRAINT icel_elim_line_uq     UNIQUE (elimination_id, line_no),
    CONSTRAINT icel_polarity_chk     CHECK (
        (debit_amount > 0 AND credit_amount = 0)
        OR (debit_amount = 0 AND credit_amount > 0)
    ),
    CONSTRAINT icel_nonneg_chk       CHECK (debit_amount >= 0 AND credit_amount >= 0),
    CONSTRAINT icel_func_polarity_chk CHECK (
        (debit_amount > 0 AND functional_debit > 0)
        OR (credit_amount > 0 AND functional_credit > 0)
    ),
    CONSTRAINT icel_func_nonneg_chk  CHECK (functional_debit >= 0 AND functional_credit >= 0),
    CONSTRAINT icel_line_no_chk      CHECK (line_no > 0),
    CONSTRAINT icel_period_chk       CHECK (period_number BETWEEN 1 AND 16)
);

COMMENT ON TABLE ledger.ic_elimination_line IS
    'Immutable debit/credit child lines of document.ic_elimination. '
    'Strict polarity: exactly one side > 0 (mirrors journal_line). '
    'Append-only: no updated_at/updated_by. Corrections via header reversal.';



-- FILE: /d/Products/athyper/server/db/sql/04_tables/006_log.sql
-- 04_tables/006_log.sql
-- Consolidated log schema — 26 tables (down from 68 backup tables)
-- Depends on: 01_schemas, 02_types_domains, 04_tables/003_master.sql, 04_tables/002_control.sql
--
-- Column order: Identity — Table-specific — Audit (NO updated_at, NO metadata, NO status)
-- All log tables are append-only.
-- Lookup validation: extensible / shared vocabularies — control.trg_validate_lookup_columns
--                    sealed / protocol-level values   — inline CHECK
-- Partitioning:    high-volume tables — PARTITION BY RANGE (created_at)
--                  _default partition seeds; pg_partman manages monthly children
--
-- ———————————————————————————————————————————————————————————————————————————
-- | SECURITY & IDENTITY (Phase 1)                                           |
-- |   §1  audit_log                  — generic entity mutation trail        |
-- |   §2  security_event_log         — auth / session events                |
-- |   §3  permission_decision_log    — auth-engine allow/deny decisions     |
-- |   §4  field_access_log           — PII field read audit                 |
-- |   §5  password_history           — hash reuse prevention                |
-- |   §6  attachment_access_log      — file download/preview audit          |
-- |   §7  share_audit_log            — delegation / share grant audit       |
-- |                                                                         |
-- | ENTITY & WORKFLOW (Phase 2)                                             |
-- |   §8  entity_lifecycle_log       — entity state-machine transitions     |
-- |   §9  workflow_event_log         — workflow steps + transitions         |
-- |  §10  close_override_log         — close override + book close audit    |
-- |                                                                         |
-- | SYSTEM OPERATIONS (Phase 3)                                             |
-- |  §11  job_log                    — job step + run history               |
-- |  §12  policy_evaluation_log      — policy scoring decisions             |
-- |  §13  hash_anchor                — tamper-evidence chain anchors        |
-- |  §14  dimension_resolution_log   — dimension resolution trace           |
-- |                                                                         |
-- | CONSOLIDATED ACTIVITY (NEW — replaces 9 tables)                        |
-- |  §15  activity_log               — domain activity unified table        |
-- |                                                                         |
-- | FINANCE CLOSE (Phase 4)                                                 |
-- |  §16  close_activity_log         — 5 close activity tables → 1         |
-- |                                                                         |
-- | EXPORT (NEW — replaces 3 tables)                                        |
-- |  §17  export_log                 — export/download audit unified table  |
-- |                                                                         |
-- | USER ACTIVITY (Phase 5)                                                 |
-- |  §18  comment_retention_log      — compliance comment retention         |
-- |  §19  search_history             — principal search activity            |
-- |                                                                         |
-- | AI (Phase 6)                                                            |
-- |  §20  ai_inference_log           — ai_action + ai_prediction → 1       |
-- |  §21  ai_monitoring_log          — ai_drift + anomaly_baseline → 1     |
-- |  §22  ai_feedback_log            — atlas + classification feedback → 1  |
-- |  §23  ai_calibration_log         — threshold calibration history        |
-- |  §24  ai_call_transcript         — AI voice transcripts                 |
-- |                                                                         |
-- | ANALYTICS (Phase 7)                                                     |
-- |  §25  kpi_execution_log          — KPI calculation results              |
-- |  §26  workspace_usage_metric     — workspace usage telemetry            |
-- ———————————————————————————————————————————————————————————————————————————


-- ============================================================================
-- §1  audit_log
-- ============================================================================
CREATE TABLE IF NOT EXISTS log.audit_log (
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,
    log_type                shared.log_type_d NOT NULL DEFAULT 'business',
    entity_type             text        NOT NULL,
    entity_id               uuid        NOT NULL,
    operation               text        NOT NULL,
    actor_id                uuid,
    actor_type              text,
    company_code_id         uuid,
    old_values              jsonb,
    new_values              jsonb,
    changed_fields          text[],
    correlation_id          uuid,
    request_id              text,
    ip_address              inet,
    user_agent              text,
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    CONSTRAINT audit_log_pkey       PRIMARY KEY (id, created_at),
    CONSTRAINT audit_log_op_chk     CHECK (operation IN (
        'insert', 'update', 'delete', 'status_change',
        'bulk_insert', 'bulk_update', 'bulk_delete',
        'restore', 'archive', 'purge'
    )),
    CONSTRAINT audit_log_entity_chk CHECK (btrim(entity_type) <> '')
    -- actor_type: 09_triggers — control.trg_validate_lookup_columns('log.actor_type')
) PARTITION BY RANGE (created_at);
COMMENT ON TABLE  log.audit_log IS 'Generic entity mutation trail. actor_type in log.actor_type lookup. Partitioned monthly.';
COMMENT ON COLUMN log.audit_log.old_values IS 'Column snapshot before operation. NULL for inserts.';
COMMENT ON COLUMN log.audit_log.new_values IS 'Column snapshot after operation. NULL for deletes.';
COMMENT ON COLUMN log.audit_log.correlation_id IS 'Links to event.outbox id for end-to-end trace.';
CREATE TABLE IF NOT EXISTS log.audit_log_default PARTITION OF log.audit_log DEFAULT;


-- ============================================================================
-- §2  security_event_log
-- ============================================================================
CREATE TABLE IF NOT EXISTS log.security_event_log (
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,
    log_type                text        NOT NULL
                            GENERATED ALWAYS AS ('system') STORED,
    event_category          text        NOT NULL,
    event_type              text        NOT NULL,
    outcome                 text        NOT NULL,
    principal_id            uuid,
    actor_type              text,
    session_id              text,
    ip_address              inet,
    user_agent              text,
    device_fingerprint      text,
    country_code            char(2),
    mfa_method              text,
    mfa_channel             text,
    risk_score              smallint,
    risk_flags              text[],
    detail                  jsonb,
    failure_reason          text,
    correlation_id          uuid,
    keycloak_event_id       text,
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    CONSTRAINT sel_pkey        PRIMARY KEY (id, created_at),
    CONSTRAINT sel_outcome_chk CHECK (outcome IN ('success', 'failure', 'blocked', 'partial', 'expired')),
    CONSTRAINT sel_risk_chk    CHECK (risk_score IS NULL OR risk_score BETWEEN 0 AND 100)
    -- event_category: 09_triggers — control.trg_validate_lookup_columns('log.security_event_category')
) PARTITION BY RANGE (created_at);
COMMENT ON TABLE  log.security_event_log IS 'Auth/session security events. log_type always system. event_category in log.security_event_category lookup. Partitioned monthly.';
COMMENT ON COLUMN log.security_event_log.risk_score IS '0–100. >=80 triggers SIEM alert.';
COMMENT ON COLUMN log.security_event_log.keycloak_event_id IS 'Original KC event id for cross-system trace.';
CREATE TABLE IF NOT EXISTS log.security_event_log_default PARTITION OF log.security_event_log DEFAULT;


-- ============================================================================
-- §3  permission_decision_log
-- ============================================================================
CREATE TABLE IF NOT EXISTS log.permission_decision_log (
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,
    log_type                text        NOT NULL
                            GENERATED ALWAYS AS ('system') STORED,
    principal_id            uuid        NOT NULL,
    persona_code            text,
    permission_id           uuid,
    permission_code         text,
    feature_id              uuid,
    feature_code            text,
    entity_type             text,
    entity_id               uuid,
    module_code             text,
    decision                text        NOT NULL,
    decision_reason         text        NOT NULL,
    scope_applied           text,
    company_code_id         uuid,
    matched_grant_id        uuid,
    matched_role_id         uuid,
    matched_group_id        uuid,
    plan_gate_result        text,
    evaluation_ms           integer,
    request_id              text,
    correlation_id          uuid,
    ip_address              inet,
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    CONSTRAINT pdl_pkey           PRIMARY KEY (id, created_at),
    CONSTRAINT pdl_decision_chk   CHECK (decision IN (
        'allow', 'deny', 'not_found', 'not_in_plan', 'addon_required',
        'override_denied', 'not_entitled', 'not_granted', 'module_not_subscribed'
    )),
    CONSTRAINT pdl_reason_chk     CHECK (btrim(decision_reason) <> ''),
    CONSTRAINT pdl_object_chk     CHECK (num_nonnulls(permission_id, feature_id) = 1),
    CONSTRAINT pdl_plan_gate_chk  CHECK (plan_gate_result IS NULL OR plan_gate_result IN (
        'allowed', 'not_in_plan', 'addon_required', 'override', 'skipped'
    ))
) PARTITION BY RANGE (created_at);
COMMENT ON TABLE  log.permission_decision_log IS 'Auth-engine allow/deny decisions. Exactly one of permission_id/feature_id per row. Partitioned monthly.';
COMMENT ON COLUMN log.permission_decision_log.evaluation_ms IS 'Auth-engine latency for performance monitoring.';
CREATE TABLE IF NOT EXISTS log.permission_decision_log_default PARTITION OF log.permission_decision_log DEFAULT;


-- ============================================================================
-- §4  field_access_log
-- ============================================================================
CREATE TABLE IF NOT EXISTS log.field_access_log (
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,
    log_type                shared.log_type_d NOT NULL DEFAULT 'business',
    principal_id            uuid        NOT NULL,
    company_code_id         uuid,
    entity_type             text        NOT NULL,
    entity_id               uuid        NOT NULL,
    field_name              text        NOT NULL,
    field_classification    text        NOT NULL,
    access_purpose          text,
    access_justification    text,
    ip_address              inet,
    user_agent              text,
    request_id              text,
    correlation_id          uuid,
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    CONSTRAINT fal_pkey         PRIMARY KEY (id, created_at),
    CONSTRAINT fal_entity_chk   CHECK (btrim(entity_type) <> ''),
    CONSTRAINT fal_field_chk    CHECK (btrim(field_name) <> '')
    -- field_classification: 09_triggers — control.trg_validate_lookup_columns('log.field_classification')
) PARTITION BY RANGE (created_at);
COMMENT ON TABLE  log.field_access_log IS 'PII/sensitive field read audit. field_classification in log.field_classification lookup (extensible — tenants add custom classes). Partitioned monthly.';
CREATE TABLE IF NOT EXISTS log.field_access_log_default PARTITION OF log.field_access_log DEFAULT;


-- ============================================================================
-- §5  password_history
-- ============================================================================
CREATE TABLE IF NOT EXISTS log.password_history (
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,
    log_type                text        NOT NULL
                            GENERATED ALWAYS AS ('system') STORED,
    principal_id            uuid        NOT NULL,
    password_hash           text        NOT NULL,
    hash_algorithm          text        NOT NULL DEFAULT 'bcrypt',
    hash_version            smallint    NOT NULL DEFAULT 1,
    change_reason           text,
    changed_by              uuid,
    ip_address              inet,
    correlation_id          uuid,
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    CONSTRAINT ph_pkey      PRIMARY KEY (id),
    CONSTRAINT ph_hash_chk  CHECK (btrim(password_hash) <> ''),
    CONSTRAINT ph_alg_chk   CHECK (hash_algorithm IN ('bcrypt', 'argon2id', 'scrypt', 'pbkdf2'))
    -- change_reason: 09_triggers — control.trg_validate_lookup_columns('log.password_change_reason')
);
COMMENT ON TABLE  log.password_history IS 'Password hash history. RLS: NO tenant read. Admin-only. change_reason in log.password_change_reason lookup.';
COMMENT ON COLUMN log.password_history.hash_version IS 'Hash parameter version — allows rotation without invalidating existing rows.';


-- ============================================================================
-- §6  attachment_access_log
-- ============================================================================
CREATE TABLE IF NOT EXISTS log.attachment_access_log (
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,
    log_type                shared.log_type_d NOT NULL DEFAULT 'business',
    principal_id            uuid        NOT NULL,
    company_code_id         uuid,
    attachment_id           uuid        NOT NULL,
    parent_entity_type      text,
    parent_entity_id        uuid,
    access_type             text        NOT NULL,
    attachment_name         text,
    attachment_size_bytes   bigint,
    attachment_mime_type    text,
    ip_address              inet,
    user_agent              text,
    request_id              text,
    correlation_id          uuid,
    outcome                 text        NOT NULL DEFAULT 'success',
    failure_reason          text,
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    CONSTRAINT aal_pkey         PRIMARY KEY (id, created_at),
    CONSTRAINT aal_outcome_chk  CHECK (outcome IN ('success', 'denied', 'not_found', 'error', 'watermarked'))
    -- access_type: 09_triggers — control.trg_validate_lookup_columns('log.attachment_access_type')
) PARTITION BY RANGE (created_at);
COMMENT ON TABLE  log.attachment_access_log IS 'Attachment download/preview audit. access_type in log.attachment_access_type lookup (extensible). Partitioned monthly.';
COMMENT ON COLUMN log.attachment_access_log.attachment_name IS 'Denormalised at access time — survives rename/delete of source attachment.';
CREATE TABLE IF NOT EXISTS log.attachment_access_log_default PARTITION OF log.attachment_access_log DEFAULT;


-- ============================================================================
-- §7  share_audit_log
-- ============================================================================
CREATE TABLE IF NOT EXISTS log.share_audit_log (
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,
    log_type                shared.log_type_d NOT NULL DEFAULT 'business',
    actor_id                uuid        NOT NULL,
    company_code_id         uuid,
    target_principal_id     uuid,
    target_group_id         uuid,
    shared_entity_type      text        NOT NULL,
    shared_entity_id        uuid        NOT NULL,
    share_type              text        NOT NULL,
    access_level            text        NOT NULL,
    expires_at              timestamptz,
    action                  text        NOT NULL,
    access_grant_id         uuid,
    request_id              text,
    correlation_id          uuid,
    ip_address              inet,
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    CONSTRAINT sal_pkey         PRIMARY KEY (id),
    CONSTRAINT sal_share_chk    CHECK (share_type IN ('share_read', 'share_edit', 'delegate')),
    CONSTRAINT sal_level_chk    CHECK (access_level IN ('read', 'edit', 'full')),
    CONSTRAINT sal_action_chk   CHECK (action IN ('grant', 'revoke', 'modify', 'expire')),
    CONSTRAINT sal_target_chk   CHECK (num_nonnulls(target_principal_id, target_group_id) = 1),
    CONSTRAINT sal_entity_chk   CHECK (btrim(shared_entity_type) <> '')
);
COMMENT ON TABLE log.share_audit_log IS 'Share/delegation audit trail. Exactly one target (principal OR group). access_grant_id links to master.access_grant.';


-- ============================================================================
-- §8  entity_lifecycle_log
-- ============================================================================
CREATE TABLE IF NOT EXISTS log.entity_lifecycle_log (
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,
    log_type                shared.log_type_d NOT NULL DEFAULT 'business',
    entity_type             text        NOT NULL,
    entity_id               uuid        NOT NULL,
    lifecycle_id            uuid,
    operation_code          text,
    from_status             text,
    to_status               text        NOT NULL,
    from_state_id           uuid,
    to_state_id             uuid,
    actor_id                uuid,
    actor_type              text,
    company_code_id         uuid,
    remarks                 text,
    payload                 jsonb,
    correlation_id          uuid,
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    CONSTRAINT ell_pkey         PRIMARY KEY (id),
    CONSTRAINT ell_entity_chk   CHECK (btrim(entity_type) <> ''),
    CONSTRAINT ell_status_chk   CHECK (btrim(to_status) <> '')
);
COMMENT ON TABLE log.entity_lifecycle_log IS 'Entity state-machine transition audit. Distinct from audit_log (column mutations). Feeds state compliance reporting.';


-- ============================================================================
-- §9  workflow_event_log  (absorbs log.workflow_transition)
-- ============================================================================
CREATE TABLE IF NOT EXISTS log.workflow_event_log (
    id                          uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id                   uuid        NOT NULL,
    log_type                    shared.log_type_d NOT NULL DEFAULT 'business',
    event_type                  text        NOT NULL,
    severity                    text        NOT NULL DEFAULT 'info',
    schema_version              smallint    NOT NULL DEFAULT 1,
    instance_id                 text        NOT NULL,
    step_instance_id            text,
    workflow_template_code      text,
    workflow_template_version   smallint,
    module_code                 text,
    entity_type                 text        NOT NULL,
    entity_id                   uuid        NOT NULL,
    actor_id                    uuid,
    actor_type                  text,
    actor_is_admin              boolean     NOT NULL DEFAULT false,
    -- Transition columns (absorbs log.workflow_transition)
    from_status                 text,
    to_status                   text,
    transition_name             text,
    action                      text,
    -- Payload
    previous_state              jsonb,
    new_state                   jsonb,
    comment                     text,
    attachments                 jsonb,
    detail                      jsonb,
    -- Tamper-evidence
    hash_prev                   text,
    hash_curr                   text,
    is_redacted                 boolean     NOT NULL DEFAULT false,
    redaction_version           smallint,
    key_version                 smallint,
    idempotency_key             text,
    -- Traceability
    ip_address                  inet,
    user_agent                  text,
    correlation_id              uuid,
    session_id                  text,
    trace_id                    text,
    created_at                  timestamptz NOT NULL DEFAULT now(),
    created_by                  uuid        NOT NULL,
    CONSTRAINT wel_pkey         PRIMARY KEY (id, created_at),
    CONSTRAINT wel_severity_chk CHECK (severity IN ('info', 'warning', 'error', 'critical')),
    CONSTRAINT wel_hash_curr_fmt CHECK (hash_curr IS NULL OR hash_curr ~ '^[0-9a-f]{64}$'),
    CONSTRAINT wel_hash_prev_fmt CHECK (hash_prev IS NULL OR hash_prev ~ '^[0-9a-f]{64}$'),
    CONSTRAINT wel_entity_chk   CHECK (btrim(entity_type) <> '')
) PARTITION BY RANGE (created_at);
COMMENT ON TABLE  log.workflow_event_log IS 'Workflow step events and transitions. Absorbs log.workflow_transition (transition_name, from_status, to_status). Tamper-evidence via hash chain. Partitioned monthly.';
COMMENT ON COLUMN log.workflow_event_log.transition_name IS 'Populated for transition events (migrated from log.workflow_transition.transition_name).';
CREATE TABLE IF NOT EXISTS log.workflow_event_log_default PARTITION OF log.workflow_event_log DEFAULT;


-- ============================================================================
-- §10  close_override_log  (absorbs log.book_close_audit_log)
-- ============================================================================
CREATE TABLE IF NOT EXISTS log.close_override_log (
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,
    log_type                shared.log_type_d NOT NULL DEFAULT 'business',
    activity_type           text        NOT NULL,
    book_code               text,
    fiscal_year             smallint,
    period_number           smallint,
    override_id             uuid,
    run_id                  uuid,
    event_type              text,
    from_status             text,
    to_status               text,
    actor_id                uuid        NOT NULL,
    actor_type              text,
    company_code_id         uuid,
    reason                  text,
    evidence                jsonb,
    correlation_id          uuid,
    payload                 jsonb,
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    CONSTRAINT col_pkey         PRIMARY KEY (id),
    CONSTRAINT col_activity_chk CHECK (activity_type IN ('close_override', 'book_close_audit'))
);
COMMENT ON TABLE log.close_override_log IS 'Period-close override + book close audit. activity_type=book_close_audit rows carry from_status/to_status. Absorbs log.book_close_audit_log.';


-- ============================================================================
-- §11  job_log  (absorbs completed rows from log.job_run)
-- ============================================================================
CREATE TABLE IF NOT EXISTS log.job_log (
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,
    log_type                text        NOT NULL
                            GENERATED ALWAYS AS ('system') STORED,
    job_type                text,
    flow_id                 uuid,
    run_id                  uuid,
    step_index              smallint,
    step_type               text,
    status                  text        NOT NULL,
    input                   jsonb,
    output                  jsonb,
    error                   text,
    duration_ms             integer,
    started_at              timestamptz,
    completed_at            timestamptz,
    attempt_no              smallint    NOT NULL DEFAULT 1,
    purge_after             timestamptz,
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    CONSTRAINT jl_pkey          PRIMARY KEY (id),
    CONSTRAINT jl_status_chk    CHECK (status IN ('success', 'failed', 'cancelled', 'timeout', 'skipped')),
    CONSTRAINT jl_duration_chk  CHECK (duration_ms IS NULL OR duration_ms >= 0),
    CONSTRAINT jl_attempt_chk   CHECK (attempt_no >= 1)
);
COMMENT ON TABLE log.job_log IS 'Job step + run completion history. Active jobs in event.outbox. On completion/failure: write summary here + mark outbox completed.';


-- ============================================================================
-- §12  policy_evaluation_log
-- ============================================================================
CREATE TABLE IF NOT EXISTS log.policy_evaluation_log (
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,
    log_type                text        NOT NULL
                            GENERATED ALWAYS AS ('system') STORED,
    txn_id                  uuid,
    pipeline_id             uuid,
    module_id               uuid,
    module_version          text,
    config_hash             text,
    score                   numeric(5,4),
    action                  text,
    conditions              jsonb,
    approvers               jsonb,
    sla_hours               smallint,
    explanation             text,
    confidence              numeric(5,4),
    evaluation_ms           integer,
    evaluated_at            timestamptz NOT NULL DEFAULT now(),
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    CONSTRAINT pel_pkey      PRIMARY KEY (id),
    CONSTRAINT pel_score_chk CHECK (score IS NULL OR score BETWEEN 0 AND 1),
    CONSTRAINT pel_conf_chk  CHECK (confidence IS NULL OR confidence BETWEEN 0 AND 1)
);
COMMENT ON TABLE log.policy_evaluation_log IS 'Policy engine scoring record. score and confidence are 0.0–1.0 fractions.';


-- ============================================================================
-- §13  hash_anchor
-- ============================================================================
CREATE TABLE IF NOT EXISTS log.hash_anchor (
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,
    log_type                text        NOT NULL
                            GENERATED ALWAYS AS ('system') STORED,
    anchor_date             date        NOT NULL,
    last_hash               text        NOT NULL,
    event_count             bigint      NOT NULL DEFAULT 0,
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    CONSTRAINT ha_pkey      PRIMARY KEY (id),
    CONSTRAINT ha_date_uq   UNIQUE (tenant_id, anchor_date),
    CONSTRAINT ha_hash_chk  CHECK (btrim(last_hash) <> ''),
    CONSTRAINT ha_count_chk CHECK (event_count >= 0)
);
COMMENT ON TABLE log.hash_anchor IS 'Daily tamper-evidence anchors. One row per (tenant, anchor_date). last_hash = SHA-256 of previous anchor + all events of the day.';


-- ============================================================================
-- §14  dimension_resolution_log
-- ============================================================================
CREATE TABLE IF NOT EXISTS log.dimension_resolution_log (
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,
    log_type                text        NOT NULL
                            GENERATED ALWAYS AS ('system') STORED,
    entity_type             text,
    entity_id               uuid,
    dimension_type_id       uuid,
    resolved_value_id       uuid,
    resolution_strategy     text,
    resolution_detail       jsonb,
    is_fallback             boolean     NOT NULL DEFAULT false,
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    CONSTRAINT drl_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE log.dimension_resolution_log IS 'Dimension resolution trace. Records how each value was determined (direct, inherited, default, fallback).';


-- ============================================================================
-- §15  activity_log  (replaces 9 tables)
-- ============================================================================
-- Replaces: kpi_activity, pack_activity, pack_release_activity, planning_activity,
--           close_override_activity, approval_event, comment_read,
--           comment_response, recent_activity.
-- domain + activity_type — extensible lookup triggers.
-- detail jsonb absorbs all domain-specific FK columns.

CREATE TABLE IF NOT EXISTS log.activity_log (
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,
    log_type                shared.log_type_d NOT NULL DEFAULT 'business',
    -- Discriminators — both lookup-validated (extensible)
    domain                  text        NOT NULL,
    activity_type           text        NOT NULL,
    -- Subject
    entity_type             text,
    entity_id               uuid,
    -- Actor
    actor_id                uuid,
    actor_type              text,
    company_code_id         uuid,
    -- Domain-specific FKs and data — absorbed into detail jsonb
    -- kpi   — {kpi_id, execution_id, calculation_run_id, fiscal_year, period_number}
    -- pack  — {pack_instance_id}
    -- release — {release_id}
    -- planning — {model_id, driver_id, formula_id}
    -- close — {override_id, run_id}
    -- approval — {approval_instance_id}
    -- user  — {comment_id, parent_comment_id, entity_name}
    detail                  jsonb,
    correlation_id          uuid,
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    CONSTRAINT al_pkey      PRIMARY KEY (id, created_at),
    CONSTRAINT al_dom_chk   CHECK (btrim(domain) <> ''),
    CONSTRAINT al_act_chk   CHECK (btrim(activity_type) <> '')
    -- domain:        09_triggers — control.trg_validate_lookup_columns('log.activity_domain')
    -- activity_type: 09_triggers — control.trg_validate_lookup_columns('log.activity_type')
) PARTITION BY RANGE (created_at);
COMMENT ON TABLE  log.activity_log IS
    'Consolidated domain activity log. Replaces 9 thin tables: kpi_activity, pack_activity, '
    'pack_release_activity, planning_activity, close_override_activity, approval_event, '
    'comment_read, comment_response, recent_activity. '
    'domain + activity_type controlled via control.lookup_domain (both extensible). '
    'All domain-specific FKs live in detail jsonb.';
COMMENT ON COLUMN log.activity_log.domain IS 'Activity domain. Lookup: log.activity_domain (is_extensible=true).';
COMMENT ON COLUMN log.activity_log.activity_type IS 'Activity type within domain. Lookup: log.activity_type (is_extensible=true).';
COMMENT ON COLUMN log.activity_log.detail IS
    'Domain-specific payload. kpi={kpi_id,execution_id,calculation_run_id,fiscal_year,period_number}, '
    'pack={pack_instance_id}, release={release_id}, planning={model_id,driver_id,formula_id}, '
    'approval={approval_instance_id}, user={comment_id,parent_comment_id,entity_name}.';
CREATE TABLE IF NOT EXISTS log.activity_log_default PARTITION OF log.activity_log DEFAULT;


-- ============================================================================
-- §16  close_activity_log  (replaces 5 finance close tables)
-- ============================================================================
-- Replaces: close_automation_audit, close_task_duration_history,
--           period_close_activity, release_decision_log, remediation_preview_log.
-- activity_type — lookup trigger (non-extensible — sealed close vocabulary).
-- close_period_id FK deferred to Phase 4 (ledger schema dependency).

CREATE TABLE IF NOT EXISTS log.close_activity_log (
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,
    log_type                shared.log_type_d NOT NULL DEFAULT 'business',
    activity_type           text        NOT NULL,
    fiscal_year             smallint,
    period_number           smallint,
    close_period_id         uuid,
    actor_id                uuid,
    actor_type              text,
    company_code_id         uuid,
    -- automation_audit — {automation_rule_id, policy_id, verdict, gate_evidence, execution_result}
    -- task_duration    — {task_id, task_code, started_at, completed_at, duration_minutes, close_type}
    -- period_close     — {close_step, step_status}
    -- release_decision — {release_id, certification_id, distribution_id, result, publication_batch_id}
    -- remediation_preview — {action_id, campaign_id, impact_summary, blocking_reasons}
    detail                  jsonb,
    outcome                 text,
    outcome_detail          text,
    correlation_id          uuid,
    payload                 jsonb,
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    CONSTRAINT cal_pkey         PRIMARY KEY (id)
    -- activity_type: 09_triggers — control.trg_validate_lookup_columns('log.close_activity_type')
);
COMMENT ON TABLE  log.close_activity_log IS
    'Finance close activity log. Replaces 5 tables: close_automation_audit, '
    'close_task_duration_history, period_close_activity, release_decision_log, '
    'remediation_preview_log. activity_type in log.close_activity_type lookup. '
    'close_period_id FK added in Phase 4 once ledger.close_period exists.';
COMMENT ON COLUMN log.close_activity_log.detail IS
    'Type-specific payload. automation_audit={automation_rule_id,policy_id,verdict,gate_evidence}, '
    'task_duration={task_id,task_code,started_at,completed_at,duration_minutes}, '
    'period_close={close_step,step_status}, '
    'release_decision={release_id,certification_id,distribution_id,result}, '
    'remediation_preview={action_id,campaign_id,impact_summary,blocking_reasons}.';


-- ============================================================================
-- §17  export_log  (replaces 3 export/download tables)
-- ============================================================================
-- Replaces: release_export_log, statement_export_log, pack_download_log.
-- export_type — lookup trigger (extensible — new export types added without DDL).

CREATE TABLE IF NOT EXISTS log.export_log (
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,
    log_type                shared.log_type_d NOT NULL DEFAULT 'business',
    export_type             text        NOT NULL,
    entity_type             text,
    entity_id               uuid,
    actor_id                uuid        NOT NULL,
    company_code_id         uuid,
    export_format           text,
    file_name               text,
    file_size_bytes         bigint,
    content_hash            text,
    hash_algorithm          text,
    ip_address              inet,
    user_agent              text,
    -- release — {release_id, certification_id, distribution_id, included_sections,
    --            release_status_at_export, is_clean_close_at_export,
    --            override_count_at_export, is_integrity_valid_at_export, export_version}
    -- statement — {instance_id, period_id, statement_type}
    -- pack_download — {distribution_id, format}
    detail                  jsonb,
    correlation_id          uuid,
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    CONSTRAINT el_pkey  PRIMARY KEY (id)
    -- export_type: 09_triggers — control.trg_validate_lookup_columns('log.export_type')
);
COMMENT ON TABLE  log.export_log IS
    'Consolidated export/download audit. Replaces: release_export_log, statement_export_log, '
    'pack_download_log. export_type in log.export_type lookup (extensible). '
    'detail carries type-specific fields.';
COMMENT ON COLUMN log.export_log.detail IS
    'release={release_id,certification_id,is_clean_close_at_export,export_version}, '
    'statement={instance_id,period_id,statement_type}, '
    'pack_download={distribution_id,format}.';


-- ============================================================================
