    created_by              uuid        NOT NULL,
    CONSTRAINT aml_pkey         PRIMARY KEY (id),
    CONSTRAINT aml_mon_chk      CHECK (monitor_type IN ('drift', 'anomaly_baseline')),
    CONSTRAINT aml_metric_chk   CHECK (btrim(metric_name) <> '')
