    CONSTRAINT act_pkey     PRIMARY KEY (id, created_at),
    CONSTRAINT act_sess_chk CHECK (btrim(session_id) <> ''),
    CONSTRAINT act_conf_chk CHECK (confidence IS NULL OR confidence BETWEEN 0 AND 1),
    CONSTRAINT act_dur_chk  CHECK (duration_seconds IS NULL OR duration_seconds >= 0)
) PARTITION BY RANGE (created_at);
COMMENT ON TABLE log.ai_call_transcript IS 'AI voice call transcripts. Reclassified from user-activity to AI domain. Partitioned monthly.';
CREATE TABLE IF NOT EXISTS log.ai_call_transcript_default PARTITION OF log.ai_call_transcript DEFAULT;


-- ============================================================================
-- §25  kpi_execution_log
-- ============================================================================
-- Stays separate from activity_log — financial columns (value, variance_amount,
-- formula_inputs) require direct SQL aggregation, not JSONB extraction.

CREATE TABLE IF NOT EXISTS log.kpi_execution_log (
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,
    log_type                text        NOT NULL DEFAULT 'business',
    kpi_id                  uuid        NOT NULL,
    kpi_version             smallint,
    company_code_id         uuid,
    fiscal_year             smallint    NOT NULL,
    period_number           smallint    NOT NULL,
    dimension_set_id        uuid,
    book_code               text        NOT NULL DEFAULT 'STAT',
    value                   numeric(18,4) NOT NULL,
    comparison_value        numeric(18,4),
    variance_amount         numeric(18,4),
    variance_pct            numeric(8,4),
    threshold_severity      text,
    formula_inputs          jsonb,
    definition_snapshot     jsonb,
    calculation_run_id      uuid,
    execution_job_id        uuid,
    trigger_source          text,
    is_current              boolean     NOT NULL DEFAULT true,
    consumer_state          text        NOT NULL DEFAULT 'calculated',
    published_to_pack_id    uuid,
    publication_batch_id    uuid,
    correlation_id          uuid,
    period_status_at_calc   text,
    calculated_at           timestamptz NOT NULL DEFAULT now(),
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    CONSTRAINT kel_pkey             PRIMARY KEY (id),
    CONSTRAINT kel_threshold_chk    CHECK (threshold_severity IS NULL OR threshold_severity IN (
        'ok', 'info', 'warning', 'critical'
    )),
    CONSTRAINT kel_consumer_chk     CHECK (consumer_state IN (
        'calculated', 'reviewed', 'approved', 'published'
    )),
    CONSTRAINT kel_trigger_chk      CHECK (trigger_source IS NULL OR trigger_source IN (
        'manual', 'scheduler', 'period_close', 'event', 'pack_refresh'
    ))
);
COMMENT ON TABLE  log.kpi_execution_log IS 'KPI calculation results. Kept separate from activity_log — financial columns need direct SQL aggregation. is_current flags latest calculation for (kpi_id, company_code_id, fiscal_year, period).';


-- ============================================================================
-- §26  workspace_usage_metric
-- ============================================================================
CREATE TABLE IF NOT EXISTS log.workspace_usage_metric (
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,
    log_type                text        NOT NULL
                            GENERATED ALWAYS AS ('system') STORED,
    workspace_id            uuid        NOT NULL,
    metric_key              text        NOT NULL,
    metric_name             text,
    metric_value            numeric,
    metric_unit             text,
    period_start            date        NOT NULL,
    period_end              date,
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    CONSTRAINT wum_pkey         PRIMARY KEY (id),
    CONSTRAINT wum_key_chk      CHECK (btrim(metric_key) <> ''),
    CONSTRAINT wum_period_chk   CHECK (period_end IS NULL OR period_end >= period_start)
);
COMMENT ON TABLE log.workspace_usage_metric IS 'Workspace usage telemetry. Feeds billing, quota enforcement, and capacity planning.';


-- ============================================================================
-- §27  notification_delivery_attempt — HTTP request/response trace
-- ============================================================================
-- Replaces log.delivery_log.
-- Append-only with a scoped UPDATE carve-out:
--   UPDATE of is_redacted, redaction_version, purge_after is allowed
--   (credential scrubbing workflow). All other columns are immutable.
-- One row per HTTP attempt — delivery may have many attempts.

CREATE TABLE IF NOT EXISTS log.notification_delivery_attempt (
    -- Identity
    id              uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid            NOT NULL,

    -- Origin
    delivery_id     uuid,
    subscription_id uuid,

    -- Request (immutable after insert)
    request_url     text            NOT NULL,
    request_method  text            NOT NULL DEFAULT 'POST',
    request_headers jsonb,
    request_body    text,
    request_content_type text,

    -- Response (immutable after insert)
    response_status integer,
    response_headers jsonb,
    response_body   text,
    response_content_type text,

    -- Outcome (immutable after insert)
    duration_ms     integer         NOT NULL,
    is_success      boolean         NOT NULL,
    error           text,

    -- Redaction (mutable — credential scrubbing post-insert)
    is_redacted     boolean         NOT NULL DEFAULT false,
    redaction_version text,
    body_truncated  boolean         NOT NULL DEFAULT false,

    -- Retention
    purge_after     timestamptz,

    -- Audit
    created_at      timestamptz     NOT NULL DEFAULT now(),
    created_by      uuid            NOT NULL,

    CONSTRAINT nda_pkey              PRIMARY KEY (id),
    CONSTRAINT nda_url_chk           CHECK (btrim(request_url) <> ''),
    CONSTRAINT nda_method_chk        CHECK (request_method IN (
        'GET', 'POST', 'PUT', 'PATCH', 'DELETE'
    )),
    CONSTRAINT nda_duration_chk      CHECK (duration_ms >= 0),
    CONSTRAINT nda_status_chk        CHECK (
        response_status IS NULL
        OR (response_status BETWEEN 100 AND 599)
    )
);

COMMENT ON TABLE  log.notification_delivery_attempt IS
    'HTTP request/response trace per delivery attempt. Replaces log.delivery_log. '
    'Append-only: DELETE blocked. UPDATE restricted to is_redacted, '
    'redaction_version, purge_after only (credential scrubbing workflow). '
    'Enforced by 09_triggers/008_log.sql.';
COMMENT ON COLUMN log.notification_delivery_attempt.is_redacted IS
    'Set true by credential-scrubbing worker after redacting sensitive headers/body.';
COMMENT ON COLUMN log.notification_delivery_attempt.purge_after IS
    'When set, the purge job hard-deletes this row. Allows GDPR-driven retention.';


-- =============================================================================
-- §28  DOCUMENT · PRINT · BRANDING  —  log.render_dlq
-- =============================================================================
-- Dead-letter queue for permanently failed render attempts.
-- Append-focused — rows are written on failure and replayed on recovery.

CREATE TABLE IF NOT EXISTS log.render_dlq (
    -- Identity
    id              uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid        NOT NULL,

    -- Source references
    output_id       uuid        NOT NULL,
    render_job_id   uuid,

    -- Error classification
    error_code      text        NOT NULL,
    error_detail    text,
    error_category  text        NOT NULL,

    -- Attempt tracking
    attempt_count   integer     NOT NULL DEFAULT 0,
    payload         jsonb       NOT NULL DEFAULT '{}'::jsonb,

    -- Replay tracking
    replayed_at     timestamptz,
    replayed_by     uuid,
    replay_count    integer     NOT NULL DEFAULT 0,
    dead_at         timestamptz NOT NULL DEFAULT now(),

    -- Audit
    created_at      timestamptz NOT NULL DEFAULT now(),
    created_by      uuid        NOT NULL DEFAULT '00000000-0000-0000-0000-000000000000',
    updated_at      timestamptz,
    updated_by      uuid,

    CONSTRAINT render_dlq_pkey              PRIMARY KEY (id),
    CONSTRAINT render_dlq_category_chk      CHECK (error_category IN (
        'transient', 'permanent', 'timeout', 'crash'
    )),
    CONSTRAINT render_dlq_error_code_chk    CHECK (btrim(error_code) <> ''),
    CONSTRAINT render_dlq_attempts_pos      CHECK (attempt_count >= 0),
    CONSTRAINT render_dlq_replay_pos        CHECK (replay_count >= 0)
);

COMMENT ON TABLE log.render_dlq IS
    'Dead-letter queue for permanently failed render attempts. '
    'EXCEPTION CLASS: queue_operational — lives in log schema but is mutable '
    '(replay updates status). Has updated_at/updated_by unlike append-only log tables. '
    'Not partitioned — operational table with low row volume.';
COMMENT ON COLUMN log.render_dlq.updated_at IS
    'Set on replay (status change). Auto-populated by trg_render_dlq_updated_at.';
COMMENT ON COLUMN log.render_dlq.updated_by IS
    'Principal who triggered the replay.';


-- ============================================================================
-- §CAL  log.cycle_audit_log — governance cycle unified audit trail
-- ============================================================================
-- Append-only, partitioned by created_at. pg_partman manages monthly children.
-- Immutability enforced by RLS (no UPDATE/DELETE policies for tenant role).

CREATE TABLE IF NOT EXISTS log.cycle_audit_log (
    -- Identity
    id              uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid        NOT NULL,

    -- Context
    company_code_id uuid,
    cycle_type_code varchar(30),
    domain          varchar(20) NOT NULL,
    event_type      varchar(40) NOT NULL,

    -- References
    cycle_run_id    uuid,
    target_id       uuid,
    target_type     varchar(30),

    -- Actor
    actor_id        uuid,
    actor_type      varchar(20) NOT NULL DEFAULT 'USER',

    -- State transition
    from_status     varchar(30),
    to_status       varchar(30),

    -- Payload
    payload         jsonb       NOT NULL DEFAULT '{}'::jsonb,
    reason          text,

    -- Audit
    created_at      timestamptz NOT NULL DEFAULT now(),
    created_by      uuid        NOT NULL DEFAULT '00000000-0000-0000-0000-000000000000',

    CONSTRAINT cycle_audit_log_pkey PRIMARY KEY (id, created_at),
    CONSTRAINT cal_domain_chk       CHECK (domain IN ('RUN','TASK','DEVIATION','CERTIFICATION','CROSS_DEP')),
    CONSTRAINT cal_actor_chk        CHECK (actor_type IN ('USER','SYSTEM','SCHEDULER'))
) PARTITION BY RANGE (created_at);

CREATE TABLE IF NOT EXISTS log.cycle_audit_log_default
    PARTITION OF log.cycle_audit_log DEFAULT;

COMMENT ON TABLE log.cycle_audit_log IS
    'Unified immutable audit trail for the governance cycle model. '
    'Partitioned monthly by created_at. Append-only — no UPDATE/DELETE '
    'policies for tenant role. pg_partman manages monthly children.';
COMMENT ON COLUMN log.cycle_audit_log.created_by IS
    'Session principal who inserted this log entry. Distinct from actor_id '
    'which represents the business-domain actor (may differ for system-initiated events).';
COMMENT ON COLUMN log.cycle_audit_log.actor_id IS
    'Business-domain actor who triggered the event. May be NULL for '
    'system-initiated events (e.g. scheduler). Distinct from created_by.';

-- ============================================================================
-- Engine 4.13: Unified Transaction Resolution Engine additions
-- ============================================================================

-- §14  resolution_log — unified audit trail (3 rows per txn: CONTEXT / INTENT / PROFILE)
--      Append-only: immutability trigger in 09_triggers prevents UPDATE and DELETE.
CREATE TABLE IF NOT EXISTS log.resolution_log (
    -- Identity
    id                          uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id                   uuid        NOT NULL,
    pipeline_id                 uuid        NOT NULL,
    txn_id                      uuid        NOT NULL,
    resolution_step             text        NOT NULL,

    -- Transaction context
    direction                   text        NOT NULL,
    flow_code                   text,
    company_code_id             uuid,
    doc_type                    text,
    amount                      numeric(18,4),
    currency_code               text,
    is_cross_border             boolean,
    is_intercompany             boolean,
    counterparty_type           text,

    -- Resolution result
    confidence                  numeric(3,2),
    resolution_method           text,
    explanation                 text,
    matched_rule_id             uuid,
    matched_override_id         uuid,
    rules_evaluated             smallint,
    evaluation_ms               integer,

    -- Override tracking
    was_overridden              boolean     NOT NULL DEFAULT false,
    override_by                 uuid,
    override_reason             text,
    original_resolved_id        uuid,

    -- Intent-specific (INTENT step)
    classification_source       text,
    classification_id           uuid,
    resolved_intent_id          uuid,
    resolved_domain             text,

    -- Profile-specific (PROFILE step)
    resolved_profile_config_id  uuid,
    resolved_profile_code       text,
    subledger_type              text,
    profile_type                text,
    profile_version             integer,
    event_count                 smallint,
    entry_template_count        smallint,
    book_rule_count             smallint,
    creates_commitment          boolean,
    has_paired_profile          boolean,

    -- Timing (log tables use created_at; resolved_at is domain-specific)
    resolved_at                 timestamptz NOT NULL DEFAULT now(),
    created_at                  timestamptz NOT NULL DEFAULT now(),
    created_by                  uuid        NOT NULL,

    CONSTRAINT rl_pkey           PRIMARY KEY (id),
    CONSTRAINT rl_step_chk       CHECK (resolution_step IN ('CONTEXT','INTENT','PROFILE')),
    CONSTRAINT rl_confidence_chk CHECK (confidence IS NULL OR confidence BETWEEN 0 AND 1)
);

COMMENT ON TABLE log.resolution_log IS
    'Engine 4.13: unified resolution audit trail. '
    '3 rows per transaction: CONTEXT (input snapshot), INTENT (Step 4), PROFILE (Step 4.5). '
    'Append-only: immutability trigger prevents UPDATE and DELETE. '
    'Partial indexes in 07_indexes for step-specific queries.';


-- =============================================================================
-- §DLQ  Dead-letter queues — Phase 3.3 WorkerFramework
-- =============================================================================
-- One DLQ table per subsystem. All three share the same column set so the
-- common insertDlq() helper can target any of them.
-- Rows are inserted on job failure (after all BullMQ retries exhausted).
-- retried_at + retried_job_id populated by retryFromDlq().

-- §DLQ-1  log.audit_dlq
CREATE TABLE IF NOT EXISTS log.audit_dlq (
    id                  uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id           uuid        NOT NULL,
    queue_name          text        NOT NULL,
    job_name            text        NOT NULL,
    payload             jsonb       NOT NULL,
    error_message       text        NOT NULL,
    retry_count         smallint    NOT NULL DEFAULT 0,
    last_attempted_at   timestamptz NOT NULL,
    retried_at          timestamptz,
    retried_job_id      text,
    created_at          timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT audit_dlq_pkey       PRIMARY KEY (id),
    CONSTRAINT audit_dlq_payload_chk CHECK (jsonb_typeof(payload) = 'object')
);

COMMENT ON TABLE log.audit_dlq IS
    'Dead-letter queue for failed audit-domain background jobs. '
    'Phase 3.3 WorkerFramework. insertDlq() target: ''log.audit_dlq''. '
    'retried_at/retried_job_id set by retryFromDlq().';

-- §DLQ-2  log.notification_dlq
CREATE TABLE IF NOT EXISTS log.notification_dlq (
    id                  uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id           uuid        NOT NULL,
    queue_name          text        NOT NULL,
    job_name            text        NOT NULL,
    payload             jsonb       NOT NULL,
    error_message       text        NOT NULL,
    retry_count         smallint    NOT NULL DEFAULT 0,
    last_attempted_at   timestamptz NOT NULL,
    retried_at          timestamptz,
    retried_job_id      text,
    created_at          timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT notification_dlq_pkey       PRIMARY KEY (id),
    CONSTRAINT notification_dlq_payload_chk CHECK (jsonb_typeof(payload) = 'object')
);

COMMENT ON TABLE log.notification_dlq IS
    'Dead-letter queue for failed notification-domain background jobs. '
    'Phase 3.3 WorkerFramework. insertDlq() target: ''log.notification_dlq''.';

-- §DLQ-3  log.render_dlq
CREATE TABLE IF NOT EXISTS log.render_dlq (
    id                  uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id           uuid        NOT NULL,
    queue_name          text        NOT NULL,
    job_name            text        NOT NULL,
    payload             jsonb       NOT NULL,
    error_message       text        NOT NULL,
    retry_count         smallint    NOT NULL DEFAULT 0,
    last_attempted_at   timestamptz NOT NULL,
    retried_at          timestamptz,
    retried_job_id      text,
    created_at          timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT render_dlq_pkey       PRIMARY KEY (id),
    CONSTRAINT render_dlq_payload_chk CHECK (jsonb_typeof(payload) = 'object')
);

COMMENT ON TABLE log.render_dlq IS
    'Dead-letter queue for failed render/PDF-domain background jobs. '
    'Phase 3.3 WorkerFramework. insertDlq() target: ''log.render_dlq''. '
    'PDF generation failures logged here after all BullMQ retries exhausted.';

-- FILE: /d/Products/athyper/server/db/sql/04_tables/007_event.sql
-- 04_tables/007_event.sql
-- Depends on: 01_schemas, 02_types_domains
-- Event and integration hub schema tables.
-- Column order: Identity → Table-specific → Metadata → Lifecycle → Audit.
--
-- Tables:
--   §1  event.outbox                    — unified transactional outbox
--   §2  event.notification_message      — notification dispatch envelope
--   §3  event.notification_delivery     — per-channel delivery record (partitioned)
--   §4  event.digest_staging            — pending digest items (work queue)
--   §5  event.endpoint                  — integration endpoint registry
--   §6  event.webhook_subscription      — per-tenant webhook subscriptions
--   §7  event.comment_flag              — user-submitted abuse report
--   §8  event.lifecycle_timer_schedule  — active timer work queue
--   §9  event.work_item                 — individual human task

-- ============================================================================
-- §1  outbox — unified transactional outbox (replaces core.outbox)
-- ============================================================================
-- Single outbox table for all event-driven processing. Workers filter by topic.
-- Supports: IAM/KC sync, workflow webhooks, audit drain, finance domain events.
-- Pattern: transactional outbox with claim-based polling (FOR UPDATE SKIP LOCKED).

CREATE TABLE IF NOT EXISTS event.outbox (
    -- Identity
    id              uuid              NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid              NOT NULL,

    -- Table-specific (event classification)
    topic           text              NOT NULL,
    event_type      text,
    event_key       text,

    -- Table-specific (event context — optional, used by some consumers)
    entity_type     text,
    entity_id       uuid,
    aggregate_id    uuid,
    aggregate_type  text,
    actor_id        uuid,
    source          text,
    correlation_id  uuid,

    -- Table-specific (payload)
    payload         jsonb             NOT NULL DEFAULT '{}'::jsonb,

    -- Table-specific (processing state)
    status          text              NOT NULL DEFAULT 'pending',
    attempts        integer           NOT NULL DEFAULT 0,
    max_attempts    integer           NOT NULL DEFAULT 5,
    available_at    timestamptz       NOT NULL DEFAULT now(),
    locked_at       timestamptz,
    locked_by       text,
    locked_until    timestamptz,
    last_error      text,
    processed_at    timestamptz,

    -- Audit
    created_at      timestamptz       NOT NULL DEFAULT now(),
    created_by      uuid              NOT NULL,

    CONSTRAINT outbox_pkey            PRIMARY KEY (id),
    CONSTRAINT outbox_topic_chk       CHECK (btrim(topic) <> ''),
    CONSTRAINT outbox_status_chk      CHECK (status IN (
        'pending', 'processing', 'completed', 'failed', 'dead_letter'
    )),
    CONSTRAINT outbox_attempts_chk    CHECK (attempts >= 0),
    CONSTRAINT outbox_max_attempts_chk CHECK (max_attempts > 0),
    CONSTRAINT outbox_locked_chk      CHECK (
        (locked_at IS NULL AND locked_by IS NULL AND locked_until IS NULL)
        OR (locked_at IS NOT NULL AND locked_by IS NOT NULL AND locked_until IS NOT NULL)
    )
);

COMMENT ON TABLE event.outbox IS
  'Unified transactional outbox. All event-driven consumers share this table, '
  'filtered by topic. Topics: iam (KC sync), wf (webhooks), audit (drain), fin (domain events). '
  'Workers claim batches via FOR UPDATE SKIP LOCKED on available_at.';

COMMENT ON COLUMN event.outbox.topic IS
  'Consumer discriminator. Each worker polls only its topic. '
  'Convention: lowercase namespace (iam, wf, audit, fin).';
COMMENT ON COLUMN event.outbox.event_type IS
  'Specific event within the topic. E.g. topic=iam, event_type=group_membership.';
COMMENT ON COLUMN event.outbox.event_key IS
  'Optional idempotency/dedup key. Workers may use for exactly-once semantics.';
COMMENT ON COLUMN event.outbox.available_at IS
  'Earliest time this event can be claimed. Used for retry backoff scheduling.';
COMMENT ON COLUMN event.outbox.locked_by IS
  'Worker instance ID that claimed this event. NULL when not processing.';


-- ============================================================================
-- §2  notification_message — dispatch envelope
-- ============================================================================
-- One row per triggered routing_rule evaluation.
-- Has status lifecycle: pending → planning → delivering → completed/partial/failed.
-- Counts (recipient_count, delivered_count, failed_count) updated by delivery worker.

CREATE TABLE IF NOT EXISTS event.notification_message (
    -- Identity
    id              uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid            NOT NULL,

    -- Trigger context
    event_id        text            NOT NULL,
    event_code      text            NOT NULL,
    rule_id         uuid,
    entity_type     text,
    entity_id       uuid,

    -- Template reference (snapshot at dispatch time)
    template_key    text            NOT NULL,
    template_version smallint       NOT NULL,
    subject         text,
    payload         jsonb           NOT NULL DEFAULT '{}',

    -- Dispatch config
    priority        text            NOT NULL DEFAULT 'normal',
    channels        text[],

    -- Counters (updated by delivery worker)
    recipient_count integer         NOT NULL DEFAULT 0,
    delivered_count integer         NOT NULL DEFAULT 0,
    failed_count    integer         NOT NULL DEFAULT 0,

    -- Lifecycle
    status          text            NOT NULL DEFAULT 'pending',
    expires_at      timestamptz,
    completed_at    timestamptz,

    -- Traceability
    correlation_id  uuid,
    metadata        jsonb           NOT NULL DEFAULT '{}',

    -- Audit
    created_at      timestamptz     NOT NULL DEFAULT now(),
    created_by      uuid            NOT NULL,
    updated_at      timestamptz,
    updated_by      uuid,

    CONSTRAINT nmsg_pkey             PRIMARY KEY (id),
    CONSTRAINT nmsg_event_chk        CHECK (btrim(event_id) <> ''),
    CONSTRAINT nmsg_template_chk     CHECK (btrim(template_key) <> ''),
    CONSTRAINT nmsg_version_chk      CHECK (template_version >= 1),
    CONSTRAINT nmsg_counts_chk       CHECK (
        recipient_count >= 0
        AND delivered_count >= 0
        AND failed_count >= 0
        AND delivered_count + failed_count <= recipient_count
    ),
    CONSTRAINT nmsg_status_chk       CHECK (status IN (
        'pending', 'planning', 'delivering', 'completed', 'partial', 'failed'
    )),
    CONSTRAINT nmsg_expiry_chk       CHECK (expires_at IS NULL OR expires_at > created_at)
    -- priority: 09_triggers — control.trg_validate_lookup_columns('notification.priority')
);

COMMENT ON TABLE  event.notification_message IS
    'Notification dispatch envelope. One row per routing_rule evaluation. '
    'status lifecycle: pending → planning → delivering → completed/partial/failed. '
    'Counters (recipient_count, delivered_count, failed_count) maintained by '
    'delivery worker. priority via notification.priority lookup.';
COMMENT ON COLUMN event.notification_message.event_id IS
    'Originating event identifier (from event.outbox.id or external event source).';
COMMENT ON COLUMN event.notification_message.payload IS
    'Template variable data used to render the message body at dispatch time.';


-- ============================================================================
-- §3  notification_delivery — per-channel delivery record
-- ============================================================================
-- One row per (message_id, recipient_id, channel) delivery attempt batch.
-- Mutable: status, attempt_count, retry timestamps updated by delivery worker.
-- Partitioned monthly — very high volume.
--
-- Absorbs:
--   log.message_delivery  → read_at column added here
--   log.sms_log           → SMS-specific fields in channel_detail jsonb
--   log.webhook_event     → completed/failed rows only (active → event.outbox)

CREATE TABLE IF NOT EXISTS event.notification_delivery (
    -- Identity
    id              uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid            NOT NULL,

    -- Origin
    message_id      uuid            NOT NULL,
    notification_id uuid,

    -- Recipient
    recipient_id    uuid,
    recipient_addr  text            NOT NULL,

    -- Channel
    channel         text            NOT NULL,
    provider_id     uuid,
    provider_code   text,

    -- Delivery state (mutable — updated by delivery worker)
    status          text            NOT NULL DEFAULT 'pending',
    attempt_count   smallint        NOT NULL DEFAULT 0,
    max_attempts    smallint        NOT NULL DEFAULT 3,
    last_error      text,
    error_category  text,

    -- External tracking
    external_id     text,
    idempotency_key text,
    subscription_id uuid,

    -- Timestamps
    sent_at         timestamptz,
    delivered_at    timestamptz,
    read_at         timestamptz,
    opened_at       timestamptz,
    clicked_at      timestamptz,
    bounced_at      timestamptz,
    next_retry_at   timestamptz,
    locked_until    timestamptz,

    -- Channel-specific overflow
    -- sms     → {direction, from_number, to_number, message_ref, crm_entity_type}
    -- webhook → {event_type, response_status, payload_hash}
    -- email   → {from_addr, reply_to, headers}
    channel_detail  jsonb,

    -- Metadata
    metadata        jsonb           NOT NULL DEFAULT '{}',

    -- Audit
    created_at      timestamptz     NOT NULL DEFAULT now(),
    created_by      uuid            NOT NULL,
    updated_at      timestamptz,
    updated_by      uuid,

    CONSTRAINT ndlv_pkey             PRIMARY KEY (id, created_at),
    CONSTRAINT ndlv_addr_chk         CHECK (btrim(recipient_addr) <> ''),
    CONSTRAINT ndlv_status_chk       CHECK (status IN (
        'pending', 'queued', 'sent', 'delivered',
        'bounced', 'failed', 'cancelled'
    )),
    CONSTRAINT ndlv_error_cat_chk    CHECK (error_category IS NULL OR error_category IN (
        'transient', 'permanent', 'rate_limit', 'auth'
    )),
    CONSTRAINT ndlv_attempts_chk     CHECK (
        attempt_count >= 0
        AND max_attempts > 0
        AND attempt_count <= max_attempts
    )
    -- channel: 09_triggers — control.trg_validate_lookup_columns('notification.channel')
) PARTITION BY RANGE (created_at);

COMMENT ON TABLE  event.notification_delivery IS
    'Per-channel delivery record. One row per (message, recipient, channel) attempt. '
    'Mutable — delivery worker updates status, attempt_count, timestamps. '
    'Absorbs: log.message_delivery (read_at added), log.sms_log (→ channel_detail), '
    'log.webhook_event completed rows. Partitioned monthly.';
COMMENT ON COLUMN event.notification_delivery.channel_detail IS
    'Channel-specific fields not in the core schema. '
    'sms→{direction,from_number,to_number,message_ref,crm_entity_type,crm_entity_id}, '
    'webhook→{event_type,response_status,payload_hash}, '
    'email→{from_addr,reply_to,message_id_header}.';
COMMENT ON COLUMN event.notification_delivery.subscription_id IS
    'For webhook deliveries: FK to the webhook subscription that triggered this row.';

-- Monthly partitions — create ahead of time via cron or migration script:
--   CREATE TABLE event.notification_delivery_2026_04
--       PARTITION OF event.notification_delivery
--       FOR VALUES FROM ('2026-04-01') TO ('2026-05-01');
-- The DEFAULT partition catches any rows outside defined ranges.
CREATE TABLE IF NOT EXISTS event.notification_delivery_default
    PARTITION OF event.notification_delivery DEFAULT;


-- ============================================================================
-- §4  digest_staging — pending digest items (work queue)
-- ============================================================================
-- Work table consumed by the digest assembly worker.
-- NOT a log — rows are deleted or marked delivered_at when batched.
-- One row per pending notification per recipient per (channel, frequency) window.

CREATE TABLE IF NOT EXISTS event.digest_staging (
    -- Identity
    id              uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid            NOT NULL,

    -- Target
    recipient_id    uuid            NOT NULL,
    channel         text            NOT NULL,
    frequency       text            NOT NULL,

    -- Source message
    message_id      uuid            NOT NULL,
    event_code      text            NOT NULL,
    subject         text,
    payload         jsonb           NOT NULL DEFAULT '{}',
    template_key    text            NOT NULL,
    priority        text            NOT NULL DEFAULT 'normal',

    -- Metadata
    metadata        jsonb           NOT NULL DEFAULT '{}',

    -- Lifecycle
    staged_at       timestamptz     NOT NULL DEFAULT now(),
    delivered_at    timestamptz,

    -- Audit
    created_at      timestamptz     NOT NULL DEFAULT now(),
    created_by      uuid            NOT NULL,

    CONSTRAINT ds_pkey              PRIMARY KEY (id),
    CONSTRAINT ds_event_chk         CHECK (btrim(event_code) <> ''),
    CONSTRAINT ds_template_chk      CHECK (btrim(template_key) <> '')
    -- channel:   09_triggers — control.trg_validate_lookup_columns('notification.channel')
    -- priority:  09_triggers — control.trg_validate_lookup_columns('notification.priority')
    -- frequency: 09_triggers — control.trg_validate_lookup_columns('notification.digest_frequency')
);

COMMENT ON TABLE  event.digest_staging IS
    'Pending digest items. Work queue consumed by the digest assembly worker. '
    'Rows marked delivered_at (or deleted) when batched into a digest message. '
    'channel, priority, frequency all lookup-validated. NOT a log — mutable work table.';
COMMENT ON COLUMN event.digest_staging.frequency IS
    'Digest aggregation window. Lookup: notification.digest_frequency. '
    'e.g. hourly_digest, daily_digest, weekly_digest.';


-- ============================================================================
-- §5  event.endpoint — integration endpoint registry
-- ============================================================================
-- Registered outbound integration targets. Each row is a named endpoint
-- that the platform can call (webhook target, external API, etc.).
-- Tenant-scoped: one tenant's endpoints are invisible to others.
-- config jsonb holds adapter-specific fields (base_url, headers, auth, timeout).
-- Sensitive values (API keys, secrets) must be encrypted at rest via
-- CredentialEncryptionService (Platform Migration Phase 1.7).
-- Consolidated from int.endpoint into event schema (no separate int schema).

CREATE TABLE IF NOT EXISTS event.endpoint (
    -- Identity
    id              uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid        NOT NULL,

    -- Classification
    service         text        NOT NULL,
    code            text        NOT NULL,
    name            text        NOT NULL,
    description     text,

    -- Target
    path            text        NOT NULL,
    method          text        NOT NULL DEFAULT 'POST',

    -- Config (adapter-specific: base_url, headers, auth, timeout_ms, retry_policy)
    -- auth object MUST be encrypted via CredentialEncryptionService before storage
    config          jsonb       NOT NULL DEFAULT '{}'::jsonb,

    -- Health
    health_check_url text,
    health          text        NOT NULL DEFAULT 'healthy',
    last_checked_at timestamptz,
    last_response_ms integer,

    -- Lifecycle
    is_active       boolean     NOT NULL DEFAULT true,

    -- Audit
    created_at      timestamptz NOT NULL DEFAULT now(),
    created_by      uuid        NOT NULL,
    updated_at      timestamptz,
    updated_by      uuid,

    CONSTRAINT endpoint_pkey        PRIMARY KEY (id),
    CONSTRAINT endpoint_tenant_uq   UNIQUE (tenant_id, id),
    CONSTRAINT endpoint_code_uq     UNIQUE (tenant_id, service, code),
    CONSTRAINT endpoint_method_chk  CHECK (method IN ('GET','POST','PUT','PATCH','DELETE')),
    CONSTRAINT endpoint_health_chk  CHECK (health IN ('healthy','degraded','down')),
    CONSTRAINT endpoint_path_chk    CHECK (btrim(path) <> ''),
    CONSTRAINT endpoint_service_chk CHECK (btrim(service) <> ''),
    CONSTRAINT endpoint_code_chk    CHECK (btrim(code) <> '')
);

COMMENT ON TABLE  event.endpoint IS
    'Outbound integration endpoint registry. One row per named target '
    '(webhook, external API, partner endpoint). config holds adapter-specific '
    'settings; config.auth MUST be encrypted at rest. '
    'Consolidated from int schema into event schema.';
COMMENT ON COLUMN event.endpoint.service IS
    'Logical service grouping (e.g. erp, payment_gateway, id_provider).';
COMMENT ON COLUMN event.endpoint.config IS
    'Adapter config: base_url, headers, auth (type + credentials), '
    'timeout_ms, retry_policy. config.auth encrypted via CredentialEncryptionService.';
COMMENT ON COLUMN event.endpoint.health IS
    'Last known health state. Updated by the integration health-check worker. '
    'healthy | degraded | down.';
COMMENT ON COLUMN event.endpoint.health_check_url IS
    'Optional URL probed via HTTP HEAD every 5 min by the endpoint-health worker. '
    'NULL = no automated health checking for this endpoint.';
COMMENT ON COLUMN event.endpoint.last_response_ms IS
    'HTTP response time (ms) from the most recent health probe. NULL if never checked.';

-- Schema evolution — safe to run against existing databases
ALTER TABLE event.endpoint ADD COLUMN IF NOT EXISTS health_check_url  text;
ALTER TABLE event.endpoint ADD COLUMN IF NOT EXISTS last_response_ms  integer;


-- ============================================================================
-- §6  event.webhook_subscription — per-tenant webhook target registrations
-- ============================================================================
-- Subscription record for outbound webhook delivery.
-- Each row declares: which event topics to forward, to what target URL,
-- and with what signing secret.
-- event.notification_delivery rows reference subscription_id for traceability.
-- Consolidated from int.webhook_subscription into event schema (no separate int schema).

CREATE TABLE IF NOT EXISTS event.webhook_subscription (
    -- Identity
    id              uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid        NOT NULL,

    -- Target
    target_url      text        NOT NULL,
    signing_secret  text,

    -- Subscription config
    topics          text[]      NOT NULL DEFAULT '{}',
    description     text,

    -- Delivery policy
    max_retries     smallint    NOT NULL DEFAULT 3,
    timeout_ms      integer     NOT NULL DEFAULT 10000,

    -- Health
    last_delivery_at     timestamptz,
    last_delivery_status text,
    failure_count        integer     NOT NULL DEFAULT 0,

    -- Lifecycle
    is_active       boolean     NOT NULL DEFAULT true,

    -- Audit
    created_at      timestamptz NOT NULL DEFAULT now(),
    created_by      uuid        NOT NULL,
    updated_at      timestamptz,
    updated_by      uuid,

    CONSTRAINT ws_pkey              PRIMARY KEY (id),
    CONSTRAINT ws_tenant_uq         UNIQUE (tenant_id, id),
    CONSTRAINT ws_url_chk           CHECK (btrim(target_url) <> ''),
    CONSTRAINT ws_timeout_chk       CHECK (timeout_ms > 0),
    CONSTRAINT ws_retries_chk       CHECK (max_retries >= 0),
    CONSTRAINT ws_failure_chk       CHECK (failure_count >= 0)
);

COMMENT ON TABLE  event.webhook_subscription IS
    'Per-tenant webhook subscription registry. Each row is a target URL '
    'that receives event.outbox payloads for the subscribed topics. '
    'event.notification_delivery.subscription_id references this table. '
    'Consolidated from int schema into event schema.';
COMMENT ON COLUMN event.webhook_subscription.signing_secret IS
    'HMAC-SHA256 signing secret for payload signature header. '
    'Store encrypted at rest via CredentialEncryptionService. NULL = unsigned delivery.';
COMMENT ON COLUMN event.webhook_subscription.topics IS
    'List of event.outbox topic values this subscription receives. '
    'Empty array = subscribe to all topics.';


-- ============================================================================
-- §7  event.comment_flag — user-submitted abuse report
-- ============================================================================
CREATE TABLE IF NOT EXISTS event.comment_flag (
    -- Identity
    id              uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid        NOT NULL,

    -- Subject (which comment was flagged)
    context_type    text        NOT NULL,
    comment_id      uuid        NOT NULL,

    -- Report
    flagged_by      uuid        NOT NULL,
    flag_reason     text        NOT NULL,
    note            text,

    -- Moderation response (mutable)
    status          text        NOT NULL DEFAULT 'pending',
    reviewed_by     uuid,
    reviewed_at     timestamptz,
    review_note     text,

    -- Audit
    created_at      timestamptz NOT NULL DEFAULT now(),
    created_by      uuid        NOT NULL,
    updated_at      timestamptz,
    updated_by      uuid,

    CONSTRAINT cf_pkey          PRIMARY KEY (id),
    CONSTRAINT cf_status_chk    CHECK (status IN (
        'pending', 'reviewed', 'dismissed', 'actioned'
    )),
    CONSTRAINT cf_review_chk    CHECK (
        (status = 'pending' AND reviewed_at IS NULL AND reviewed_by IS NULL)
        OR (status IN ('reviewed','dismissed','actioned')
            AND reviewed_at IS NOT NULL AND reviewed_by IS NOT NULL)
    ),
    -- review_note is required when actioned (moderator must explain decision)
    CONSTRAINT cf_actioned_note_chk CHECK (
        status <> 'actioned' OR review_note IS NOT NULL
    )
    -- context_type: 09_triggers — control.trg_validate_lookup_columns('master.comment_type')
    -- flag_reason:  09_triggers — control.trg_validate_lookup_columns('master.flag_reason')
);

COMMENT ON TABLE  event.comment_flag IS
    'User-submitted comment abuse report. Actionable event — demands moderation response. '
    'status lifecycle: pending — reviewed / dismissed / actioned. '
    'When actioned: governance.comment_moderation is_hidden is set true. '
    'context_type in master.comment_type. flag_reason in master.flag_reason (extensible).';
COMMENT ON COLUMN event.comment_flag.review_note IS
    'Moderator decision note. Required when status = actioned.';


-- =============================================================================
-- §8  event.lifecycle_timer_schedule — active timer work queue
-- =============================================================================
-- One row per scheduled timer event for an entity in a state.
-- Moved from control.* (backup) to event.* — it is an actionable work item.
-- L08: 'failed' status added.
-- L11: entity_id is TEXT (polymorphic — not always uuid).
-- policy_snapshot captures rules at schedule time (version-pinned).

CREATE TABLE IF NOT EXISTS event.lifecycle_timer_schedule (
    -- Identity
    id              uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid        NOT NULL,

    -- Subject (L11: entity_id = TEXT to match entity_lifecycle_instance)
    entity_name     text        NOT NULL,
    entity_id       text        NOT NULL,
    lifecycle_id    uuid        NOT NULL,
    state_id        uuid        NOT NULL,

    -- Timer definition
    timer_type      text        NOT NULL,
    transition_id   uuid,

    -- Schedule
    scheduled_at    timestamptz NOT NULL DEFAULT now(),
    fire_at         timestamptz NOT NULL,

    -- Execution
    job_id          text,
    policy_id       uuid,
    -- Version-pinned rules at schedule creation time
    policy_snapshot jsonb       NOT NULL DEFAULT '{}',

    -- Status (L08: 'failed' added)
    status          text        NOT NULL DEFAULT 'scheduled',

    -- Audit
    created_at      timestamptz NOT NULL DEFAULT now(),
    created_by      uuid        NOT NULL,
    updated_at      timestamptz,
    updated_by      uuid,

    CONSTRAINT lts_pkey             PRIMARY KEY (id),
    CONSTRAINT lts_timer_type_chk   CHECK (timer_type IN (
        'auto_close', 'auto_cancel', 'reminder', 'auto_transition'
    )),
    -- L08: 'failed' added
    CONSTRAINT lts_status_chk       CHECK (status IN (
        'scheduled', 'fired', 'cancelled', 'failed'
    )),
    CONSTRAINT lts_fire_after_chk   CHECK (fire_at >= scheduled_at),
    CONSTRAINT lts_entity_chk       CHECK (btrim(entity_name) <> '' AND btrim(entity_id) <> ''),
    CONSTRAINT lts_snapshot_chk     CHECK (jsonb_typeof(policy_snapshot) = 'object')
);

COMMENT ON TABLE  event.lifecycle_timer_schedule IS
    'Active timer work queue. One row per entity awaiting a scheduled lifecycle action. '
    'Created when entity enters a state that has a timer_policy_code in config. '
    'Cancelled when entity leaves the state before fire_at. '
    'Timer worker polls WHERE status=''scheduled'' AND fire_at <= now(). '
    'policy_snapshot: version-pinned copy of rules at schedule time. '
    'L08: failed status added. L11: entity_id=TEXT. '
    'Moved from control.* to event.* — it is an active work item, not config.';


-- =============================================================================
-- §9  event.work_item — individual human task
-- =============================================================================
-- One row per human task within a workflow. The primitive that a person
-- actually sees in their inbox and acts upon.
-- task_type discriminates: approval / review / watcher (lookup-validated).
-- A07: designated_id (who was originally assigned) is immutable after creation.
--       assignee_id  (who currently holds it) changes on reassignment.
-- work_item can exist without a workflow_stage (standalone watcher, ad-hoc review).
-- Renamed from event.approval_task (backup).

CREATE TABLE IF NOT EXISTS event.work_item (
    -- Identity
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,

    -- Task classification (lookup: work_item.task_type)
    task_type               text        NOT NULL DEFAULT 'approval',

    -- Parent references (both nullable — standalone work_items allowed)
    workflow_request_id     uuid,
    workflow_stage_id       uuid,

    -- Original assignment (A07: immutable after INSERT)
    designated_id           uuid,           -- resolved from workflow_template_rule
    designated_group_id     uuid,           -- group assignment (any member can claim)

    -- Current assignment (A07: updated on reassignment)
    assignee_id             uuid,
    assignee_group_id       uuid,
    assignee_team_id        uuid,

    -- Execution ordering (within serial-mode stage)
    order_index             smallint    NOT NULL DEFAULT 1,

    -- Task lifecycle
    status                  text        NOT NULL DEFAULT 'pending',
    assigned_at             timestamptz,
    started_at              timestamptz,
    completed_at            timestamptz,

    -- Decision (valid values driven by task_type metadata in lookup)
    -- approval:  approve | reject | escalate
    -- review:    acknowledge | flag | escalate
    -- watcher:   read
    decision                text,
    reason                  text,

    -- SLA
    due_at                  timestamptz,

    -- Metadata (IP, device, comment_id, etc.)
    metadata                jsonb       NOT NULL DEFAULT '{}',

    -- Audit
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT wi_pkey                  PRIMARY KEY (id),
    CONSTRAINT wi_tenant_id_uq          UNIQUE (tenant_id, id),
    CONSTRAINT wi_order_chk             CHECK (order_index >= 1),
    CONSTRAINT wi_status_chk            CHECK (status IN (
        'pending', 'assigned', 'in_progress', 'completed', 'skipped', 'escalated'
    )),
    -- A11: due_at must be in the future relative to creation
    CONSTRAINT wi_due_at_chk            CHECK (
        due_at IS NULL OR due_at > created_at
    ),
    -- Completed tasks must have completed_at
    CONSTRAINT wi_completed_chk         CHECK (
        status NOT IN ('completed', 'skipped', 'escalated')
        OR completed_at IS NOT NULL
    ),
    -- A07: assignee or group required when not pending
    CONSTRAINT wi_assignee_chk          CHECK (
        status = 'pending'
        OR assignee_id IS NOT NULL
        OR assignee_group_id IS NOT NULL
        OR assignee_team_id IS NOT NULL
    ),
    -- Exactly one of: stage-linked or standalone
    CONSTRAINT wi_request_stage_chk     CHECK (
        (workflow_request_id IS NOT NULL AND workflow_stage_id IS NOT NULL)  -- stage-linked
        OR (workflow_request_id IS NOT NULL AND workflow_stage_id IS NULL)   -- request-linked watcher
        OR (workflow_request_id IS NULL AND workflow_stage_id IS NULL)       -- fully standalone
    ),
    CONSTRAINT wi_metadata_chk          CHECK (jsonb_typeof(metadata) = 'object')
    -- task_type: 09_triggers — control.trg_validate_lookup_columns('work_item.task_type')
);

COMMENT ON TABLE  event.work_item IS
    'Individual human task — the primitive a person acts on. '
    'task_type (lookup: work_item.task_type): approval | review | watcher. '
    'A07: designated_id = original assignment (immutable). '
    '      assignee_id  = current holder (changes on reassignment). '
    'Can exist standalone (no workflow_request_id — ad-hoc task). '
    'Watcher tasks: workflow_stage_id=NULL, status auto-completes on read. '
    'Valid decisions driven by task_type metadata in lookup_value. '
    'Renamed from event.approval_task (backup).';
COMMENT ON COLUMN event.work_item.designated_id IS
    'Original assignee resolved from workflow_template_rule at task creation. '
    'Immutable after INSERT — enforced by trg_fn_wi_designation_guard. '
    'Audit trail: who was originally supposed to act on this task.';
COMMENT ON COLUMN event.work_item.assignee_id IS
    'Current holder. Starts equal to designated_id. '
    'Updated on reassignment — each change logged in log.workflow_event_log. '
    'NULL when assigned to a group (assignee_group_id set) awaiting claim.';
COMMENT ON COLUMN event.work_item.decision IS
    'Outcome of the work_item. Valid values per task_type: '
    'approval — approve | reject | escalate. '
    'review   — acknowledge | flag | escalate. '
    'watcher  — read. '
    'Validated by trg_fn_wi_decision_guard against task_type lookup metadata.';


-- ============================================================================
-- §10  event.push_subscription — web/mobile push device registry
-- ============================================================================
-- One row per (principal, platform, device). Tracks the endpoint and keys
-- required to deliver push notifications via VAPID (Web Push) or FCM/APNs.
-- Expired or inactive subscriptions pruned by cron.

CREATE TABLE IF NOT EXISTS event.push_subscription (
    -- Identity
    id              uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid            NOT NULL,
    principal_id    uuid            NOT NULL,

    -- Subscription identity
    platform        text            NOT NULL,   -- 'web', 'android', 'ios'
    device_id       text            NOT NULL,   -- browser fingerprint or OS device ID
    endpoint        text            NOT NULL,   -- push service URL (FCM / APNs / Web Push)

    -- Web Push VAPID keys (required when platform = 'web')
    p256dh_key      text,                       -- client public key
    auth_key        text,                       -- client auth secret

    -- FCM / APNs token (required when platform IN ('android', 'ios'))
    device_token    text,

    -- Optional metadata
    user_agent      text,
    metadata        jsonb           NOT NULL DEFAULT '{}',

    -- Lifecycle
    is_active       boolean         NOT NULL DEFAULT true,
    last_used_at    timestamptz,
    expires_at      timestamptz,

    -- Audit
    created_at      timestamptz     NOT NULL DEFAULT now(),
    created_by      uuid            NOT NULL,
    updated_at      timestamptz,
    updated_by      uuid,

    CONSTRAINT ps_pkey              PRIMARY KEY (id),
    CONSTRAINT ps_tenant_uq         UNIQUE (tenant_id, id),
    CONSTRAINT ps_device_uq         UNIQUE (tenant_id, principal_id, platform, device_id),
    CONSTRAINT ps_endpoint_chk      CHECK  (btrim(endpoint) <> ''),
    CONSTRAINT ps_platform_chk      CHECK  (platform IN ('web', 'android', 'ios')),
    CONSTRAINT ps_web_keys_chk      CHECK  (
        platform <> 'web'
        OR (p256dh_key IS NOT NULL AND auth_key IS NOT NULL)
    ),
    CONSTRAINT ps_mobile_token_chk  CHECK  (
        platform = 'web'
        OR device_token IS NOT NULL
    )
);

COMMENT ON TABLE event.push_subscription IS
    'Web/mobile push device registry. One row per (principal, platform, device). '
    'Web Push requires VAPID keys (p256dh_key + auth_key). '
    'FCM (android) and APNs (ios) use device_token. '
    'Expired or inactive subscriptions pruned by a periodic cron.';

COMMENT ON COLUMN event.push_subscription.platform IS
    'Push platform discriminator: ''web'' (VAPID), ''android'' (FCM), ''ios'' (APNs).';
COMMENT ON COLUMN event.push_subscription.device_id IS
    'Stable per-browser or per-device identifier used for deduplication on re-registration.';
COMMENT ON COLUMN event.push_subscription.endpoint IS
    'Push service delivery URL. For Web Push this is the browser-generated URL. '
    'For FCM/APNs this is the gateway endpoint for the device_token.';

CREATE INDEX IF NOT EXISTS ps_principal_active_idx
    ON event.push_subscription (tenant_id, principal_id)
    WHERE is_active = true;

CREATE INDEX IF NOT EXISTS ps_expired_pidx
    ON event.push_subscription (expires_at)
    WHERE is_active = true AND expires_at IS NOT NULL;


-- ============================================================================
-- §11  event.whatsapp_consent — WhatsApp Business API opt-in registry
-- ============================================================================
-- Tracks per-principal consent for outbound WhatsApp Business API messages.
-- consent_status lifecycle: pending → opted_in → opted_out / revoked.
-- Outbound WhatsApp messages are blocked unless consent_status = 'opted_in'.
-- Phone numbers stored in E.164 format (+[country][number]).

CREATE TABLE IF NOT EXISTS event.whatsapp_consent (
    -- Identity
    id              uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid            NOT NULL,
    principal_id    uuid            NOT NULL,

    -- Phone number (E.164)
    phone_e164      text            NOT NULL,

    -- Consent state
    consent_status  text            NOT NULL DEFAULT 'pending',
    consented_at    timestamptz,
    revoked_at      timestamptz,
    consent_source  text,           -- 'web_form', 'api', 'import'

    -- WhatsApp Business Account linkage
    waba_id         text,           -- WhatsApp Business Account ID
    namespace       text,           -- Template namespace for this tenant

    -- Optional metadata
    metadata        jsonb           NOT NULL DEFAULT '{}',

    -- Audit
    created_at      timestamptz     NOT NULL DEFAULT now(),
    created_by      uuid            NOT NULL,
    updated_at      timestamptz,
    updated_by      uuid,

    CONSTRAINT wac_pkey             PRIMARY KEY (id),
    CONSTRAINT wac_tenant_uq        UNIQUE (tenant_id, id),
    CONSTRAINT wac_phone_uq         UNIQUE (tenant_id, principal_id, phone_e164),
    CONSTRAINT wac_phone_chk        CHECK  (phone_e164 ~ '^\+[1-9]\d{1,14}$'),
    CONSTRAINT wac_status_chk       CHECK  (consent_status IN (
        'pending', 'opted_in', 'opted_out', 'revoked'
    )),
    CONSTRAINT wac_consent_chk      CHECK  (
        (consent_status = 'opted_in' AND consented_at IS NOT NULL)
        OR consent_status <> 'opted_in'
    ),
    CONSTRAINT wac_revoke_chk       CHECK  (
        (consent_status = 'revoked' AND revoked_at IS NOT NULL)
        OR consent_status <> 'revoked'
    )
);

COMMENT ON TABLE event.whatsapp_consent IS
    'WhatsApp Business API opt-in registry. Tracks per-principal consent status for '
    'outbound WhatsApp messages. consent_status lifecycle: pending → opted_in → revoked. '
    'Outbound messages blocked unless consent_status = ''opted_in''. '
    'Phone numbers stored in E.164 format.';

COMMENT ON COLUMN event.whatsapp_consent.phone_e164 IS
    'Recipient phone number in E.164 format (e.g. +14155552671). '
    'Must match the number registered with the WhatsApp Business Account.';
COMMENT ON COLUMN event.whatsapp_consent.consent_source IS
    'How consent was obtained: ''web_form'', ''api'', or ''import''.';
COMMENT ON COLUMN event.whatsapp_consent.waba_id IS
    'WhatsApp Business Account ID used to send messages to this recipient. '
    'Required by Meta Cloud API for template message dispatch.';

CREATE INDEX IF NOT EXISTS wac_principal_active_idx
    ON event.whatsapp_consent (tenant_id, principal_id)
    WHERE consent_status = 'opted_in';

CREATE INDEX IF NOT EXISTS wac_phone_lookup_idx
    ON event.whatsapp_consent (tenant_id, phone_e164)
    WHERE consent_status = 'opted_in';

-- FILE: /d/Products/athyper/server/db/sql/04_tables/007a_event_orchestration.sql
-- 04_tables/007a_event_orchestration.sql
-- Depends on: 007_event.sql
-- Dedicated persistence tables for DagOrchestrationService.
--
-- Replaces the temporary event.work_item workaround that was incompatible
-- with the wi_status_chk CHECK constraint (which only allows workflow-approval
-- statuses, not DAG-specific statuses like 'running' or 'failed').
--
-- Tables:
--   §1  event.orchestration_run   — one row per DAG execution
--   §2  event.orchestration_node  — one row per step within a run

-- ============================================================================
-- §1  orchestration_run — one row per DAG execution
-- ============================================================================

CREATE TABLE IF NOT EXISTS event.orchestration_run (
    -- Identity
    id              uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid        NOT NULL REFERENCES master.tenant(id),

    -- DAG reference
    dag_id          text        NOT NULL,  -- DagDefinition.id
    trigger_type    text        NOT NULL DEFAULT 'manual',   -- manual | scheduler | api
    trigger_ref     text,                                    -- schedule code, API call id, etc.
    correlation_id  text,

    -- Status
    status          text        NOT NULL DEFAULT 'running',

    -- Step counters (denormalised; updated on each node state change)
    total_nodes     integer     NOT NULL DEFAULT 0,
    completed_nodes integer     NOT NULL DEFAULT 0,
    failed_nodes    integer     NOT NULL DEFAULT 0,
    skipped_nodes   integer     NOT NULL DEFAULT 0,

    -- Timestamps
    started_at      timestamptz NOT NULL DEFAULT now(),
    completed_at    timestamptz,
    timeout_at      timestamptz,

    -- Payload snapshots
    input           jsonb,
    output          jsonb,

    -- Audit
    created_by      uuid,

    CONSTRAINT orch_run_pkey       PRIMARY KEY (id),
    CONSTRAINT orch_run_status_chk CHECK (status IN ('running', 'completed', 'failed', 'canceled'))
);

CREATE INDEX IF NOT EXISTS idx_orch_run_tenant_status
    ON event.orchestration_run (tenant_id, status, started_at DESC);

CREATE INDEX IF NOT EXISTS idx_orch_run_dag
    ON event.orchestration_run (tenant_id, dag_id, started_at DESC);

CREATE INDEX IF NOT EXISTS idx_orch_run_correlation
    ON event.orchestration_run (correlation_id)
    WHERE correlation_id IS NOT NULL;

COMMENT ON TABLE event.orchestration_run IS
    'One row per DAG execution — managed by DagOrchestrationService';

-- ============================================================================
-- §2  orchestration_node — one row per step within a run
-- ============================================================================

CREATE TABLE IF NOT EXISTS event.orchestration_node (
    -- Identity
    id              uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid        NOT NULL REFERENCES master.tenant(id),
    run_id          uuid        NOT NULL REFERENCES event.orchestration_run(id) ON DELETE CASCADE,

    -- Node identity (mirrors DagStep)
    node_code       text        NOT NULL,   -- DagStep.id
    node_type       text        NOT NULL,   -- DagStep.jobName (BullMQ job name)
    depends_on      text[]      NOT NULL DEFAULT '{}',  -- array of node_code values

    -- Status
    status          text        NOT NULL DEFAULT 'pending',

    -- BullMQ correlation
    job_id          text,

    -- Payload
    input           jsonb,
    output          jsonb,
    error           text,

    -- Execution metrics
    retry_count     integer     NOT NULL DEFAULT 0,

    -- Timestamps
    started_at      timestamptz,
    completed_at    timestamptz,
    duration_ms     integer,

    CONSTRAINT orch_node_pkey       PRIMARY KEY (id),
    CONSTRAINT orch_node_run_code   UNIQUE (run_id, node_code),
    CONSTRAINT orch_node_status_chk CHECK (
        status IN ('pending', 'running', 'completed', 'failed', 'skipped', 'canceled')
    )
);

CREATE INDEX IF NOT EXISTS idx_orch_node_run_id
    ON event.orchestration_node (run_id);

CREATE INDEX IF NOT EXISTS idx_orch_node_job_id
    ON event.orchestration_node (job_id)
    WHERE job_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_orch_node_active
    ON event.orchestration_node (tenant_id, status)
    WHERE status IN ('pending', 'running');

COMMENT ON TABLE event.orchestration_node IS
    'One row per step within a DAG run — managed by DagOrchestrationService';

-- FILE: /d/Products/athyper/server/db/sql/04_tables/007b_event_connector_instance.sql
-- 04_tables/007b_event_connector_instance.sql
-- Depends on: 007_event.sql, 002_control.sql (control.connector_type)
-- Per-tenant connector connection instances.
--
-- A connector_instance is one configured, authenticated connection to an
-- external system described by a control.connector_type template.
-- The config_schema of the type drives the UI form for instance creation.
--
-- NOTE (Phase 5 hardening): credential fields inside the `config` JSONB
-- should be encrypted at rest via CredentialEncryptionService before storage.
-- For Phase 4 they are stored as plaintext. Mask them in list responses.

CREATE TABLE IF NOT EXISTS event.connector_instance (
    -- Identity
    id                    uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id             uuid        NOT NULL REFERENCES master.tenant(id),
    connector_type_id     uuid        NOT NULL REFERENCES control.connector_type(id),

    -- Instance identity
    code                  text        NOT NULL,
    name                  text        NOT NULL,
    description           text,

    -- Config (form values matching connector_type.config_schema)
    -- WARNING: may contain credential values — encrypt in Phase 5.
    config                jsonb       NOT NULL DEFAULT '{}',

    -- Status & health
    status                text        NOT NULL DEFAULT 'active',
    health_status         text        NOT NULL DEFAULT 'unknown',
    last_health_check_at  timestamptz,
    last_error_message    text,
    is_active             boolean     NOT NULL DEFAULT true,

    -- Audit
    created_at            timestamptz NOT NULL DEFAULT now(),
    created_by            uuid        NOT NULL,
    updated_at            timestamptz,
    updated_by            uuid,

    CONSTRAINT connector_instance_pkey         PRIMARY KEY (id),
    CONSTRAINT connector_instance_code_uq      UNIQUE (tenant_id, code),
    CONSTRAINT connector_instance_status_chk   CHECK (status IN ('active', 'testing', 'paused', 'error', 'deprecated')),
    CONSTRAINT connector_instance_health_chk   CHECK (health_status IN ('healthy', 'degraded', 'down', 'unknown'))
);

CREATE INDEX IF NOT EXISTS idx_connector_instance_tenant
    ON event.connector_instance (tenant_id, is_active, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_connector_instance_type
    ON event.connector_instance (connector_type_id, tenant_id);

CREATE INDEX IF NOT EXISTS idx_connector_instance_health
    ON event.connector_instance (tenant_id, health_status)
    WHERE health_status IN ('degraded', 'down');

COMMENT ON TABLE event.connector_instance IS
    'Per-tenant configured connections to external systems — instances of control.connector_type templates';

-- FILE: /d/Products/athyper/server/db/sql/04_tables/008_governance.sql
-- 04_tables/008_governance.sql
-- Depends on: 01_schemas, 04_tables/003_master.sql
-- Governance schema tables.

-- ============================================================================
-- §11  governance.comment_moderation — aggregated moderation state
-- ============================================================================
CREATE TABLE IF NOT EXISTS governance.comment_moderation (
    -- Identity
    id              uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid        NOT NULL,

    -- Subject (one row per comment)
    context_type    text        NOT NULL,
    comment_id      uuid        NOT NULL,

    -- Moderation state (mutable — UPSERT on flag events)
    is_hidden       boolean     NOT NULL DEFAULT false,
    hidden_reason   text,
    hidden_at       timestamptz,
    hidden_by       uuid,

    -- Counters (maintained by trigger)
    flag_count      integer     NOT NULL DEFAULT 0,
    last_flagged_at timestamptz,

    -- Audit
    created_at      timestamptz NOT NULL DEFAULT now(),
    created_by      uuid        NOT NULL,
    updated_at      timestamptz,
    updated_by      uuid,

    CONSTRAINT gmod_pkey        PRIMARY KEY (id),
    CONSTRAINT gmod_unique      UNIQUE (tenant_id, context_type, comment_id),
    CONSTRAINT gmod_count_chk   CHECK (flag_count >= 0),
    CONSTRAINT gmod_hidden_chk  CHECK (
        (is_hidden = false AND hidden_at IS NULL AND hidden_by IS NULL)
        OR (is_hidden = true AND hidden_at IS NOT NULL AND hidden_by IS NOT NULL)
    )
    -- context_type: 09_triggers — control.trg_validate_lookup_columns('master.comment_type')
);

COMMENT ON TABLE  governance.comment_moderation IS
    'Aggregated moderation state per comment. One row per (tenant, context_type, comment_id). '
    'UPSERT pattern — updated by trigger on event.comment_flag changes. '
    'Kept separate from event.comment_flag for O(1) render-time moderation checks. '
    'context_type in master.comment_type lookup.';
COMMENT ON COLUMN governance.comment_moderation.flag_count IS
    'Total accumulated flags for this comment across all reporters. '
    'Maintained by trg_sync_comment_moderation trigger on event.comment_flag.';


-- ============================================================================
-- §BPS  governance.book_period_status — per-book period gate
-- ============================================================================
-- Same period can be open in STAT but closed in TAX.
-- Posting checks BOTH fiscal_period.status AND book_period_status.status.
-- ============================================================================

CREATE TABLE IF NOT EXISTS governance.book_period_status (
    -- Identity
    id               uuid         NOT NULL DEFAULT shared.uuidv7(),
    tenant_id        uuid         NOT NULL,

    -- Company scope (Tier 1 UUID)
    company_code_id  uuid         NOT NULL,

    -- Book + Period
    book_id          uuid         NOT NULL,
    fiscal_year      smallint     NOT NULL,
    period_number    smallint     NOT NULL,

    -- Close timestamps
    opened_at        timestamptz,
    opened_by        uuid,
    soft_closed_at   timestamptz,
    soft_closed_by   uuid,
    hard_closed_at   timestamptz,
    hard_closed_by   uuid,

    -- Reopen tracking
    reopen_count     smallint     NOT NULL DEFAULT 0,
    last_reopen_reason text,

    -- Metadata
    metadata         jsonb        NOT NULL DEFAULT '{}'::jsonb,

    -- Lifecycle
    status           text         NOT NULL DEFAULT 'future',
    is_active        boolean      GENERATED ALWAYS AS (status IN ('open', 'soft_close')) STORED,
    status_changed_at timestamptz,
    status_changed_by uuid,

    -- Audit
    created_at       timestamptz  NOT NULL DEFAULT now(),
    created_by       uuid         NOT NULL,
    updated_at       timestamptz,
    updated_by       uuid,

    CONSTRAINT book_period_status_pkey PRIMARY KEY (id),
    CONSTRAINT book_period_status_tenant_id_uq UNIQUE (tenant_id, id),
    CONSTRAINT book_period_status_composite_uq
        UNIQUE (tenant_id, company_code_id, book_id, fiscal_year, period_number),
    CONSTRAINT bps_period_range_chk CHECK (period_number BETWEEN 0 AND 16),
    CONSTRAINT bps_reopen_count_chk CHECK (reopen_count >= 0)
);

COMMENT ON TABLE governance.book_period_status IS
    'Per-book period gate. Same period can be open in STAT but closed in TAX. '
    'Posting requires BOTH fiscal_period.status AND book_period_status.status '
    'to allow posting.';


-- ============================================================================
-- GENERIC GOVERNANCE CYCLE MODEL
-- ============================================================================
-- 11 tables implementing a reusable cycle-based governance framework.
-- Supports ordered phases, parallel tasks via intra-cycle DAG, hybrid JSONB
-- domain_data, cross-cycle dependencies, deviation carryforward, and
-- external approval integration via document.workflow_request.
--
-- Lifecycle state machines:
--   cycle_run:    PLANNED → OPEN → IN_PROGRESS → PHASE_GATE → COMPLETED → CERTIFIED → CLOSED
--   cycle_task:   PENDING → IN_PROGRESS → COMPLETED | FAILED | DEVIATED | BLOCKED
--   cycle_deviation: OPEN → PENDING_APPROVAL → APPROVED → APPLIED → RESOLVED | ACCEPTED
--   cycle_certification: DRAFT → PENDING_REVIEW → CERTIFIED → ATTESTED → SUPERSEDED | REVOKED


-- ============================================================================
-- §CT  governance.cycle_type — cycle type definitions (root entity)
-- ============================================================================
CREATE TABLE IF NOT EXISTS governance.cycle_type (
    -- Identity
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,

    -- Definition
    type_code               varchar(30) NOT NULL,
    type_name               varchar(150) NOT NULL,
    description             text,
    frequency               varchar(20) NOT NULL DEFAULT 'MONTHLY',
    domain                  varchar(30) NOT NULL,
    clean_cycle_policy      jsonb       NOT NULL DEFAULT '{}'::jsonb,
    approval_policies       jsonb                DEFAULT '{}'::jsonb,
    run_data_schema         jsonb,
    task_data_schema        jsonb,

    -- Lifecycle
    is_active               boolean     NOT NULL DEFAULT true,

    -- Audit
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT ctyp_pkey           PRIMARY KEY (id),
    CONSTRAINT ctyp_code_uq        UNIQUE (tenant_id, type_code),
    CONSTRAINT ctyp_tenant_id_uq   UNIQUE (tenant_id, id),
    CONSTRAINT ctyp_frequency_chk  CHECK (
        frequency IN ('DAILY','WEEKLY','BIWEEKLY','SEMI_MONTHLY',
                      'MONTHLY','QUARTERLY','SEMI_ANNUAL','ANNUAL','AD_HOC')),
    CONSTRAINT ctyp_domain_chk     CHECK (
        domain IN ('FINANCE','HR','INVENTORY','WAREHOUSE','PROCUREMENT',
                   'PROJECT','SUPPLIER','SAFETY','COMPLIANCE','CUSTOM'))
);

COMMENT ON TABLE governance.cycle_type IS
    'Governance cycle type definitions. Root entity for the cycle model. '
    'Each type defines phases, task categories, templates, and policies.';


-- ============================================================================
-- §CP  governance.cycle_phase — ordered phases per cycle type
-- ============================================================================
CREATE TABLE IF NOT EXISTS governance.cycle_phase (
    -- Identity
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,

    -- Parent
    cycle_type_id           uuid        NOT NULL,

    -- Definition
    phase_code              varchar(30) NOT NULL,
    phase_name              varchar(100) NOT NULL,
    sort_order              smallint    NOT NULL,
    description             text,
    is_gate_enforced        boolean     NOT NULL DEFAULT true,
    min_readiness_pct       numeric(5,2),
    target_hours_from_start integer,

    -- Lifecycle
    is_active               boolean     NOT NULL DEFAULT true,

    -- Audit
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT cph_pkey              PRIMARY KEY (id),
    CONSTRAINT cph_code_uq           UNIQUE (tenant_id, cycle_type_id, phase_code),
    CONSTRAINT cph_order_uq          UNIQUE (tenant_id, cycle_type_id, sort_order),
    CONSTRAINT cph_tenant_type_id_uq UNIQUE (tenant_id, cycle_type_id, id),
    CONSTRAINT cph_type_fk           FOREIGN KEY (tenant_id, cycle_type_id)
        REFERENCES governance.cycle_type (tenant_id, id)
);

COMMENT ON TABLE governance.cycle_phase IS
    'Ordered phases within a cycle type. sort_order determines sequence. '
    'Gates can be enforced per phase with min_readiness_pct thresholds.';


-- ============================================================================
-- §TCAT  governance.cycle_task_category — task categories per cycle type
-- ============================================================================
CREATE TABLE IF NOT EXISTS governance.cycle_task_category (
    -- Identity
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,

    -- Parent
    cycle_type_id           uuid        NOT NULL,

    -- Definition
    category_code           varchar(30) NOT NULL,
    category_name           varchar(100) NOT NULL,
    sort_order              smallint    NOT NULL DEFAULT 0,
    color_code              varchar(7),

    -- Lifecycle
    is_active               boolean     NOT NULL DEFAULT true,

    -- Audit
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT ctcat_pkey              PRIMARY KEY (id),
    CONSTRAINT ctcat_code_uq           UNIQUE (tenant_id, cycle_type_id, category_code),
    CONSTRAINT ctcat_tenant_type_id_uq UNIQUE (tenant_id, cycle_type_id, id),
    CONSTRAINT ctcat_type_fk           FOREIGN KEY (tenant_id, cycle_type_id)
        REFERENCES governance.cycle_type (tenant_id, id)
);

COMMENT ON TABLE governance.cycle_task_category IS
    'Registered task categories per cycle type (e.g. SUBLEDGER, TAX, CASH). '
    'FK-enforced on cycle_task_template.category_id. '
    'P2-FIX: updated_at/updated_by added — category metadata (name, sort, color) is mutable.';


-- ============================================================================
-- §TPL  governance.cycle_task_template — reusable task definitions
-- ============================================================================
CREATE TABLE IF NOT EXISTS governance.cycle_task_template (
    -- Identity
    id                       uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id                uuid        NOT NULL,
    entity_code              varchar(20) NOT NULL,

    -- Parents
    cycle_type_id            uuid        NOT NULL,
    phase_id                 uuid        NOT NULL,
    category_id              uuid        NOT NULL,

    -- Definition
    task_code                varchar(50) NOT NULL,
    task_name                varchar(150) NOT NULL,
    description              text,
    completion_mode          varchar(10) NOT NULL DEFAULT 'MANUAL',
    system_check_handler     varchar(100),
    is_mandatory             boolean     NOT NULL DEFAULT true,
    is_waivable              boolean     NOT NULL DEFAULT false,
    severity                 varchar(10),
    sort_order               smallint    NOT NULL DEFAULT 0,
    sla_hours                integer,
    estimated_duration_min   integer,
    reminder_lead_hours      integer,
    default_owner_role       text,
    default_owner_user_id    uuid,
    is_auto_start_when_ready boolean     NOT NULL DEFAULT false,
    orchestration_group      text,
    blueprint_filter         varchar(5)[],

    -- Lifecycle
    is_active                boolean     NOT NULL DEFAULT true,

    -- Audit
    created_at               timestamptz NOT NULL DEFAULT now(),
    created_by               uuid        NOT NULL,
    updated_at               timestamptz,
    updated_by               uuid,

    CONSTRAINT ctpl_pkey               PRIMARY KEY (id),
    CONSTRAINT ctpl_code_uq            UNIQUE (tenant_id, entity_code, cycle_type_id, task_code),
    CONSTRAINT ctpl_type_fk            FOREIGN KEY (tenant_id, cycle_type_id)
        REFERENCES governance.cycle_type (tenant_id, id),
    CONSTRAINT ctpl_phase_fk           FOREIGN KEY (tenant_id, cycle_type_id, phase_id)
        REFERENCES governance.cycle_phase (tenant_id, cycle_type_id, id),
    CONSTRAINT ctpl_category_fk        FOREIGN KEY (tenant_id, cycle_type_id, category_id)
        REFERENCES governance.cycle_task_category (tenant_id, cycle_type_id, id),
    CONSTRAINT ctpl_completion_mode_chk CHECK (completion_mode IN ('MANUAL','SYSTEM','HYBRID')),
    CONSTRAINT ctpl_system_handler_chk  CHECK (completion_mode = 'MANUAL' OR system_check_handler IS NOT NULL),
    CONSTRAINT ctpl_severity_chk        CHECK (severity IS NULL OR severity IN ('LOW','MEDIUM','HIGH','CRITICAL')),
    CONSTRAINT ctpl_sla_positive_chk    CHECK (sla_hours IS NULL OR sla_hours > 0),
    CONSTRAINT ctpl_dur_positive_chk    CHECK (estimated_duration_min IS NULL OR estimated_duration_min > 0)
);

COMMENT ON TABLE governance.cycle_task_template IS
    'Reusable task definitions within a cycle type. Templates are materialized '
    'into cycle_task instances when a cycle_run is opened.';


-- ============================================================================
-- §TDEP  governance.cycle_task_dependency — intra-cycle DAG between templates
-- ============================================================================
CREATE TABLE IF NOT EXISTS governance.cycle_task_dependency (
    -- Identity
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,

    -- Scope
    cycle_type_id           uuid        NOT NULL,
    entity_code             varchar(20) NOT NULL,

    -- Edge
    predecessor_template_id uuid        NOT NULL REFERENCES governance.cycle_task_template(id),
    successor_template_id   uuid        NOT NULL REFERENCES governance.cycle_task_template(id),
    dependency_type         varchar(20) NOT NULL DEFAULT 'FINISH_TO_START',
    is_hard                 boolean     NOT NULL DEFAULT true,

    -- Lifecycle
    is_active               boolean     NOT NULL DEFAULT true,

    -- Audit
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT ctdep_pkey          PRIMARY KEY (id),
    CONSTRAINT ctdep_no_self_chk   CHECK (predecessor_template_id <> successor_template_id),
    CONSTRAINT ctdep_dep_type_chk  CHECK (dependency_type IN ('FINISH_TO_START','FINISH_TO_FINISH')),
    CONSTRAINT ctdep_edge_uq       UNIQUE (tenant_id, cycle_type_id, entity_code, predecessor_template_id, successor_template_id),
    CONSTRAINT ctdep_type_fk       FOREIGN KEY (tenant_id, cycle_type_id)
        REFERENCES governance.cycle_type (tenant_id, id)
);

COMMENT ON TABLE governance.cycle_task_dependency IS
    'Intra-cycle directed acyclic graph (DAG) between task templates. '
    'Cycle detection enforced by trg_check_dep_cycle trigger.';


-- ============================================================================
-- §CRUN  governance.cycle_run — runtime cycle instance
-- ============================================================================
CREATE TABLE IF NOT EXISTS governance.cycle_run (
    -- Identity
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,
    entity_code             varchar(20) NOT NULL,

    -- Type + Period
    cycle_type_id           uuid        NOT NULL,
    fiscal_year             smallint    NOT NULL,
    period_number           smallint    NOT NULL,
    run_number              smallint    NOT NULL DEFAULT 1,

    -- Lifecycle
    status                  varchar(30) NOT NULL DEFAULT 'PLANNED',
    current_phase_id        uuid,

    -- Dates
    period_end_date         date        NOT NULL,
    cycle_start_date        date        NOT NULL,
    cycle_target_date       date        NOT NULL,
    phase_targets           jsonb       NOT NULL DEFAULT '[]'::jsonb,

    -- Execution timestamps
    started_at              timestamptz,
    started_by              uuid,
    completed_at            timestamptz,
    completed_by            uuid,
    certified_at            timestamptz,
    certified_by            uuid,
    cancelled_at            timestamptz,
    cancelled_by            uuid,

    -- Domain
    notes                   text,
    domain_data             jsonb       NOT NULL DEFAULT '{}'::jsonb,

    -- Audit
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT crun_pkey           PRIMARY KEY (id),
    CONSTRAINT crun_natural_uq     UNIQUE (tenant_id, entity_code, cycle_type_id, fiscal_year, period_number, run_number),
    CONSTRAINT crun_tenant_id_uq   UNIQUE (tenant_id, id),
    CONSTRAINT crun_type_fk        FOREIGN KEY (tenant_id, cycle_type_id)
        REFERENCES governance.cycle_type (tenant_id, id),
    CONSTRAINT crun_phase_fk       FOREIGN KEY (tenant_id, cycle_type_id, current_phase_id)
        REFERENCES governance.cycle_phase (tenant_id, cycle_type_id, id),
    CONSTRAINT crun_status_chk     CHECK (
        status IN ('PLANNED','OPEN','IN_PROGRESS','PHASE_GATE','COMPLETED',
                   'CERTIFIED','CLOSED','REOPENED','CANCELLED')),
    CONSTRAINT crun_dates_chk      CHECK (cycle_start_date <= cycle_target_date)
);

COMMENT ON TABLE governance.cycle_run IS
    'Runtime cycle instance. One run per (entity, type, fiscal_year, period, run_number). '
    'domain_data validated against cycle_type.run_data_schema by trigger.';
COMMENT ON COLUMN governance.cycle_run.domain_data IS
    'Extensible JSONB payload validated against cycle_type.run_data_schema by '
    'governance.trg_validate_domain_data(). Holds cycle-specific context such as '
    'reporting_currency, consolidation_scope, and special instructions.';


-- ============================================================================
-- §CTSK  governance.cycle_task — materialized task instance
-- ============================================================================
CREATE TABLE IF NOT EXISTS governance.cycle_task (
    -- Identity
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,
    entity_code             varchar(20) NOT NULL,

    -- Parents
    cycle_run_id            uuid        NOT NULL,
    template_id             uuid        NOT NULL REFERENCES governance.cycle_task_template(id),
    phase_id                uuid        NOT NULL,
    category_id             uuid        NOT NULL,

    -- Definition (copied from template)
    task_code               varchar(50) NOT NULL,
    is_mandatory            boolean     NOT NULL DEFAULT true,

    -- Assignment
    assigned_to             uuid,
    assigned_role           text,

    -- Lifecycle
    status                  varchar(20) NOT NULL DEFAULT 'PENDING',
    due_at                  timestamptz,

    -- Completion
    completed_by            uuid,
    completed_at            timestamptz,
    completion_notes        text,
    evidence_payload        jsonb       NOT NULL DEFAULT '{}'::jsonb,

    -- Failure
    failure_reason          text,
    failed_at               timestamptz,

    -- Runtime
    execution_meta          jsonb       NOT NULL DEFAULT '{}'::jsonb,
    domain_data             jsonb       NOT NULL DEFAULT '{}'::jsonb,

    -- Audit
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT ctsk_pkey              PRIMARY KEY (id),
    CONSTRAINT ctsk_natural_uq        UNIQUE (tenant_id, cycle_run_id, task_code),
    CONSTRAINT ctsk_run_fk            FOREIGN KEY (tenant_id, cycle_run_id)
        REFERENCES governance.cycle_run (tenant_id, id),
    CONSTRAINT ctsk_status_chk        CHECK (status IN ('PENDING','IN_PROGRESS','COMPLETED','BLOCKED','FAILED','DEVIATED')),
    CONSTRAINT ctsk_completion_chk    CHECK (status <> 'COMPLETED' OR (completed_by IS NOT NULL AND completed_at IS NOT NULL)),
    CONSTRAINT ctsk_completion_cln_chk CHECK (status = 'COMPLETED' OR completed_by IS NULL),
    CONSTRAINT ctsk_failure_chk       CHECK (status <> 'FAILED' OR (failure_reason IS NOT NULL AND failed_at IS NOT NULL)),
    CONSTRAINT ctsk_failure_cln_chk   CHECK (status = 'FAILED' OR failure_reason IS NULL)
);

COMMENT ON TABLE governance.cycle_task IS
    'Materialized task instance within a cycle run. Created from templates by '
    'governance.materialize_cycle_tasks(). domain_data validated by trigger.';
COMMENT ON COLUMN governance.cycle_task.domain_data IS
    'Extensible JSONB payload validated against cycle_task_template.task_data_schema. '
    'Holds task-specific context: checklist items, calculation parameters, scope filters.';
COMMENT ON COLUMN governance.cycle_task.evidence_payload IS
    'Structured proof of task completion. Contents vary by task_code: '
    'e.g. reconciliation_report, sign-off screenshots, balance confirmations. '
    'Validated by governance.trg_validate_domain_data() if evidence_schema is set on template.';
COMMENT ON COLUMN governance.cycle_task.execution_meta IS
    'Runtime execution metadata: retry counts, worker_id, timing metrics, error traces. '
    'Written by the task execution engine, not by users.';


-- ============================================================================
-- §CDEV  governance.cycle_deviation — unified exception/override/waiver
-- ============================================================================
CREATE TABLE IF NOT EXISTS governance.cycle_deviation (
    -- Identity
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,
    entity_code             varchar(20) NOT NULL,

    -- Parent
    cycle_run_id            uuid        NOT NULL,

    -- Classification
    deviation_type          varchar(20) NOT NULL,
    scope                   varchar(20) NOT NULL DEFAULT 'TASK',

    -- Scope references
    task_id                 uuid        REFERENCES governance.cycle_task(id),
    task_template_id        uuid        REFERENCES governance.cycle_task_template(id),
    task_code               varchar(50),
    task_category           varchar(30),
    deviation_code          varchar(50),

    -- Description
    title                   varchar(200) NOT NULL,
    description             text,

    -- Reason
    reason_code             varchar(30) NOT NULL,
    reason_subcode          varchar(30),
    reason_detail           text,

    -- Impact
    severity                varchar(20) NOT NULL DEFAULT 'MEDIUM',
    impact_type             varchar(30) NOT NULL DEFAULT 'PROCESS',
    impact_amount           numeric(18,4),
    impact_currency         varchar(3),

    -- Lifecycle
    status                  varchar(20) NOT NULL DEFAULT 'OPEN',
    applies_to_phase_id     uuid        REFERENCES governance.cycle_phase(id),

    -- Workflow approval
    workflow_request_id     uuid,

    -- Actors
    requested_by            uuid        NOT NULL,
    requested_at            timestamptz NOT NULL DEFAULT now(),
    decision_notes          text,
    assigned_to             uuid,
    assigned_at             timestamptz,
    resolved_by             uuid,
    resolved_at             timestamptz,
    resolution_notes        text,
    revocation_reason       text,

    -- Evidence
    evidence_payload        jsonb       NOT NULL DEFAULT '{}'::jsonb,

    -- Effectivity
    effective_from          date        NOT NULL DEFAULT CURRENT_DATE,
    effective_to            date,

    -- Carryforward lineage
    carried_from_id         uuid        REFERENCES governance.cycle_deviation(id),
    carry_count             smallint    NOT NULL DEFAULT 0,

    -- Audit
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT cdev_pkey              PRIMARY KEY (id),
    CONSTRAINT cdev_run_fk            FOREIGN KEY (tenant_id, cycle_run_id)
        REFERENCES governance.cycle_run (tenant_id, id),
    CONSTRAINT cdev_type_chk          CHECK (deviation_type IN ('EXCEPTION','OVERRIDE','WAIVER')),
    CONSTRAINT cdev_scope_chk         CHECK (scope IN ('TASK','CATEGORY','GATE','PERIOD')),
    CONSTRAINT cdev_severity_chk      CHECK (severity IN ('LOW','MEDIUM','HIGH','CRITICAL')),
    CONSTRAINT cdev_impact_type_chk   CHECK (impact_type IN ('TASK_BLOCKER','GATE_BLOCKER','DATA_QUALITY','PROCESS','EXTERNAL','IMMATERIAL')),
    CONSTRAINT cdev_status_chk        CHECK (
        status IN ('OPEN','PENDING_APPROVAL','APPROVED','REJECTED','APPLIED',
                   'RESOLVED','ACCEPTED','DEFERRED','EXPIRED','REVOKED','CARRIED_FORWARD')),
    CONSTRAINT cdev_cat_ref_chk       CHECK (scope <> 'CATEGORY' OR task_category IS NOT NULL),
    CONSTRAINT cdev_decision_chk      CHECK (status NOT IN ('APPROVED','REJECTED') OR decision_notes IS NOT NULL),
    CONSTRAINT cdev_resolution_chk    CHECK (status NOT IN ('RESOLVED','ACCEPTED') OR resolution_notes IS NOT NULL),
    CONSTRAINT cdev_task_scope_chk    CHECK (scope <> 'TASK' OR task_id IS NOT NULL OR task_template_id IS NOT NULL),
    CONSTRAINT cdev_gate_scope_chk    CHECK (scope <> 'GATE' OR applies_to_phase_id IS NOT NULL)
);

COMMENT ON TABLE governance.cycle_deviation IS
    'Unified exception/override/waiver within a cycle run. Supports approval '
    'workflow via document.workflow_request, carryforward lineage, and '
    'scope-specific integrity constraints.';
COMMENT ON COLUMN governance.cycle_deviation.evidence_payload IS
    'Structured proof supporting the deviation: exception reports, override justifications, '
    'waiver approvals. Validated by governance.trg_validate_domain_data() if schema defined.';


-- ============================================================================
-- §CCERT  governance.cycle_certification — formal sign-off / attestation
-- ============================================================================
CREATE TABLE IF NOT EXISTS governance.cycle_certification (
    -- Identity
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,
    entity_code             varchar(20) NOT NULL,

    -- Parent
    cycle_run_id            uuid        NOT NULL,

    -- Definition
    cert_code               varchar(40) NOT NULL,
    cert_version            smallint    NOT NULL DEFAULT 1,
    cert_type               varchar(20) NOT NULL DEFAULT 'STANDARD',

    -- Lifecycle
    status                  varchar(20) NOT NULL DEFAULT 'DRAFT',
    content_hash            varchar(64),
    snapshot_payload        jsonb,

    -- Workflow approval
    workflow_request_id     uuid,

    -- Review
    controller_notes        text,
    attestation_notes       text,

    -- Actors
    certified_by            uuid,
    certified_at            timestamptz,
    attested_by             uuid,
    attested_at             timestamptz,

    -- Supersession
    superseded_by_id        uuid        REFERENCES governance.cycle_certification(id),
    supersession_reason     text,
    revocation_reason       text,

    -- Audit
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT ccert_pkey          PRIMARY KEY (id),
    CONSTRAINT ccert_natural_uq    UNIQUE (tenant_id, cycle_run_id, cert_code, cert_version),
    CONSTRAINT ccert_run_fk        FOREIGN KEY (tenant_id, cycle_run_id)
        REFERENCES governance.cycle_run (tenant_id, id),
    CONSTRAINT ccert_type_chk      CHECK (cert_type IN ('STANDARD','WITH_EXCEPTIONS','QUALIFIED','INTERIM')),
    CONSTRAINT ccert_status_chk    CHECK (status IN ('DRAFT','PENDING_REVIEW','CERTIFIED','ATTESTED','SUPERSEDED','REVOKED'))
);

COMMENT ON TABLE governance.cycle_certification IS
    'Formal sign-off and attestation within a cycle run. Supports versioning, '
    'supersession, content hashing, and external approval workflow.';


-- ============================================================================
-- §CXDEP  governance.cycle_cross_dependency — phase-to-phase across types
-- ============================================================================
CREATE TABLE IF NOT EXISTS governance.cycle_cross_dependency (
    -- Identity
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,

    -- Predecessor
    predecessor_type_id     uuid        NOT NULL,
    predecessor_phase_id    uuid        NOT NULL,

    -- Successor
    successor_type_id       uuid        NOT NULL,
    successor_phase_id      uuid        NOT NULL,

    -- Config
    is_hard                 boolean     NOT NULL DEFAULT true,
    is_active               boolean     NOT NULL DEFAULT true,
    description             text,

    -- Audit
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT cxdep_pkey          PRIMARY KEY (id),
    CONSTRAINT cxdep_edge_uq       UNIQUE (tenant_id, predecessor_type_id, predecessor_phase_id, successor_type_id, successor_phase_id),
    CONSTRAINT cxdep_no_self_chk   CHECK (predecessor_type_id <> successor_type_id OR predecessor_phase_id <> successor_phase_id),
    CONSTRAINT cxdep_pred_phase_fk FOREIGN KEY (tenant_id, predecessor_type_id, predecessor_phase_id)
        REFERENCES governance.cycle_phase (tenant_id, cycle_type_id, id),
    CONSTRAINT cxdep_succ_phase_fk FOREIGN KEY (tenant_id, successor_type_id, successor_phase_id)
        REFERENCES governance.cycle_phase (tenant_id, cycle_type_id, id)
);

COMMENT ON TABLE governance.cycle_cross_dependency IS
    'Phase-to-phase dependencies across different cycle types. Used by '
    'governance.check_cross_cycle_gate() to block successor phase entry. '
    'P2-FIX: updated_at/updated_by added — is_active and description are mutable.';


-- ============================================================================
-- §CCFR  governance.cycle_carryforward_rule — carryforward config per type
-- ============================================================================
CREATE TABLE IF NOT EXISTS governance.cycle_carryforward_rule (
    -- Identity
    id                      uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id               uuid        NOT NULL,

    -- Parent
    cycle_type_id           uuid        NOT NULL,

    -- Rule
    deviation_type          varchar(20) NOT NULL,
    action                  varchar(20) NOT NULL,
    max_carry_count         smallint,
    escalate_after_carries  smallint,
    description             text,

    -- Lifecycle
    is_active               boolean     NOT NULL DEFAULT true,

    -- Audit
    created_at              timestamptz NOT NULL DEFAULT now(),
    created_by              uuid        NOT NULL,
    updated_at              timestamptz,
    updated_by              uuid,

    CONSTRAINT ccfr_pkey           PRIMARY KEY (id),
    CONSTRAINT ccfr_rule_uq        UNIQUE (tenant_id, cycle_type_id, deviation_type),
    CONSTRAINT ccfr_type_fk        FOREIGN KEY (tenant_id, cycle_type_id)
        REFERENCES governance.cycle_type (tenant_id, id),
    CONSTRAINT ccfr_dev_type_chk   CHECK (deviation_type IN ('EXCEPTION','OVERRIDE','WAIVER')),
    CONSTRAINT ccfr_action_chk     CHECK (action IN ('FORCE_CLOSE','AUTO_CARRY','EXPIRE')),
    CONSTRAINT ccfr_max_count_chk  CHECK (max_carry_count IS NULL OR max_carry_count > 0)
);

COMMENT ON TABLE governance.cycle_carryforward_rule IS
    'Carryforward policy per cycle type and deviation type. Controls whether '
    'open deviations are force-closed, auto-carried, or expired at cycle boundary. '
    'P2-FIX: updated_at/updated_by added — rule config (action, thresholds) is mutable.';


-- =============================================================================
-- §RP  governance.report_pack — Phase 4.4 report delivery
-- =============================================================================
-- Tracks generated report packs for governance cycles.
-- Each row represents a requested report bundle for a cycle run.
-- Files are stored in object storage (S3/MinIO).
-- The download endpoint generates a time-limited presigned URL from storage_key.
--
-- Phase 4.4 delivery contract (A12):
--   GET /api/governance/report-packs/:id/download → 302 redirect to presigned URL
--   Initial implementation uses HTML stub (format='html').
--   Upgrades to PDF format after Phase 5.1 rendering pipeline ships.

CREATE TABLE IF NOT EXISTS governance.report_pack (
    -- Identity
    id                  uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id           uuid        NOT NULL,

    -- Subject
    cycle_run_id        uuid        NOT NULL,

    -- Report spec
    report_type         text        NOT NULL DEFAULT 'cycle_summary',
    format              text        NOT NULL DEFAULT 'html',

    -- Generation status
    status              text        NOT NULL DEFAULT 'pending',

    -- Storage
    storage_key         text,               -- S3/MinIO object key; NULL until generated
    file_size_bytes     bigint,
    content_type        text        NOT NULL DEFAULT 'text/html',

    -- Generation metadata
    generated_at        timestamptz,
    error_message       text,

    -- Audit
    created_at          timestamptz NOT NULL DEFAULT now(),
    created_by          uuid        NOT NULL,
    updated_at          timestamptz,
    updated_by          uuid,

    CONSTRAINT rp_pkey          PRIMARY KEY (id),
    CONSTRAINT rp_tenant_uq     UNIQUE (tenant_id, id),
    CONSTRAINT rp_status_chk    CHECK (status IN ('pending', 'generating', 'ready', 'failed')),
    CONSTRAINT rp_format_chk    CHECK (format IN ('html', 'pdf', 'xlsx')),
    CONSTRAINT rp_type_chk      CHECK (report_type IN (
        'cycle_summary', 'deviation_summary', 'certification_summary',
        'task_status', 'compliance_dashboard'
    )),
    CONSTRAINT rp_storage_chk   CHECK (
        (status IN ('pending', 'generating', 'failed')) OR storage_key IS NOT NULL
    )
);

COMMENT ON TABLE governance.report_pack IS
    'Generated report bundle for a governance cycle run. '
    'storage_key = S3/MinIO object key populated after generation. '
    'Download via GET /governance/report-packs/:id/download → presigned URL. '
    'Phase 4.4: HTML stub. Upgrades to PDF after Phase 5.1 renderer ships.';
COMMENT ON COLUMN governance.report_pack.storage_key IS
    'S3/MinIO object key. Format: reports/{tenantId}/{cycleRunId}/{id}.{format}. '
    'NULL while status is pending/generating/failed.';
COMMENT ON COLUMN governance.report_pack.format IS
    'Output format. html (Phase 4.4 stub), pdf (Phase 5.1+), xlsx (optional).';


-- ============================================================================
-- §CCERT-IMM  Certification snapshot immutability (Phase 6 hardening)
-- ============================================================================
-- Once a cycle_certification reaches CERTIFIED, ATTESTED, or SUPERSEDED status,
-- snapshot_payload and content_hash are frozen. Any UPDATE to those columns
-- raises an exception — create a superseding certification instead.
-- The status column may still advance (CERTIFIED → ATTESTED → SUPERSEDED);
-- only the evidence payload columns are locked.
-- ============================================================================

CREATE OR REPLACE FUNCTION governance.trg_certification_snapshot_immutable()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF OLD.status IN ('CERTIFIED', 'ATTESTED', 'SUPERSEDED') THEN
        IF OLD.snapshot_payload IS DISTINCT FROM NEW.snapshot_payload THEN
            RAISE EXCEPTION
                'governance.cycle_certification.snapshot_payload is immutable once '
                'status = %. Create a superseding certification instead.',
                OLD.status
            USING ERRCODE = 'object_not_in_prerequisite_state';
        END IF;
        IF OLD.content_hash IS DISTINCT FROM NEW.content_hash THEN
            RAISE EXCEPTION
                'governance.cycle_certification.content_hash is immutable once '
                'status = %.',
                OLD.status
            USING ERRCODE = 'object_not_in_prerequisite_state';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_ccert_snapshot_immutable ON governance.cycle_certification;
CREATE TRIGGER trg_ccert_snapshot_immutable
    BEFORE UPDATE ON governance.cycle_certification
    FOR EACH ROW EXECUTE FUNCTION governance.trg_certification_snapshot_immutable();

COMMENT ON FUNCTION governance.trg_certification_snapshot_immutable() IS
    'Prevents modification of snapshot_payload and content_hash once a '
    'cycle_certification has reached CERTIFIED, ATTESTED, or SUPERSEDED. '
    'Evidence integrity: once signed off the audit evidence is frozen in place.';


-- ============================================================================
-- §LH  governance.legal_hold — legal hold registry
-- ============================================================================
-- Active holds block partition archive workers from detaching / moving
-- partitions to cold storage. The archive worker cross-references
-- governance.legal_hold before any DETACH CONCURRENTLY operation.
--
-- Lifecycle:
--   legal_hold.status: active → released | expired

CREATE TABLE IF NOT EXISTS governance.legal_hold (
    -- Identity
    id                  uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id           uuid        NOT NULL,

    -- Hold definition
    hold_name           varchar(200) NOT NULL,
    hold_code           varchar(60)  NOT NULL,           -- slugified, used in UI + API
    description         text,
    custodian_id        uuid         NOT NULL,           -- principal_id of hold owner

    -- Scope (at least one scope dimension must be set)
    scope_entity_type   varchar(50),                     -- e.g. 'journal_entry', NULL = all types
    scope_entity_id_lo  uuid,                            -- optional range start (entity id)
    scope_entity_id_hi  uuid,                            -- optional range end  (entity id)
    scope_date_from     timestamptz,                     -- inclusive start of time range
    scope_date_to       timestamptz,                     -- inclusive end of time range
    scope_log_schemas   text[],                          -- NULL = all log schemas; otherwise ['log','audit']

    -- Lifecycle
    status              text         NOT NULL DEFAULT 'active',

    -- Effectivity
    effective_from      timestamptz  NOT NULL DEFAULT now(),
    effective_to        timestamptz,                     -- NULL = indefinite

    -- Release
    release_date        timestamptz,
    release_reason      text,
    released_by         uuid,

    -- Audit
    created_at          timestamptz  NOT NULL DEFAULT now(),
    created_by          uuid         NOT NULL,
    updated_at          timestamptz,
    updated_by          uuid,

    CONSTRAINT lh_pkey          PRIMARY KEY (id),
    CONSTRAINT lh_tenant_uq     UNIQUE (tenant_id, id),
    CONSTRAINT lh_code_uq       UNIQUE (tenant_id, hold_code),
    CONSTRAINT lh_status_chk    CHECK (status IN ('active', 'released', 'expired')),
    CONSTRAINT lh_scope_chk     CHECK (
        scope_entity_type IS NOT NULL
        OR scope_date_from IS NOT NULL
        OR scope_log_schemas IS NOT NULL
    ),
    CONSTRAINT lh_date_range_chk CHECK (
        scope_date_from IS NULL OR scope_date_to IS NULL OR scope_date_from <= scope_date_to
    ),
    CONSTRAINT lh_effectivity_chk CHECK (
        effective_to IS NULL OR effective_from <= effective_to
    ),
    CONSTRAINT lh_release_chk   CHECK (
        (status <> 'released') OR (release_date IS NOT NULL AND released_by IS NOT NULL AND release_reason IS NOT NULL)
    )
);

COMMENT ON TABLE governance.legal_hold IS
    'Legal hold registry. Active holds block the partition archive worker from '
    'detaching / archiving log partitions whose time range overlaps the hold scope. '
    'status: active (blocking) → released (manually lifted) | expired (effective_to passed).';

COMMENT ON COLUMN governance.legal_hold.hold_code IS
    'Slugified hold identifier. Used in API paths and UI labels. '
    'Must be unique per tenant. Pattern: [a-z0-9-]{1,60}.';

COMMENT ON COLUMN governance.legal_hold.scope_entity_type IS
    'If set, only audit rows for this entity type are in scope. '
    'NULL means all entity types are in scope.';

COMMENT ON COLUMN governance.legal_hold.scope_log_schemas IS
    'Array of log schema names covered by this hold (e.g. {''log'',''audit''}). '
    'NULL means all log schemas.';

COMMENT ON COLUMN governance.legal_hold.custodian_id IS
    'Principal ID of the responsible custodian. Must be a valid master.principal.id. '
    'No FK enforced here — principal may be deleted; legal hold remains.';


-- ============================================================================
-- §LHM  governance.legal_hold_manifest — partitions blocked by a hold
-- ============================================================================
-- Populated by the archive worker when it encounters a partition that
-- would be archived but is blocked by an active hold.
-- Also pre-populated via POST /api/governance/legal-holds/:id/manifest/refresh.

CREATE TABLE IF NOT EXISTS governance.legal_hold_manifest (
    -- Identity
    id                  uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id           uuid        NOT NULL,

    -- Parent hold
    legal_hold_id       uuid        NOT NULL,

    -- Blocked partition
    partition_schema    text        NOT NULL,            -- e.g. 'log'
    partition_table     text        NOT NULL,            -- e.g. 'audit_log_2024_01'
    partition_range_lo  timestamptz NOT NULL,            -- inclusive
    partition_range_hi  timestamptz NOT NULL,            -- exclusive

    -- Status
    is_released         boolean     NOT NULL DEFAULT false,
    released_at         timestamptz,

    -- Audit
    created_at          timestamptz NOT NULL DEFAULT now(),
    created_by          uuid        NOT NULL,
    updated_at          timestamptz,
    updated_by          uuid,

    CONSTRAINT lhm_pkey          PRIMARY KEY (id),
    CONSTRAINT lhm_tenant_uq     UNIQUE (tenant_id, id),
    CONSTRAINT lhm_unique        UNIQUE (tenant_id, legal_hold_id, partition_schema, partition_table),
    CONSTRAINT lhm_hold_fk       FOREIGN KEY (tenant_id, legal_hold_id)
        REFERENCES governance.legal_hold (tenant_id, id)
        ON DELETE CASCADE,
    CONSTRAINT lhm_range_chk     CHECK (partition_range_lo < partition_range_hi),
    CONSTRAINT lhm_release_chk   CHECK (
        (is_released = false AND released_at IS NULL)
        OR (is_released = true AND released_at IS NOT NULL)
    )
);

COMMENT ON TABLE governance.legal_hold_manifest IS
    'Inventory of log partitions blocked by a legal hold. '
    'One row per (hold, partition). Populated by the archive worker or on-demand '
    'via POST /api/governance/legal-holds/:id/manifest/refresh. '
    'is_released is set true when the hold is lifted and the partition is free to archive. '
    'CASCADE DELETE from legal_hold cleans up manifest rows when hold is hard-deleted '
    '(soft-delete via status=released is preferred for audit trail).';

CREATE INDEX IF NOT EXISTS lh_tenant_status_idx
    ON governance.legal_hold (tenant_id, status)
    WHERE status = 'active';

CREATE INDEX IF NOT EXISTS lhm_hold_idx
    ON governance.legal_hold_manifest (tenant_id, legal_hold_id);

CREATE INDEX IF NOT EXISTS lhm_partition_idx
    ON governance.legal_hold_manifest (partition_schema, partition_table, is_released);

-- FILE: /d/Products/athyper/server/db/sql/04_tables/009_snapshot.sql
-- 04_tables/009_snapshot.sql
-- Scope: Snapshot schema — immutable compiled versions and pre-computed route maps.
-- Depends on: 01_schemas, 04_tables/002_control.sql, 04_tables/003f_master_cms.sql
--
-- Tables (snapshot schema, all append-only unless noted):
--   §1  lifecycle_version         — frozen compiled lifecycle definition (append-only)
--   §2  lifecycle_route           — full compiled route graph per lifecycle (mutable — recompiled in-place)
--   §3  status_route              — simplified transition map for Pattern A/B entities (mutable)
--   §4  entity_compiled           — pre-compiled entity version snapshot (append-only)
--   §5  entity_compiled_overlay   — compiled overlay delta for an entity version (append-only)
--   §6  template_version          — immutable frozen template content per version (append-only)
--   §7  content_item_version      — immutable body snapshot per CMS content item (append-only)
--
-- FK constraints  → 06_constraints/009_snapshot.sql + 06_constraints/011_cms.sql
-- Indexes         → 07_indexes/009_snapshot.sql
-- Triggers        → 09_triggers/009_snapshot.sql
-- RLS             → 11_rls_policies/009_snapshot.sql


-- =============================================================================
-- §1  snapshot.lifecycle_version — frozen immutable compiled lifecycle definition
-- =============================================================================
-- Immutable snapshot of a lifecycle at a point in time.
-- workflow_instance pins to lifecycle_version_id for version-pinned in-flight execution.
-- Append-only: UPDATE and DELETE blocked by trg_lv_immutable trigger.

CREATE TABLE IF NOT EXISTS snapshot.lifecycle_version (
    -- Identity
    id              uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid        NOT NULL,

    -- Parent reference
    lifecycle_id    uuid        NOT NULL,

    -- Version
    version         integer     NOT NULL,

    -- Compiled definition (denormalised from control.lifecycle + child tables)
    -- {states: [{id, code, name, is_terminal, is_initial, sort_order, config}],
    --  transitions: [{id, from, to, operation_code, is_active, config}],
    --  hooks: [{id, timing, action, config, origin, contract_role, safety_level, sort_order}],
    --  gates: {transition_id: {required_operations, conditions, threshold_rules}},
    --  timers: {state_code: {policy_code, rules: [...]}}}
    definition      jsonb       NOT NULL,

    -- Source hash (matches lifecycle.definition_hash at compile time)
    compiled_hash   text        NOT NULL,

    -- Audit (append-only — no updated_at)
    created_at      timestamptz NOT NULL DEFAULT now(),
    created_by      uuid        NOT NULL,

    CONSTRAINT lv_pkey          PRIMARY KEY (id),
    CONSTRAINT lv_tenant_id_uq  UNIQUE (tenant_id, id),
    CONSTRAINT lv_version_uq    UNIQUE (tenant_id, lifecycle_id, version),
    CONSTRAINT lv_version_chk   CHECK (version >= 1),
    CONSTRAINT lv_definition_chk CHECK (jsonb_typeof(definition) = 'object'),
    CONSTRAINT lv_hash_chk      CHECK (length(compiled_hash) >= 64)
);

COMMENT ON TABLE snapshot.lifecycle_version IS
    'Immutable compiled snapshots of lifecycle definitions. '
    'document.workflow_instance pins to lifecycle_version_id — '
    'in-flight workflows continue on the version active when they started. '
    'advance_workflow_state() reads definition jsonb (one row, no joins). '
    'Append-only: trg_lv_immutable blocks UPDATE and DELETE.';
COMMENT ON COLUMN snapshot.lifecycle_version.definition IS
    'Fully denormalised lifecycle definition. Structure: '
    '{states:[{id,code,name,is_terminal,is_initial,sort_order,config}], '
    'transitions:[{id,from,to,operation_code,is_active,config}], '
    'hooks:[{id,timing,action,config,origin,contract_role,safety_level,sort_order}], '
    'gates:{transition_id:{required_operations,conditions,threshold_rules}}, '
    'timers:{state_code:{policy_code,rules:[...]}}}.';


-- =============================================================================
-- §2  snapshot.lifecycle_route — full compiled route map per lifecycle
-- =============================================================================
-- Pre-computed traversal graph: which states are reachable from each state.
-- Used by UI to visualise "what can happen next" and by navigation helpers.
-- Mutable: recompiled in-place (UNIQUE lifecycle_id) when definition changes.

CREATE TABLE IF NOT EXISTS snapshot.lifecycle_route (
    -- Identity
    id              uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid        NOT NULL,

    -- Parent reference
    lifecycle_id    uuid        NOT NULL,

    -- Compiled route graph
    -- {reachable_from: {state_code: [reachable_state_codes]},
    --  shortest_paths: {from_code: {to_code: [path_codes]}},
    --  terminal_states: [state_codes],
    --  initial_state: state_code}
    compiled_json   jsonb       NOT NULL,
    compiled_hash   text        NOT NULL,

    -- Audit (append-only — recompiled by replace, no in-place UPDATE)
    created_at      timestamptz NOT NULL DEFAULT now(),
    created_by      uuid        NOT NULL,

    CONSTRAINT lr_pkey          PRIMARY KEY (id),
    CONSTRAINT lr_lifecycle_uq  UNIQUE NULLS NOT DISTINCT (tenant_id, lifecycle_id),
    CONSTRAINT lr_json_chk      CHECK (jsonb_typeof(compiled_json) = 'object'),
    CONSTRAINT lr_hash_chk      CHECK (length(compiled_hash) >= 64)
);

COMMENT ON TABLE snapshot.lifecycle_route IS
    'Pre-compiled full route graph for a lifecycle. '
    'Used by UI to render ''what happens next'' state visualisation. '
    'Recompiled by fn_lifecycle_child_changed when definition changes. '
    'UNIQUE(tenant_id, lifecycle_id) — one route map per lifecycle.';


-- =============================================================================
-- §3  snapshot.status_route — simplified route for Pattern A/B entities
-- =============================================================================
-- One row per (tenant, entity_name). Flat allowed-transitions map.
-- Used by control.validate_status_transition() for O(1) status update validation.
-- Used by control.guard_terminal_immutability() to block edits on terminal records.
-- Used by control.guard_deletable_states() to block DELETE on non-draft records.

CREATE TABLE IF NOT EXISTS snapshot.status_route (
    -- Identity
    id              uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid        NOT NULL,
    entity_name     text        NOT NULL,

    -- Compiled route (flat map for O(1) lookups)
    -- {allowed_transitions: {from_status: [to_statuses]},
    --  terminal_states: [status_codes],
    --  deletable_states: [status_codes],
    --  initial_state: status_code,
    --  all_states: [status_codes]}
    compiled_json   jsonb       NOT NULL,
    compiled_hash   text        NOT NULL,

    -- Audit (mutable — recompiled in-place)
    created_at      timestamptz NOT NULL DEFAULT now(),
    created_by      uuid        NOT NULL,
    updated_at      timestamptz,
    updated_by      uuid,

    CONSTRAINT sr_pkey      PRIMARY KEY (id),
    CONSTRAINT sr_entity_uq UNIQUE (tenant_id, entity_name),
    CONSTRAINT sr_entity_chk CHECK (btrim(entity_name) <> ''),
    CONSTRAINT sr_json_chk  CHECK (jsonb_typeof(compiled_json) = 'object'),
    CONSTRAINT sr_hash_chk  CHECK (length(compiled_hash) >= 64)
);

COMMENT ON TABLE snapshot.status_route IS
    'Simplified compiled status transition map for Pattern A/B entities. '
    'One row per (tenant, entity_name) — fastest possible lookup for status validation. '
    'Read by control.validate_status_transition() on every entity status UPDATE. '
    'Read by control.guard_terminal_immutability() to block field edits. '
    'Read by control.guard_deletable_states() to block DELETE. '
    'Recompiled by snapshot.compile_status_route() when lifecycle definition changes. '
    'updated_at/updated_by: mutable (recompiled in-place, not appended).';


-- =============================================================================
-- §4  snapshot.entity_compiled — pre-compiled entity version snapshot
-- =============================================================================
-- Read-only after creation: compile function creates new rows, never updates.
-- Append-only: trg_fn_ec_immutable blocks UPDATE and DELETE.

CREATE TABLE IF NOT EXISTS snapshot.entity_compiled (
    -- Identity
    id                  uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id           uuid        NOT NULL,

    -- Parent reference
    entity_version_id   uuid        NOT NULL,

    -- Compiled output
    compiled_json       jsonb       NOT NULL,
    compiled_hash       text        NOT NULL,

    -- Compliance lint results
    compliance_report   jsonb       NOT NULL DEFAULT '{}',
    compliance_score    numeric(5,2),

    -- Audit (append-only — no updated_at)
    created_at          timestamptz NOT NULL DEFAULT now(),
    created_by          uuid        NOT NULL,

    CONSTRAINT ec_pkey          PRIMARY KEY (id),
    CONSTRAINT ec_version_uq    UNIQUE (entity_version_id),
    CONSTRAINT ec_hash_chk      CHECK (length(compiled_hash) >= 64),
    CONSTRAINT ec_score_chk     CHECK (compliance_score IS NULL OR compliance_score BETWEEN 0 AND 100),
    CONSTRAINT ec_json_chk      CHECK (jsonb_typeof(compiled_json) = 'object'),
    CONSTRAINT ec_report_chk    CHECK (jsonb_typeof(compliance_report) = 'object')
);

COMMENT ON TABLE snapshot.entity_compiled IS
    'Pre-compiled entity version snapshot for fast API serving. '
    'Append-only — trg_fn_ec_immutable blocks UPDATE/DELETE. '
    'UNIQUE(entity_version_id) — one compiled snapshot per version. '
    'compliance_score: 0–100 linting quality score.';


-- =============================================================================
-- §5  snapshot.entity_compiled_overlay — compiled overlay delta
-- =============================================================================
-- Diff applied to entity_compiled for a specific overlay set.
-- Enables overlay rendering without re-compiling the base snapshot.
-- Append-only.

CREATE TABLE IF NOT EXISTS snapshot.entity_compiled_overlay (
    -- Identity
    id                  uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id           uuid        NOT NULL,

    -- Parent reference
    entity_version_id   uuid        NOT NULL,

    -- Which overlays are included in this compilation
    overlay_set         jsonb       NOT NULL,   -- [overlay_id, ...]

    -- Compiled delta
    compiled_json       jsonb       NOT NULL,
    compiled_hash       text        NOT NULL,

    -- Audit (append-only — no updated_at)
    created_at          timestamptz NOT NULL DEFAULT now(),
    created_by          uuid        NOT NULL,

    CONSTRAINT eco_pkey     PRIMARY KEY (id),
    CONSTRAINT eco_hash_chk CHECK (length(compiled_hash) >= 64),
    CONSTRAINT eco_set_chk  CHECK (jsonb_typeof(overlay_set) = 'array'),
    CONSTRAINT eco_json_chk CHECK (jsonb_typeof(compiled_json) = 'object')
);

COMMENT ON TABLE snapshot.entity_compiled_overlay IS
    'Compiled overlay delta for a specific entity version + overlay set. '
    'Append-only. Applied on top of snapshot.entity_compiled at serve time. '
    'overlay_set: jsonb array of overlay_ids included in this compilation.';


-- =============================================================================
-- §6  snapshot.template_version — immutable frozen template content per version
-- =============================================================================
-- Created once — UPDATE and DELETE blocked by trg_fn_template_version_immutable.
-- btree_gist extension required for the GiST temporal index (00_extensions).

CREATE TABLE IF NOT EXISTS snapshot.template_version (
    -- Identity
    id              uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id       uuid        NOT NULL,

    -- Parent reference
    template_id     uuid        NOT NULL,
    version         integer     NOT NULL,

    -- Content (at least one of html / json must be NOT NULL)
    content_html    text,
    content_json    jsonb,
    header_html     text,
    footer_html     text,
    styles_css      text,

    -- Schema & assets
    variables_schema    jsonb,
    assets_manifest     jsonb,

    -- Integrity
    checksum        text        NOT NULL,

    -- Effective date window for "which version on date X?" queries
    effective_from  date,
    effective_to    date,

    -- Audit (append-only — no updated_at)
    created_at      timestamptz NOT NULL DEFAULT now(),
    created_by      uuid        NOT NULL,

    CONSTRAINT template_version_pkey         PRIMARY KEY (id),
    CONSTRAINT template_version_tenant_id_uq UNIQUE (tenant_id, id),
    CONSTRAINT template_version_checksum_uq  UNIQUE (tenant_id, template_id, checksum),
    CONSTRAINT template_version_version_pos  CHECK (version >= 1),
    CONSTRAINT template_version_has_content  CHECK (content_html IS NOT NULL OR content_json IS NOT NULL),
    CONSTRAINT template_version_date_order   CHECK (
        effective_to IS NULL OR effective_from IS NULL OR effective_to >= effective_from),
    CONSTRAINT template_version_checksum_chk CHECK (btrim(checksum) <> '')
    -- Circular FK from master.template.current_version_id → 06_constraints/009_snapshot.sql
    -- (DEFERRABLE INITIALLY DEFERRED)
);

COMMENT ON TABLE snapshot.template_version IS
    'Immutable point-in-time snapshot of template content per version. '
    'UPDATE and DELETE blocked by trg_fn_template_version_immutable trigger. '
    'GiST temporal index supports ''which version was effective on date X?'' queries.';
COMMENT ON COLUMN snapshot.template_version.checksum IS
    'SHA-256 or similar hash of content. Unique per (tenant, template) — prevents '
    'duplicate version content being published.';
COMMENT ON COLUMN snapshot.template_version.variables_schema IS
    'JSON Schema for template variables. Validated by fn_validate_variables_schema().';


-- =============================================================================
-- §7  snapshot.content_item_version — immutable body snapshot per CMS content item
-- =============================================================================
-- One row per (tenant, content_item, version). Append-only.
-- checksum prevents saving an identical body as a new version number.
-- master.content_item.current_version_id points to the active row.
-- UPDATE and DELETE blocked by snapshot.trg_content_item_version_immutable (09_triggers/011_cms.sql).
-- FKs → 06_constraints/011_cms.sql

CREATE TABLE IF NOT EXISTS snapshot.content_item_version (
    -- Identity
    id                  uuid        NOT NULL DEFAULT shared.uuidv7(),
    tenant_id           uuid        NOT NULL,

    -- Parent reference
    content_item_id     uuid        NOT NULL,
    version             integer     NOT NULL,

    -- Body
    body_json           jsonb       NOT NULL,
    body_format         text        NOT NULL DEFAULT 'slate',

    -- Metadata
    change_summary      text,
    checksum            text        NOT NULL,

    -- Audit (append-only — no updated_at)
    created_at          timestamptz NOT NULL DEFAULT now(),
    created_by          uuid        NOT NULL,

    CONSTRAINT civ_pkey             PRIMARY KEY (id),
    CONSTRAINT civ_tenant_id_uq     UNIQUE (tenant_id, id),
    CONSTRAINT civ_version_uq       UNIQUE (tenant_id, content_item_id, version),
    CONSTRAINT civ_checksum_uq      UNIQUE (tenant_id, content_item_id, checksum),
    CONSTRAINT civ_version_pos      CHECK (version >= 1),
    CONSTRAINT civ_checksum_chk     CHECK (btrim(checksum) <> ''),
    CONSTRAINT civ_body_format_chk  CHECK (body_format IN ('slate','prosemirror','html','markdown'))
    -- FKs (tenant, content_item, principal) → 06_constraints/011_cms.sql
    -- Circular FK from master.content_item.current_version_id → 06_constraints/011_cms.sql
);

COMMENT ON TABLE snapshot.content_item_version IS
    'Immutable body snapshot per content item version. '
    'UPDATE and DELETE blocked by snapshot.trg_content_item_version_immutable trigger. '
    'Pattern mirrors snapshot.template_version. '
    'checksum prevents saving an identical body under a new version number.';
COMMENT ON COLUMN snapshot.content_item_version.version IS
    'Monotonically increasing per (tenant_id, content_item_id). Starts at 1.';
COMMENT ON COLUMN snapshot.content_item_version.body_json IS
    'Rich-text document tree. Format declared in body_format.';
COMMENT ON COLUMN snapshot.content_item_version.body_format IS
    'Sealed: slate | prosemirror | html | markdown.';
COMMENT ON COLUMN snapshot.content_item_version.checksum IS
    'SHA-256 of body_json. Unique per (tenant, content_item) — prevents '
    'saving a duplicate body as a new version.';

-- FILE: /d/Products/athyper/server/db/sql/04_tables/010_aggregate.sql
-- 04_tables/010_aggregate.sql
-- Depends on: 01_schemas, 03_bootstrap_functions (shared.uuidv7)
-- Aggregate schema tables: pre-computed summaries materialized from ledger movements.

-- ── aggregate.tax_credit_summary ─────────────────────────────────────────────
-- Period-level tax position snapshot materialized from ledger.tax_credit_movement.
-- Rebuildable: last_rebuilt_at tracks freshness.
-- Filing lifecycle: draft → posted → filed → closed.
CREATE TABLE IF NOT EXISTS aggregate.tax_credit_summary (
    -- Identity
    id                  uuid            NOT NULL DEFAULT shared.uuidv7(),
    tenant_id           uuid            NOT NULL,

    -- Table-specific
    company_code_id     uuid            NOT NULL,
    jurisdiction_id     uuid            NOT NULL,
    tax_type_id         uuid            NOT NULL,
    book_id             uuid            NOT NULL,
    fiscal_year         smallint        NOT NULL,
    period_number       smallint        NOT NULL,
    -- Aggregated balances (computed from movements)
    input_credits       numeric(18,4)   NOT NULL DEFAULT 0,
    output_liability    numeric(18,4)   NOT NULL DEFAULT 0,
    net_position        numeric(18,4)   GENERATED ALWAYS AS (input_credits - output_liability) STORED,
    wht_deducted        numeric(18,4)   NOT NULL DEFAULT 0,
    wht_suffered        numeric(18,4)   NOT NULL DEFAULT 0,
    adjustment_total    numeric(18,4)   NOT NULL DEFAULT 0,
    carry_forward_in    numeric(18,4)   NOT NULL DEFAULT 0,
    movement_count      integer         NOT NULL DEFAULT 0,
    currency_code       character(3)    NOT NULL,
    -- Filing lifecycle
    is_reconciled       boolean         NOT NULL DEFAULT false,
    reconciled_at       timestamptz,
    reconciled_by       uuid,
    filed_at            timestamptz,
    filing_reference    text,
    -- Rebuild tracking
    last_rebuilt_at     timestamptz     NOT NULL DEFAULT now(),
    version             integer         NOT NULL DEFAULT 1,

    -- Lifecycle
    status              text            NOT NULL DEFAULT 'draft',
    posted_at           timestamptz,
    posted_by           uuid,

    -- Audit
    created_at          timestamptz     NOT NULL DEFAULT now(),
    created_by          uuid            NOT NULL,
    updated_at          timestamptz,
    updated_by          uuid,

    CONSTRAINT tcs_pkey             PRIMARY KEY (id),
    CONSTRAINT tcs_tenant_id_uq     UNIQUE (tenant_id, id),
    CONSTRAINT tcs_period_uq        UNIQUE (tenant_id, company_code_id, jurisdiction_id,
                                            tax_type_id, book_id, fiscal_year, period_number),
    CONSTRAINT tcs_status_chk       CHECK (status IN ('draft','posted','filed','closed')),
    CONSTRAINT tcs_input_nonneg     CHECK (input_credits >= 0),
    CONSTRAINT tcs_output_nonneg    CHECK (output_liability >= 0),
    CONSTRAINT tcs_wht_nonneg       CHECK (wht_deducted >= 0 AND wht_suffered >= 0),
    CONSTRAINT tcs_period_chk       CHECK (period_number BETWEEN 1 AND 16)
);
COMMENT ON TABLE aggregate.tax_credit_summary IS
    'Period-level tax position snapshot in aggregate schema. '
    'Materialized from ledger.tax_credit_movement — rebuildable at any time. '
    'last_rebuilt_at tracks freshness. carry_forward_in captures prior-period balance. '
    'Filing lifecycle: draft → posted → filed → closed.';

