CREATE TRIGGER trg_scp_validate_payment_term
    BEFORE INSERT OR UPDATE OF payment_term_id ON master.company_code_supplier_profile
    FOR EACH ROW EXECUTE FUNCTION master.trg_validate_current_payment_term();

