EXCEPTION WHEN OTHERS THEN NULL; END $$;
DO $$ BEGIN
    GRANT EXECUTE ON FUNCTION master.fn_upsert_contact_link(uuid, text, uuid, text, text, text, boolean, uuid) TO athyperapp;
EXCEPTION WHEN OTHERS THEN NULL; END $$;
